export class Observation {
  constructor ({ station, temperature, text, time, icon }) {
    this.__station = station
    this.__temperature = temperature
    this.__text = text
    this.__time = time
    this.__icon = icon
  }

  get station () {
    return this.__station
  }

  get temperature () {
    return this.__temperature
  }

  get text () {
    return this.__text
  }

  get time () {
    return this.__time
  }

  get icon () {
    return this.__icon
  }
}

export class ObservationStation {
  constructor ({ id, coordinates, name, obsUrl, timeZone }) {
    this.__id = id
    this.__coordinates = coordinates
    this.__name = name
    this.__obsUrl = obsUrl
    this.__timeZone = timeZone
  }

  get id () {
    return this.__id
  }

  get coordinates () {
    return this.__coordinates
  }

  get name () {
    return this.__name
  }

  get obsUrl () {
    return this.__obsUrl
  }

  get timeZone () {
    return this.__timeZone
  }
}
