export class EsriLocation {
  constructor ({ coordinates, magicKey, name, text }) {
    this.__coordinates = coordinates
    this.__magicKey = magicKey
    this.__name = name
    this.__text = text
  }

  get coordinates () {
    return this.__coordinates
  }

  get magicKey () {
    return this.__magicKey
  }

  get name () {
    return this.__name
  }

  get text () {
    return this.__text
  }
}

export class EsriSuggestion {
  constructor ({ magicKey, text }) {
    this.__magicKey = magicKey
    this.__text = text
  }

  get magicKey () {
    return this.__magicKey
  }

  get text () {
    return this.__text
  }
}
