export class Alert {
  constructor (alert) {
    this.__id = alert.id
    this.__areaDesc = alert.areaDesc
    this.__affectedZones = alert.affectedZones
    this.__category = alert.category
    this.__certainty = alert.certainty
    this.__description = alert.description
    this.__effective = alert.effective
    this.__ends = alert.ends
    this.__eventCode = alert.eventCode
    this.__event = alert.event
    this.__expires = alert.expires
    this.__headline = alert.headline
    this.__instruction = alert.instruction
    this.__issuance = alert.issuance
    this.__messageType = alert.messageType
    this.__onset = alert.onset
    this.__response = alert.response
    this.__sender = alert.sender
    this.__senderName = alert.senderName
    this.__sent = alert.sent
    this.__status = alert.status
    this.__severity = alert.severity
    this.__urgency = alert.urgency
    this.__url = alert.url
    this.__vtec = alert.vtec
  }

  get id () {
    return this.__id
  }

  get areaDesc () {
    return this.__areaDesc
  }

  get affectedZones () {
    return this.__affectedZones
  }

  get category () {
    return this.__category
  }

  get certainty () {
    return this.__certainty
  }

  get description () {
    return this.__description
  }

  get effective () {
    return this.__effective
  }

  get ends () {
    return this.__ends
  }

  get eventCode () {
    return this.__eventCode
  }

  get event () {
    return this.__event
  }

  get expires () {
    return this.__expires
  }

  get headline () {
    return this.__headline
  }

  get instruction () {
    return this.__instruction
  }

  get issuance () {
    return this.__issuance
  }

  get messageType () {
    return this.__messageType
  }

  get onset () {
    return this.__onset
  }

  get response () {
    return this.__response
  }

  get sender () {
    return this.__sender
  }

  get senderName () {
    return this.__senderName
  }

  get sent () {
    return this.__sent
  }

  get status () {
    return this.__status
  }

  get severity () {
    return this.__severity
  }

  get urgency () {
    return this.__urgency
  }

  get url () {
    return this.__url
  }

  get vtec () {
    return this.__vtec
  }

  toString () {
    return this.__id
  }
}

export class AlertSummary {
  constructor ({ id, event, expiration, issuance, office, url, vtec, bbox }) {
    this.__id = id
    this.__event = event
    this.__expiration = expiration
    this.__issuance = issuance
    this.__office = office
    this.__url = url
    this.__vtec = vtec
    this.__bbox = bbox
    this.__zoneCount = 1
  }

  get bbox () {
    return this.__bbox
  }

  set bbox (value) {
    this.__bbox = value
  }

  get id () {
    return this.__id
  }

  get event () {
    return this.__event
  }

  get expiration () {
    return this.__expiration
  }

  get issuance () {
    return this.__issuance
  }

  get office () {
    return this.__office
  }

  get url () {
    return this.__url
  }

  get vtec () {
    return this.__vtec
  }

  get zoneCount () {
    return this.__zoneCount
  }

  incZoneCount () {
    this.__zoneCount += 1
  }

  toString () {
    return this.__id
  }
}
