import { LoadingError, ResourceLoader } from '~/cmi/loaders'
import * as log from '~/cmi/log'
import { Point } from '~/entities'

export async function loadPoint ({ apiBaseUrl, apiKey, coordinates }) {
  const url = `${apiBaseUrl}/points/${coordinates[1].toFixed(4)},${coordinates[0].toFixed(4)}`
  const options = {
    headers: {
      'Accept': 'application/geo+json'
    },
    responseType: 'json'
  }
  if (apiKey !== null) {
    options.headers['API-Key'] = apiKey
  }

  log.info(`Requesting point data for (${coordinates[1].toFixed(4)},${coordinates[0].toFixed(4)}) from ${url}`)

  const loader = new ResourceLoader()
  return loader.load(url, options, response => {
    try {
      const point = new Point({
        coordinates: response.data.geometry.coordinates,
        forecastUrl: response.data.properties.forecast,
        forecastHourlyUrl: response.data.properties.forecastHourly,
        officeUrl: response.data.properties.forecastOffice,
        stationsUrl: response.data.properties.observationStations,
        // API may return a point for a location that is invalid, check for a grid to make sure
        valid: response.data.properties.forecastGridData !== null
      })
      log.debug(`Received point data for ${response.data.geometry.coordinates}`, point)

      return point
    } catch (err) {
      throw new LoadingError(`Error reading point data for ${response.data.geometry.coordinates}`, err)
    }
  })
}


