<template>
  <i v-if="false" />
</template>

<script>
import debounce from 'debounce-promise'
import { mapGetters, mapMutations } from 'vuex'

import { loadTextProduct, loadTextProductSummary } from '~/loaders'

const DEBOUNCE_DELAY = 1000 // ms

const fetchTextProductSummary = debounce(async ({ apiBaseUrl, apiKey, productType, locationId }) => {
  return loadTextProductSummary({ apiBaseUrl, apiKey, productType, locationId })
}, DEBOUNCE_DELAY, { leading: true })

const fetchLoadTextProduct = debounce(async (url, key) => {
  return loadTextProduct(url, key)
}, DEBOUNCE_DELAY, { leading: true })

export default {
  asyncComputed: {
    product: {
      async get () {
        if (!this.station || (this.stationData && this.stationData.status === 'up')) {
          return null
        }
        const products = await fetchTextProductSummary({
          apiBaseUrl: this.apiBaseUrl,
          apiKey: this.apiKey,
          productType: 'FTM',
          locationId: this.station.substring(1)
        })

        if (products.length === 0) {
          return null
        }
        const product = await fetchLoadTextProduct(products[0].url, this.apiKey)

        return product.text
      },
      default: null
    }
  },
  computed: {
    ...mapGetters([
      'lastReloadTime'
    ]),
    ...mapGetters('persist', [
      'apiBaseUrl',
      'apiKey'
    ]),
    ...mapGetters('local', [
      'station'
    ])
  },
  watch: {
    product (value) {
      this.setStationStatus(value)
    },
    '$asyncComputed.station.exception' (value) {
      this.setStationStatusError(value)
    },
    '$asyncComputed.station.updating' (value) {
      this.setStationStatusLoading(value)
    }
  },
  methods: {
    ...mapMutations('local', [
      'setStationStatus',
      'setStationStatusError',
      'setStationStatusLoading'
    ])
  }
}
</script>
