import * as log from '~/cmi/log'
import { Location } from '~/entities'
import { Info } from 'luxon'

export default {
  namespaced: true,
  state: {
    apiKey: null,
    esriKey: null,
    favorites: [],
    // Default CMI interface to prevent error if CMI is not available
    // Functions are overridden once CMI is loaded
    cmi: {
      gotoLastFrame: () => {},
      panTo: () => {}
    },
    suppressBookmarkUntil: [],
    zoom: {
      default: 4,
      min: 3,
      max: 20,
      focus: 7
    },
    disableControls: false,
    recent: [],
    urls: {
      alerts: null,
      api: null,
      forecast: null,
      gis: null
    },
    timezone: 'local',
    metrics: {
      tile: {
        latency: {
          cache: 0,
          fast: 0,
          max: 0,
          medium: 0,
          slow: 0
        }
      }
    }
  },
  mutations: {
    apiKey (state, input) {
      state.apiKey = input
    },
    esriKey (state, input) {
      state.esriKey = input
    },
    favorites (state, input) {
      if (!Array.isArray(input) || input.find(item => !(item instanceof Location))) {
        log.error('Favorites should be an array of Location objects')
        return
      }
      state.favorites = input.map(location => ({
        id: location.id,
        coordinates: location.coordinates,
        name: location.name,
        type: location.type
      }))
    },
    cmi (state, input) {
      state.cmi = input
    },
    disableControls (state, input) {
      state.disableControls = input
    },
    suppressBookmarkUntil (state, input) {
      state.suppressBookmarkUntil = input
    },
    recent (state, input) {
      if (!Array.isArray(input) || input.find(item => !(item instanceof Location))) {
        log.error('Recent should be an array of Location objects')
        return
      }
      state.recent = input.map(location => ({
        id: location.id,
        coordinates: location.coordinates,
        name: location.name,
        type: location.type
      }))
    },
    tileMetrics (state, input) {
      state.metrics.tile = input
    },

    // URLs
    alertsBaseUrl (state, input) {
      state.urls.alerts = input
    },
    apiBaseUrl (state, input) {
      state.urls.api = input
    },
    forecastBaseUrl (state, input) {
      state.urls.forecast = input
    },
    gisBaseUrl (state, input) {
      state.urls.gis = input
    },
    timezone (state, input) {
      if (Info.isValidIANAZone(input) || input === 'local') {
        state.timezone = input
      } else {
        log.error(`Invalid timezone: ${input}. Timezone must be a valid IANA timezone string or 'local'.`)
      }
    }
  },
  actions: {
    panTo: ({ getters }, { center = null, zoom = null, duration = null } = {}) => {
      getters.cmi.panTo({ center, zoom, duration })
    },
    fitTo: ({ getters }, { bounds = null, zoom = null, duration = null } = {}) => {
      getters.cmi.fitTo({ bounds, zoom, duration })
    },
    addBookmarkSuppress ({ commit, getters }, keys = []) {
      if (!Array.isArray(keys)) {
        keys = [keys]
      }
      commit('suppressBookmarkUntil', getters.suppressBookmarkUntil.concat(keys))
    },
    removeBookmarkSuppress ({ commit, getters }, keys = []) {
      if (!Array.isArray(keys)) {
        keys = [keys]
      }
      commit('suppressBookmarkUntil', getters.suppressBookmarkUntil.filter(el => !keys.includes(el)))
    },
    trackTileMetric: ({ commit, getters }, timeInMilli = null) => {
      if (timeInMilli) {
        let tileMetrics = getters.tileMetrics
        if (timeInMilli < 50) {
          tileMetrics.latency.cache++
        } else if (timeInMilli < 750) {
          tileMetrics.latency.fast++
        } else if (timeInMilli < 1500) {
          tileMetrics.latency.medium++
        } else {
          tileMetrics.latency.slow++
        }
        tileMetrics.latency.max = Math.max(tileMetrics.latency.max, timeInMilli)
        commit('tileMetrics', tileMetrics)
      }
    }
  },
  getters: {
    apiKey: state => state.apiKey,
    esriKey: state => state.esriKey,
    alertsBaseUrl: state => state.urls.alerts,
    apiBaseUrl: state => state.urls.api,
    disableControls: state => state.disableControls,
    forecastBaseUrl: state => state.urls.forecast,
    gisBaseUrl: state => state.urls.gis,
    gisUrl: (state, getters) => workspace => {
      return workspace ? `${getters.gisBaseUrl}/${workspace}/ows` : `${getters.gisBaseUrl}/ows`
    },
    suppressBookmarkUntil: state => state.suppressBookmarkUntil,
    suppressBookmark: state => state.suppressBookmarkUntil.length > 0,
    favorites: state => state.favorites.filter(location => {
      // ignore previous esri-suggestion favorites
      return !location.hasOwnProperty('magicKey')
    }).map(location => new Location({
      id: location.id,
      coordinates: location.coordinates,
      name: location.name,
      type: location.type
    })), // get all favorites locations; have to rebuild forage into class
    cmi: state => state.cmi,
    recent: state => state.recent.filter(location => {
      // ignore previous esri-suggestion recent
      return !location.hasOwnProperty('magicKey')
    }).map(location => new Location({
      id: location.id,
      coordinates: location.coordinates,
      name: location.name,
      type: location.type
    })), // get all recent locations; have to rebuild forage into class
    tileMetrics: state => state.metrics.tile,
    timezone: state => state.timezone,
    zoom: state => state.zoom
  }
}
