<template>
  <app-panel>
    These options are for support and do not affect the map display.
    <div class="config-item">
      <span class="config-item-icon fa fa-stack-overflow" />
      Logging level
      <select
        v-model="logLevel"
        name="log-level-select"
        class="config-item-input"
      >
        <option
          v-for="level in logLevels"
          :key="level.id"
          :value="level.id"
        >
          {{ level.text }}
        </option>
      </select>
      <div
        class="config-subitem config-clickable"
        @click="onEventLoggingClick"
      >
        <span
          :class="[
            'config-item-icon',
            'fa',
            isEventLoggingEnabled ? 'fa-toggle-on' : 'fa-toggle-off'
          ]"
        />
        Event logging
      </div>
      <div
        class="config-subitem config-clickable"
        @click="onVuexLoggingClick"
      >
        <span
          :class="[
            'config-item-icon',
            'fa',
            isVuexLoggingEnabled ? 'fa-toggle-on' : 'fa-toggle-off'
          ]"
        />
        Session State logging
      </div>
    </div>
    <div class="config-item">
      <span class="config-item-icon fa fa-area-chart" />
      Metrics
      <div
        class="config-subitem"
      >
        {{ tileMetricsForLatency }}
      </div>
    </div>
    <template #buttons>
      <app-panel-button
        label="Basic"
        panel="config"
      />
    </template>
  </app-panel>
</template>

<script>
import * as log from 'loglevel'
import { mapGetters, mapActions } from 'vuex'

import AppPanel from '~/components/menu/Panel.vue'
import AppPanelButton from '~/components/menu/PanelButton.vue'

const VUEX_LOGGER = log.getLogger('vuex')

export default {
  components: {
    AppPanel,
    AppPanelButton
  },
  data () {
    return {
      logLevels: [
        { id: this.$cmi.log.levels.SILENT, text: 'Disabled' },
        { id: this.$cmi.log.levels.ERROR, text: 'Error' },
        { id: this.$cmi.log.levels.WARN, text: 'Warning' },
        { id: this.$cmi.log.levels.INFO, text: 'Info' },
        { id: this.$cmi.log.levels.DEBUG, text: 'Debug' }
      ],
      vuexLoggingEnabled: VUEX_LOGGER.getLevel() < log.levels.SILENT
    }
  },
  computed: {
    ...mapGetters('persist', [
      'tileMetrics'
    ]),
    logLevel: {
      get () { return this.$cmi.log.getLevel() },
      set (value) { this.$cmi.log.setLevel(value) }
    },
    isEventLoggingEnabled () {
      return this.$cmi.log.isEventLoggingEnabled()
    },
    isVuexLoggingEnabled: {
      get () { return this.vuexLoggingEnabled },
      set (value) {
        this.vuexLoggingEnabled = Boolean(value)
        VUEX_LOGGER.setLevel(this.vuexLoggingEnabled ? log.levels.DEBUG : log.levels.SILENT)
      }
    },
    tileMetricsForLatency () {
      const lat = this.tileMetrics.latency
      return `Tile Latency: ${this.maxLatCount(lat.cache)}|${this.maxLatCount(lat.fast)}|${this.maxLatCount(lat.medium)}|${this.maxLatCount(lat.slow)} (${lat.max})`
    }
  },
  mounted () {
    this.addPanelButton({
      label: 'Basic',
      panel: 'config'
    })
  },
  methods: {
    ...mapActions('menu', [
      'addPanelButton'
    ]),
    onEventLoggingClick () {
      this.$cmi.log.setEventLoggingEnabled(!this.isEventLoggingEnabled)
    },
    onVuexLoggingClick () {
      this.isVuexLoggingEnabled = !this.isVuexLoggingEnabled
    },
    maxLatCount (count) {
      const maxCount = 100
      return `${count % maxCount}.${parseInt(count / maxCount)}`
    }
  }
}
</script>

