<template>
  <app-panel>
    <app-panel-section
      description="Select the local radar product:"
    >
      <app-panel-item
        v-for="layer in layers"
        :key="layer.name"
        :label="layer.longText"
        @click.native="selectProduct(layer.name)"
      />
    </app-panel-section>
  </app-panel>
</template>

<script>
import { mapGetters, mapActions } from 'vuex'

import AppPanel from '../Panel.vue'
import AppPanelItem from '../PanelItem.vue'
import AppPanelSection from '~/components/menu/PanelSection.vue'

export default {
  components: {
    AppPanel,
    AppPanelItem,
    AppPanelSection
  },
  computed: {
    ...mapGetters('local', [
      'filter',
      'layers'
    ]),
    layerName: {
      get () { return this.$store.getters['local/layerName'] },
      set (value) { this.$store.commit('local/layerName', value) }
    }
  },
  methods: {
    ...mapActions('menu', [
      'closePanel'
    ]),
    selectProduct (id) {
      this.layerName = id
      if (this.$tracker) {
        this.$tracker('event', {
          action: 'local',
          label: id
        })
      }
      this.closePanel()
    }
  }
}
</script>

