<template>
  <cmi-layer-group
    v-if="nationalMap"
    id="national"
  >
    <cmi-timeline-wms
      v-for="domain in domains"
      :id="`timeline-national-${domain.layer}`"
      :key="domain.layer"
      :layer="`${domain.layer}_${nationalMap}`"
      :frame-count="mapFrames"
      :min-zoom="minZoom"
      :max-zoom="maxZoom"
      :opacity="opacity"
      :primary="domain.primary || false"
      :url="gisUrl(`${domain.layer}/${domain.layer}_${nationalMap}`)"
      :tile-size="[512,512]"
      version="1.1.1"
      :z-index="zIndex"
      @track:tile="trackTileMetric"
    />
  </cmi-layer-group>
</template>

<script>
import { mapGetters, mapActions } from 'vuex'
import { DOMAINS, MAPS } from '~/config'

export default {
  props: {
    maxZoom: {
      type: Number,
      default: 10
    },
    minZoom: {
      type: Number,
      default: 4
    },
    opacity: {
      type: Number,
      default: 0.6
    },
    zIndex: {
      type: Number,
      required: true
    }
  },
  data () {
    return {
      domains: DOMAINS,
      maps: MAPS
    }
  },
  computed: {
    ...mapGetters([
      'nationalMap'
    ]),
    ...mapGetters('persist', [
      'gisUrl'
    ]),
    mapFrames () {
      if (this.nationalMap) {
        const map = this.maps.national.find(map => map.name === this.nationalMap)
        if (map) {
          return map.frames
        }
      }
      return undefined
    }
  },
  methods: {
    ...mapActions('persist', [
      'trackTileMetric'
    ])
  }
}
</script>
