<template>
  <input
    type="button"
    :value="label"
    @click="onClick"
  >
</template>

<script>
import { mapActions } from 'vuex'

export default {
  props: {
    label: {
      type: String,
      required: true
    },
    panel: {
      type: String,
      default: null
    }
  },
  methods: {
    ...mapActions('menu', [
      'closePanel',
      'togglePanel'
    ]),
    onClick () {
      if (this.panel) {
        this.togglePanel(this.panel)
      } else {
        this.closePanel()
      }
    }
  }
}
</script>
