<template>
  <div
    :class="[
      'menu-panel-agenda-actions-item',
      panel !== null && currentPanel === panel? 'selected' : '',
      isOptionsAction ? 'menu-panel-agenda-actions-item-options' : ''
    ]"
    @click="currentPanel = panel"
  >
    <span
      v-if="icon"
      :class="[
        'menu-panel-agenda-actions-item-icon',
        iconClass
      ]"
    />
    <span
      v-if="label"
      class="menu-panel-agenda-actions-item-label"
    >
      {{ label }}
    </span>
    <template v-else-if="hasSlotLabel">
      <slot />
    </template>
    <span
      v-if="!isOptionsAction && panel !== null"
      :class="[
        'fa',
        'menu-panel-agenda-actions-item-icon',
        'menu-panel-agenda-actions-item-panel',
        currentPanel === panel ? 'menu-panel-agenda-actions-item-panel-open' : ''
      ]"
    />
  </div>
</template>

<script>
export default {
  components: {
  },
  props: {
    icon: {
      type: String,
      default: null
    },
    label: {
      type: String,
      default: null
    },
    panel: {
      type: String,
      default: null
    }
  },
  computed: {
    currentPanel: {
      get () { return this.$store.getters['menu/panel'] },
      set (input) { this.$store.dispatch('menu/togglePanel', input) }
    },
    hasSlotLabel () {
      return !!this.$slots['default'] || !!this.$scopedSlots['default']
    },
    iconClass () {
      if (this.isOptionsAction) {
        return 'fa fa-ellipsis-v'
      }
      return this.icon !== null ? this.icon : 'fa fa-circle-o-notch fa-spin'
    },
    isOptionsAction () {
      return this.panel !== null && this.panel.indexOf('options') >= 0
    }
  }
}
</script>

