  display: inline-block;
  overflow: hidden;
  vertical-align: top;
  border-bottom: 4px solid #fff;
  cursor: pointer;
  line-height: 30px;
  border-right: 1px solid #cdcdcd;
  padding: 0 5px;
  height: 30px;

  &:first-child {
    padding-left: 0;
  }

  &:not(.menu-panel-agenda-actions-item-options):last-child {
    padding-right: 0;
    border-right: none;
  }

  &.selected {
    border-bottom-color: #000;
  }

  .menu-panel-agenda-actions-item-select {
    font-size: 0.9em;
    padding: 2px;
  }

  .menu-panel-agenda-actions-item-panel {
    transition: transform 0.5s;
    font-size: 16px;
    color: #999;
    transform: rotate(0deg);
  }

  .menu-panel-agenda-actions-item-panel::before {
    content: '\f107';
  }

  .menu-panel-agenda-actions-item-panel-open {
    transform: rotate(180deg);
  }
}

.menu-panel-agenda-actions-item-label {
  vertical-align: middle;
}

.menu-panel-agenda-actions-item-icon {
  font-size: 21px;
  color: #333;
  display: inline-block;
  vertical-align: middle;

  &.wi {
    font-size: 1.4em;
  }

  &.wi::before {
    display: block;
