import deepmerge from 'deepmerge'
import VueAsyncComputed from 'vue-async-computed'

import { WFS, WMS } from './loaders'
import { FallbackProps } from './plugins'
import * as components from './components'
import * as converters from './util/converters'
import * as http from './util/http'
import * as log from './log'
import * as schema from './schema'
import * as validators from './util/validators'

const COMPONENTS = {
  'map': components.Map,
  'layer-group': components.LayerGroup,
  'timer': components.Timer,
  // controls
  'control-bar': components.ControlBar,
  'control-bar-info': components.ControlBarInfo,
  'legend': components.Legend,
  // layers
  'layer-kml': components.LayerKML,
  'layer-mapbox': components.LayerMapbox,
  'layer-osm': components.LayerOsm,
  'layer-wms': components.LayerWms,
  'layer-vector-shape': components.LayerVectorShape,
  // map features
  'map-marker': components.MapMarker,
  // timelines
  'timeline-wms': components.TimelineWms
}

const DEFAULTS = {
  componentPrefix: 'cmi-',
  instanceName: 'cmi'
}

function plugin (Vue, options = {}) {
  options = deepmerge(DEFAULTS, options)

  const validator = new schema.SchemaValidator({ schemas: [schema.SCHEMA_CMI_CONFIG] })
  validator.validate('/cmi/config', options)

  Vue.prototype[`$${options.instanceName}`] = {
    http: http,
    log: log,
    wfs: (...args) => new WFS(...args),
    wms: (...args) => new WMS(...args)
  }
  log.initialize(options.instanceName)

  const emit = Vue.prototype.$emit
  Vue.prototype.$emit = function (...args) {
    const from = this.$vnode ? this.$vnode.tag : 'Event without vnode'
    if (args.length > 1) {
      log.event(`Event "${args[0]}" from ${from}: `, ...args.slice(1))
    } else {
      log.event(`Event "${args[0]}" from ${from}`)
    }
    emit.apply(this, args)
  }

  Vue.use(VueAsyncComputed)
  Vue.use(FallbackProps)

  for (const key of Object.keys(COMPONENTS)) {
    const pluginKey = key === options.instanceName ? key : `${options.componentPrefix}${key}`
    Vue.component(pluginKey, COMPONENTS[key])
  }

  log.debug(
    'CMI initialized:' +
    `\n  Component prefix: ${options.componentPrefix}` +
    `\n  Instance name: ${options.instanceName}`
  )
}

export default plugin

export {
  components,
  converters,
  log,
  schema,
  validators,
  DEFAULTS
}
