import { DateTime } from 'luxon'
import xmldom from 'xmldom'
import xpath from 'xpath'

import * as log from '../log'
import { LoadingError, ResourceLoader } from './base'
import { HTTP } from '../util/http'
import { WmsDefinitionBuilder } from '../entities/definitions'

export class WMS {
  constructor (url, version) {
    this.__url = url
    this.__version = version
  }

  async getCapabilities () {
    const options = {
      headers: { 'Accept': 'application/xml' },
      params: {
        service: 'wms',
        version: this.__version,
        request: 'GetCapabilities'
      }
    }

    const loader = new ResourceLoader()
    return loader.load(this.__url, options, response => {
      // TODO: process into object tree
      return response.data
    })
  }

  /**
   * Fetch a list of layers.
   *
   * @return {Object[]}
   */
  async getLayers () {
    // TODO: use JSON version of GetCapabilities response
    log.debug(`Reading layers from ${this.__url}`)
    const capabilities = await this.getCapabilities()

    const doc = new xmldom.DOMParser().parseFromString(capabilities)
    const layerData = xpath.select('//WMT_MS_Capabilities/Capability/Layer/Layer', doc)
    const layers = layerData.reduce((map, layer) => {
      try {
        const name = xpath.select('string(Name)', layer)
        const title = xpath.select('string(Title)', layer)
        const description = xpath.select('string(Abstract)', layer)
        const times = xpath.select('string(Extent[@name="time"])', layer)
        const extent = xpath.select('LatLonBoundingBox', layer, true)
        const attributions = xpath.select('Attribution', layer)

        const builder = new WmsDefinitionBuilder()
        builder
          .setId(name)
          .setName(title)
          .setDescription(description)
          .setExtent([
            parseFloat(extent.getAttribute('minx')),
            parseFloat(extent.getAttribute('miny')),
            parseFloat(extent.getAttribute('maxx')),
            parseFloat(extent.getAttribute('maxy'))
          ])
          .setUrl(this.__url)
          .setVersion(this.__version)

        if (times) {
          builder.setTimes(times.split(',').map(time => DateTime.fromISO(time, { zone: 'UTC', setZone: true })))
        }

        if (attributions) {
          for (const attribution of attributions) {
            const text = xpath.select('string(Title)', attribution)
            const url = xpath.select('string(OnlineResource)', attribution)
            builder.addAttribution({ text, url })
          }
        }

        map[name] = builder.create()
      } catch (error) {
        log.warn(`Failed to read layer data: ${error.stack}\n`, new xmldom.XMLSerializer().serializeToString(layer))
      }

      return map
    }, {})
    log.debug('Found layers', layers)

    return layers
  }

  /**
   * Fetches a list of styles associated with a layer.
   *
   * @param {String} layer - the layer to query
   * @return {Object}
   */
  async getStyles (layer) {
    const options = {
      headers: { 'Accept': 'application/vnd.ogc.sld+xml' },
      params: {
        service: 'wms',
        version: this.__version,
        request: 'GetStyles',
        layers: layer
      }
    }

    const loader = new ResourceLoader()
    return loader.load(this.__url, options, response => {
      // TODO: process into object tree
      return response.data
    })
  }
}

