export class WmsGetStylesLoader extends ResourceLoader {
  constructor ({ url, layer }) {
    super()
    this.__layer = layer
    this.__url = url
  }

  async request (cancelToken) {
    log.info(`Requesting WMS GetStyles from ${this.__url}`)

    return HTTP.get(this.__url, {
      cancelToken: cancelToken,
      headers: { 'Accept': 'application/vnd.ogc.sld+xml' },
      responseType: 'text',
      params: {
        service: 'wms',
        version: this.__version,
        request: 'GetStyles',
        layers: this.__layer
      }
    })
  }

  process (response) {
    try {
      const doc = new xmldom.DOMParser().parseFromString(response.data)
      const select = xpath.useNamespaces({ sld: 'http://www.opengis.net/sld' })
      const userStyles = select('//sld:StyledLayerDescriptor/sld:NamedLayer/sld:UserStyle', doc)

      // Use the default style if one is set.
      // Otherwise, assume that the first is the one we want.
      let userStyle = userStyles[0]
      for (const userStyleChoice of userStyles) {
        const isDefault = select('number(sld:IsDefault)', userStyleChoice)
        if (isDefault) {
          userStyle = userStyleChoice
        }
      }

      const styles = select('sld:FeatureTypeStyle', userStyle).reduce((map, style) => {
        try {
          for (const rule of select('sld:Rule', style)) {
            try {
              const name = select('string(sld:Name)', rule)
              // Disregard the outline styles
              if (name !== 'outline') {
                map[name] = select('string(sld:PolygonSymbolizer/sld:Fill/sld:CssParameter)', rule)
              }
            } catch (error) {
              log.warn(`Could not read name or color for style rule: ${error.stack}\n`, rule)
            }
          }
        } catch (error) {
          log.warn('Could not read name or color for style', style)
        }

        return map
      }, {})
      log.debug(`Received styles from ${this.__url}`, styles)

      return styles
    } catch (err) {
      throw new LoadingError(`Error reading styles from ${this.__url}`, err)
    }
  }
}
