export class ForecastDay {
  constructor (...periods) {
    this.__periods = periods
    this.__date = new Date(this.__periods[0].startTime).getDate()
  }

  get name () {
    return this.__periods[0].name
  }

  get periods () {
    return this.__periods
  }

  get day () {
    return this.__periods.find(period => period.daytime === true)
  }

  get date () {
    return this.__date
  }

  get night () {
    return this.__periods.find(period => period.daytime === false)
  }

  get high () {
    return this.day ? this.day.temperature : null
  }

  get low () {
    return this.night ? this.night.temperature : null
  }
}

export class ForecastPeriod {
  constructor ({ daytime, details, name, short, temperature, startTime, endTime }) {
    this.__daytime = daytime
    this.__details = details
    this.__name = name
    this.__short = short
    this.__temperature = temperature
    this.__startTime = startTime
    this.__endTime = endTime
  }

  get daytime () {
    return this.__daytime
  }

  get details () {
    return this.__details
  }

  get name () {
    return this.__name
  }

  get short () {
    return this.__short
  }

  get temperature () {
    return this.__temperature
  }

  get startTime () {
    return this.__startTime
  }

  get endTime () {
    return this.__endTime
  }
}
