import * as converters from './converters'
import * as log from '../log'
import * as validators from './validators'

/**
 * A timer which can be used to schedule the execution of functions.
 */
export class Timer {
  /**
   * Constructor.
   *
   * The delay parameter can be an integer specifying the number of milliseconds
   * or an ISO8601 duration string.
   *
   * @param {Number|String} delay - the initial delay on the timer
   * @param {Boolean} [autostart=false] - whether to start the timer immediately upon creation
   * @param {Function[]} [listeners=[]] - listeners to notify when the timer expires
   * @param {String} [name=null] - the optional name of the timer (for logging purposes only)
   * @param {Boolean} [repeat=true] - whether the timer should loop once expired
   */
  constructor (delay, { autostart = false, listeners = [], name = null, repeat = true } = {}) {
    if (!Array.isArray(listeners)) {
      listeners = [listeners]
    }
    for (const listener of listeners) {
      if (typeof listener !== 'function') {
        throw new Error(`Listener is not a function: ${listener}`)
      }
    }

    this.delay = delay
    this.name = name
    this.__listeners = listeners
    this.__repeat = Boolean(repeat)
    this.__start = null
    this.__timer = null

    if (autostart) {
      this.start()
    }
  }

  /**
   * Returns the timer delay in milliseconds.
   *
   * @returns {Number}
   */
  get delay () {
    return this.__delay.valueOf()
  }

  /**
   * Changes the delay on the timer.
   *
   * @param {Number|String} - the new delay
   */
  set delay (value) {
    if (!validators.convertibleToDuration(value)) {
      throw new Error(`Timer delay must be an integer or ISO8601 duration; received ${value}`)
    }
    const duration = converters.convertToDuration(value)
    let delay = duration.valueOf()
    if (delay === 0) {
      throw new Error('Delay for timer cannot be zero')
    }
    this.__delay = delay

    // Check if the timer would already have expired
    if (this.__timer) {
      const now = new Date()
      const time = this.__start - now + this.__delay
      if (time <= 0) {
        this._execute()
      }
      // update the interval for loops
      if (this.__repeat) {
        this.stop()
        this.start()
      }
    }
  }

  /**
   * Returns whether or not the timer is currently running.
   *
   * @return {Boolean}
   */
  get isRunning () {
    return this.__timer !== null
  }

  /**
   * Returns the name of the timer.
   *
   * @returns {Number}
   */
  get name () {
    return this.__name
  }

  /**
   * Sets or changes the name of the timer.
   *
   * @param {String} - the new name
   */
  set name (value) {
    if (value !== null && typeof value !== 'string') {
      throw new Error('Timer name must be null or a string')
    }
    this.__name = value
  }

  /**
   * Adds a listener to the timer.
   *
   * @param {Function} listener - the listener to add
   */
  addListener (listener) {
    this.__listeners.push(listener)
  }

  /**
   * Removes a listener from the timer.
   *
   * @param {Function} listener - the listener to remove
   */
  removeListener (listener) {
    this.__listeners = this.__listeners.filter(item => item !== listener)
  }

  /**
   * Starts the timer.
   *
   * If the timer is already running, this will restart it.
   */
  start () {
    if (this.__timer) {
      log.debug(`Restarting ${this._logName}`)
      this.stop()
    } else {
      log.debug(`Starting ${this._logName}`)
    }

    this.__start = new Date()
    if (this.__repeat) {
      this.__timer = setInterval(this._execute.bind(this), this.__delay)
    } else {
      this.__timer = setTimeout(this._execute.bind(this), this.__delay)
    }
  }

  /**
   * Stops the timer.
   */
  stop () {
    if (!this.__timer) {
      return
    }

    log.debug(`Stopping ${this._logName}`)
    if (this.__repeat) {
      clearInterval(this.__timer)
    } else {
      clearTimeout(this.__timer)
    }
    this.__timer = null
  }

  /**
   * Notifies listeners when the timer expires.
   *
   * @private
   */
  _execute () {
    for (const listener of this.__listeners) {
      log.debug(`Calling listeners for ${this._logName}`)
      try {
        listener()
      } catch (err) {
        log.error(`Failed to execute listener for ${this._logName}: ${err}\n${err.stack}`)
      }
    }
    if (!this.__repeat) {
      this.__timer = null
    }
  }

  get _logName () {
    return this.__name ? `timer "${this.__name}"` : 'timer'
  }
}
