<template>
  <div
    :class="[
      'menu',
      !showMenu ? 'menu-closed' : ''
    ]"
  >
    <div
      :class="['menu-primary', menuOpen ? 'menu-primary-open' : '']"
    >
      <app-primary-agenda
        v-if="showMenu"
        :expanded="!expandSearch"
      />
      <app-primary-search
        v-if="showMenu"
        :enabled="panel==='search'"
        :expanded="expandSearch"
      />
      <app-primary-config />
    </div>
    <app-agendas v-if="showAgenda" />
    <app-panels v-if="panel" />
    <app-panel-buttons v-if="panel" />
  </div>
</template>

<script>
import AppAgendas from './Agendas.vue'
import AppPanels from './Panels.vue'
import AppPanelButtons from './PanelButtons.vue'
import AppPrimaryConfig from './primary/Config.vue'
import AppPrimarySearch from './primary/Search.vue'
import AppPrimaryAgenda from './primary/Agenda.vue'

import { mapGetters } from 'vuex'

export default {
  components: {
    AppAgendas,
    AppPanels,
    AppPanelButtons,
    AppPrimaryConfig,
    AppPrimarySearch,
    AppPrimaryAgenda
  },
  computed: {
    ...mapGetters([
      'agenda'
    ]),
    ...mapGetters('menu', {
      panel: 'panel',
      focus: 'focus',
      showMenu: 'show'
    }),
    menuOpen () {
      return this.agenda || this.panel
    },
    showAgenda () {
      return this.agenda && !['selectagenda', 'search', 'config'].find(panel => panel === this.panel) && !this.focus
    },
    expandSearch () {
      return this.agenda !== null || this.panel === 'search'
    }
  }
}
</script>

<style lang="scss" scoped>
.menu {
  position: absolute;
  top: 0;
  left: 0;
  max-width: 360px;
  width: 100%;
  max-height: 100%;
  display: flex;
  flex-direction: column;
  z-index: 500;
}

.menu-closed {
  width: auto;
}

.menu-primary {
  flex: 0;
  position: relative;
  width: 100%;
  color: #eee;
  background: #000;
  display: flex;
  justify-content: space-between;
  border-bottom-right-radius: 4px;
}

.menu-primary-open {
  border-bottom-right-radius: 0;
}
</style>
