<template>
  <div class="cmi-radar-container">
    <app-menu v-if="!disable" />
    <app-map @click="onClick" />
    <app-alert-colors-data v-if="alertColorsActive" />
    <app-alerts-extent-data v-if="alertsForExtentActive" />
    <app-alerts-point-data v-if="alertsForPointActive" />
    <app-forecast-point-data v-if="forecastPointActive" />
    <app-radar-station-status-data v-if="radarStationStatusActive" />
    <app-radar-stations-data v-if="radarStationsActive" />
  </div>
</template>

<script>
import { mapGetters } from 'vuex'

import AppAlertColorsData from '~/components/data/AlertColorsData.vue'
import AppAlertsExtentData from '~/components/data/AlertsExtentData.vue'
import AppAlertsPointData from '~/components/data/AlertsPointData.vue'
import AppForecastPointData from '~/components/data/ForecastPointData.vue'
import AppRadarStationStatusData from '~/components/data/RadarStationStatusData.vue'
import AppRadarStationsData from '~/components/data/RadarStationsData.vue'
import AppMap from '~/components/Map.vue'
import AppMenu from '~/components/menu/Menu.vue'

export default {
  name: 'App',
  components: {
    AppAlertColorsData,
    AppAlertsExtentData,
    AppAlertsPointData,
    AppForecastPointData,
    AppRadarStationStatusData,
    AppRadarStationsData,
    AppMap,
    AppMenu
  },
  computed: {
    ...mapGetters([
      'extent',
      'location'
    ]),
    ...mapGetters('alerts', [
      'lastLayerTime'
    ]),
    ...mapGetters('watchers', [
      'count'
    ]),
    ...mapGetters('menu', [
      'disable'
    ]),
    alertColorsActive () {
      return this.count('alertColors') > 0
    },
    alertsForExtentActive () {
      return this.count('alertsForExtent') > 0 && this.lastLayerTime //  && this.extent
    },
    alertsForPointActive () {
      return this.count('alertsForPoint') > 0 && this.location
    },
    forecastPointActive () {
      return this.count('forecastPoint') > 0
    },
    radarStationStatusActive () {
      return this.count('radarStationStatus') > 0
    },
    radarStationsActive () {
      return this.count('radarStations') > 0
    }
  },
  methods: {
    onClick () {
      // Intentionally removed behavior that assumes user wants to close panel on map click
    }
  }
}
</script>

<style lang="scss">
@import '../style/app.scss';

.cmi-radar-container {
  position: relative;
  display: block;
  width: 100%;
  height: $radar-cont-height;
  background: #b7f8ef;
}
</style>
