<template>
  <app-menu-option
    class="menu-item search-container"
  >
    <div
      class="search-icon icon"
      @click="togglePanel('search')"
    />
    <span
      v-if="showSelectedLocation"
      class="search-location"
      @click="editLocation"
    >
      {{ selected || '' }}
    </span>
    <span
      v-if="!showSelectedLocation && !expanded"
      class="search-label"
      @click="togglePanel('search')"
    >
      Location
    </span>
    <input
      v-show="!showSelectedLocation && expanded"
      ref="searchBox"
      v-model="criteria"
      placeholder="City, ZIP, Radar, or Common Name"
      type="text"
      class="search-input"
      @click="togglePanel('search')"
      @focus="inputFocused = true"
      @blur="inputFocused = false"
    >
    <span
      v-if="criteria"
      class="search-action-icon search-action-icon-clear"
      @click="resetCriteria"
    />
  </app-menu-option>
</template>

<script>
import { v4 as uuid } from 'uuid'
import { mapGetters, mapActions } from 'vuex'

import AppMenuOption from '../MenuOption.vue'

export default {
  components: {
    AppMenuOption
  },
  props: {
    enabled: {
      type: Boolean,
      default: false
    },
    expanded: {
      type: Boolean,
      default: false
    }
  },
  data () {
    return {
      input: '',
      inputFocused: false,
      searchBoxId: `search-box-${uuid()}`
    }
  },
  computed: {
    ...mapGetters('search', [
      'selected'
    ]),
    ...mapGetters('menu', [
      'panel'
    ]),
    criteria: {
      get () { return this.$store.getters['search/criteria'] },
      set (value) { this.$store.commit('search/criteria', value) }
    },
    showSelectedLocation () {
      return this.selected && !this.inputFocused
    }
  },
  watch: {
    enabled () {
      if (this.enabled) {
        this.focusSearchInput()
      }
    },
    panel (current, previous) {
      if (previous === 'search' && current === null) {
        this.cancelSearch()
      }
    }
  },
  methods: {
    ...mapActions('menu', [
      'closePanel',
      'togglePanel'
    ]),
    cancelSearch () {
      this.criteria = ''
      this.closePanel()
    },
    resetCriteria () {
      this.criteria = ''
      this.$refs.searchBox.focus()
    },
    focusSearchInput () {
      this.inputFocused = true
      // If location selected, need to wait until input is rendered
      this.$nextTick(function () {
        this.$refs.searchBox.focus()
      })
    },
    editLocation () {
      if (this.enabled) {
        this.focusSearchInput()
      } else {
        this.togglePanel('search')
      }
    }
  }
}
</script>

