<template>
  <app-panel>
    <app-panel-option
      v-show="!focus"
      label="Hide Menu"
      @click="onHideMenuClick"
    >
      <template #icon>
        <span class="fa fa-eye" />
      </template>
    </app-panel-option>
    <app-panel-option
      v-show="!focus"
      label="Reset Map"
      @click="onResetClick"
    >
      <template #icon>
        <span class="fa fa-undo" />
      </template>
    </app-panel-option>
    <app-panel-option
      v-show="!focus || focus === 'basemap'"
      id="basemap"
      label="Basemap"
      :expands="true"
      :default-expand="true"
    >
      <template #icon>
        <span class="fa fa-square" />
      </template>
      <select
        v-model="baseMap"
        name="map-basemap-select"
        class="config-item-input"
      >
        <option
          v-for="map in maps"
          :key="map.name"
          :value="map.name"
        >
          {{ map.text }}
        </option>
      </select>
      <input
        type="checkbox"
        class="config-item-input"
        :checked="baseMapLabels || !baseMapLabelsEnabled"
        :disabled="!baseMapLabelsEnabled"
        @change="onBaseMapLabelsClick"
      >
      Show Labels
      <br>
      <p v-if="!baseMapLabelsEnabled">
        This basemap does not support label toggle yet.
      </p>
    </app-panel-option>
    <app-panel-option
      v-show="!focus || focus === 'boundaries'"
      id="boundaries"
      label="Boundary Overlays"
      :expands="true"
      :default-expand="true"
    >
      <template #icon>
        <span class="fa fa-delicious" />
      </template>
      <div
        class="config-subitem config-clickable"
        @click="onArtccMapClick"
      >
        <span
          :class="[
            'config-item-icon',
            'fa',
            artccMapEnabled ? 'fa-toggle-on' : 'fa-toggle-off'
          ]"
        />
        Air Route Traffic Control Centers
      </div>
      <div
        class="config-subitem config-clickable"
        @click="onCountyMapClick"
      >
        <span
          :class="[
            'config-item-icon',
            'fa',
            countyMapEnabled ? 'fa-toggle-on' : 'fa-toggle-off'
          ]"
        />
        Counties
      </div>
      <div
        class="config-subitem config-clickable"
        @click="onCWAMapClick"
      >
        <span
          :class="[
            'config-item-icon',
            'fa',
            cwaMapEnabled ? 'fa-toggle-on' : 'fa-toggle-off'
          ]"
        />
        County Warning Areas
      </div>
      <div
        class="config-subitem config-clickable"
        @click="onStateMapClick"
      >
        <span
          :class="[
            'config-item-icon',
            'fa',
            stateMapEnabled ? 'fa-toggle-on' : 'fa-toggle-off'
          ]"
        />
        States
      </div>
      <div
        class="config-subitem config-clickable"
        @click="onRfcMapClick"
      >
        <span
          :class="[
            'config-item-icon',
            'fa',
            rfcMapEnabled ? 'fa-toggle-on' : 'fa-toggle-off'
          ]"
        />
        River Forecast Centers
      </div>
    </app-panel-option>
  </app-panel>
</template>

<script>
import { MAPS } from '~/config'
import { mapActions, mapGetters } from 'vuex'
import AppPanel from '~/components/menu/Panel.vue'
import AppPanelOption from '~/components/menu/PanelOption.vue'

export default {
  components: {
    AppPanel,
    AppPanelOption
  },
  data () {
    return {
      maps: MAPS.base
    }
  },
  computed: {
    ...mapGetters('menu', [
      'focus'
    ]),
    baseMap: {
      get () { return this.$store.getters.baseMap },
      set (value) {
        this.$store.commit('baseMap', value)

        if (this.$tracker) {
          this.$tracker('event', {
            action: 'config-basemap',
            label: value
          })
        }
      }
    },
    baseMapLabels: {
      get () { return this.$store.getters.baseMapLabels },
      set (value) { this.$store.commit('baseMapLabels', value) }
    },
    baseMapLabelsEnabled () {
      const activeBasemap = this.maps.find(basemap => basemap.name === this.baseMap)
      if (activeBasemap && activeBasemap.url.vector.length > 1) {
        return true
      }
      return false
    },
    artccMapEnabled: {
      get () { return this.$store.getters.artccMapEnabled },
      set (value) { this.$store.commit('artccMap', value) }
    },
    countyMapEnabled: {
      get () { return this.$store.getters.countyMapEnabled },
      set (value) { this.$store.commit('countyMap', value) }
    },
    cwaMapEnabled: {
      get () { return this.$store.getters.cwaMapEnabled },
      set (value) { this.$store.commit('cwaMap', value) }
    },
    showMenu: {
      get () { return this.$store.getters['menu/show'] },
      set (value) { this.$store.commit('menu/show', value) }
    },
    stateMapEnabled: {
      get () { return this.$store.getters.stateMapEnabled },
      set (value) { this.$store.commit('stateMap', value) }
    },
    rfcMapEnabled: {
      get () { return this.$store.getters.rfcMapEnabled },
      set (value) { this.$store.commit('rfcMap', value) }
    }
  },
  mounted () {
    this.addPanelButton({
      label: 'Advanced',
      panel: 'configadvanced'
    })
  },
  methods: {
    ...mapActions([
      'reset'
    ]),
    ...mapActions('menu', [
      'addPanelButton',
      'closePanel'
    ]),
    onBaseMapLabelsClick (event) {
      this.baseMapLabels = event.target.checked
      if (this.$tracker && this.baseMapLabels) {
        this.$tracker('event', {
          action: 'config-basemap-option',
          label: 'labels'
        })
      }
    },
    onArtccMapClick () {
      this.artccMapEnabled = !this.artccMapEnabled

      if (this.$tracker && this.artccMapEnabled) {
        this.$tracker('event', {
          action: 'config-boundary',
          label: 'artcc'
        })
      }
    },
    onCountyMapClick () {
      this.countyMapEnabled = !this.countyMapEnabled

      if (this.$tracker && this.countyMapEnabled) {
        this.$tracker('event', {
          action: 'config-boundary',
          label: 'county'
        })
      }
    },
    onCWAMapClick () {
      this.cwaMapEnabled = !this.cwaMapEnabled

      if (this.$tracker && this.cwaMapEnabled) {
        this.$tracker('event', {
          action: 'config-boundary',
          label: 'cwa'
        })
      }
    },
    onRfcMapClick () {
      this.rfcMapEnabled = !this.rfcMapEnabled

      if (this.$tracker && this.rfcMapEnabled) {
        this.$tracker('event', {
          action: 'config-boundary',
          label: 'rfc'
        })
      }
    },
    onHideMenuClick () {
      this.closePanel()
      this.showMenu = false

      if (this.$tracker) {
        this.$tracker('event', {
          action: 'config-hide'
        })
      }
    },
    onResetClick () {
      this.closePanel()

      if (this.$tracker) {
        this.$tracker('event', {
          action: 'config-reset'
        })
      }

      this.reset()
    },
    onStateMapClick () {
      this.stateMapEnabled = !this.stateMapEnabled

      if (this.$tracker && this.stateMapEnabled) {
        this.$tracker('event', {
          action: 'config-boundary',
          label: 'state'
        })
      }
    }
  }
}
</script>

