export class TextProductSummary {
  constructor ({ id, code, name, url }) {
    this.__id = id
    this.__code = code
    this.__name = name
    this.__url = url
  }

  get id () {
    return this.__id
  }

  get code () {
    return this.__code
  }

  get name () {
    return this.__name
  }

  get url () {
    return this.__url
  }
}

export class TextProduct extends TextProductSummary {
  constructor ({ id, code, name, text, url }) {
    super({ id, code, name, url })
    this.__text = text
  }

  get text () {
    return this.__text
  }
}
