import { DateTime, Duration } from 'luxon'

/**
 * Converts duration from a string or number to a Duration object.
 *
 * The value can be specified as an ISO8601 duration string or elapsed time in
 * milliseconds.  This method extends ISO8601 to recognize a leading minus for
 * a duration string.  The resulting duration will be negated.
 *
 * A null value will return an instantaneous Duration object.
 *
 * @param {Number|String} value - The duration to convert
 * @return {luxon.Duration}
 */
export function convertToDuration (value) {
  if (value === null) {
    return Duration.fromMillis(0)
  }
  if (Duration.isDuration(value)) {
    return value
  }
  if (typeof value === 'string' && !/^[0-9.]+$/.test(value)) {
    return Duration.fromISO(value)
  }
  return Duration.fromMillis(value)
}

/**
 * Converts a value to a DateTime or Duration object.
 *
 * The value can be specified as an ISO8601 timestamp or duration string.  It
 * can also be provided as a duration in milliseconds.  If specified as an
 * ISO8601 duration, an optional leading minus is permitted.  The resulting
 * duration will be negated.
 *
 * A null value will return an instantaneous Duration object.
 *
 * @param {Number|String} value - The time to convert
 * @return {luxon.DateTime|luxon.Duration}
 */
export function convertToDurationOrTime (value, forceToUTC = true) {
  if (value === null) {
    return Duration.fromMillis(0)
  }
  if (value instanceof Date) {
    return DateTime.fromJSDate(value, { zone: 'UTC' })
  }
  if (Duration.isDuration(value) || DateTime.isDateTime(value)) {
    return value
  }
  if (typeof value === 'string') {
    if (value.substring(0, 2) === '-P') {
      return Duration.fromISO(value.substring(1)).negate()
    }
    if (value.substring(0, 1) === 'P') {
      return Duration.fromISO(value)
    }
    if (!/^[0-9.]+$/.test(value)) {
      return DateTime.fromISO(value, { zone: 'UTC', setZone: forceToUTC })
    }
  }
  return Duration.fromMillis(value)
}

/**
 * Converts time from a string or number to a DateTime object.
 *
 * The value can be specified as an ISO8601 timestamp or epoch time in
 * milliseconds.
 *
 * A null value will return the current time.
 *
 * @param {Number|String} value - The time to convert
 * @return {luxon.DateTime}
 */
export function convertToTime (value, forceToUTC = true) {
  if (value === null) {
    return DateTime.utc()
  }
  if (value instanceof Date) {
    return DateTime.fromJSDate(value, { zone: 'UTC' })
  }
  if (DateTime.isDateTime(value)) {
    return value
  }
  if (typeof value === 'string' && !/^[0-9.]+$/.test(value)) {
    return DateTime.fromISO(value, { zone: 'UTC', setZone: forceToUTC })
  }
  return DateTime.fromMillis(value, { zone: 'UTC' })
}
