<template>
  <div
    :class="[
      'option',
      expanded ? 'optionExpanded' : '',
      hasFocus ? 'optionExpandedFocus' : ''
    ]"
  >
    <div
      v-if="!headless"
      :class="[
        'header',
        expanded ? 'headerExpanded' : ''
      ]"
    >
      <div
        v-if="this.$slots['icon']"
        class="icon"
        @click="onHeaderClick"
      >
        <slot name="icon" />
      </div>
      <div
        class="label"
        @click="onHeaderClick"
      >
        {{ label }}
        <span
          v-if="expands"
          :class="[
            'fa',
            'fa-angle-down',
            'actionIconExpand',
            expanded ? 'actionIconExpandExpanded' : ''
          ]"
        />
      </div>
      <div
        v-if="id"
        class="action"
        @click="toggleFocus"
      >
        <span
          :class="[
            'fa',
            'fa-sign-in',
            'actionIconFocus',
            hasFocus ? 'actionIconFocusSet' : ''
          ]"
        />
      </div>
    </div>
    <div class="content">
      <slot name="fixed" />
      <slot
        v-if="expanded"
        name="default"
      />
    </div>
  </div>
</template>

<script>
export default {
  props: {
    expands: {
      type: Boolean,
      default: false
    },
    defaultExpand: {
      type: Boolean,
      default: false
    },
    headless: {
      type: Boolean,
      default: false
    },
    label: {
      type: String,
      required: true
    },
    id: {
      type: String,
      default: null
    }
  },
  data () {
    return {
      expanded: this.defaultExpand
    }
  },
  computed: {
    focus: {
      get () { return this.$store.getters['menu/focus'] },
      set (value) { this.$store.commit('menu/focus', value) }
    },
    hasFocus () {
      return this.focus !== null && this.focus === this.id
    }
  },
  methods: {
    toggleExpand () {
      this.expanded = !this.expanded
    },
    onHeaderClick () {
      if (this.expands) {
        this.toggleExpand()
      } else {
        this.$emit('click')
      }
    },
    toggleFocus () {
      this.focus = this.hasFocus ? null : this.id
    }
  }
}
</script>

