  display: flex;
  align-items: center;
  gap: 20px;
  padding-left: 0;
  padding-top: 0;
  padding-right: 10px;
  transition: padding 0.1s ease-out;
  cursor: pointer;
}

.headerExpanded {
  padding-left: 10px;
  padding-top: 6px;
}

.header .icon {
  width: 24px;
  flex: 0 0;
  position: relative;
  top: -2px;
  font-size: 1.5em;
  text-align: center;
  vertical-align: middle;
}

.header .label {
  flex: 1 1;
}

.content {
  margin: 10px 12px;
}

div.action {
  flex: 0 0;
  font-size: 1.5em;
  cursor: pointer;
}

.actionIconFocus {
  transition: transform 0.5s;
  transform: rotate(270deg);
}

.actionIconFocusSet {
  transform: rotate(90deg);
}

.actionIconExpand {
  position: relative;
