import { LoadingError, ResourceLoader } from '~/cmi/loaders'
import * as log from '~/cmi/log'
import { EsriLocation, EsriSuggestion } from '~/entities'

const ESRI_CATEGORIES = [
  'Land Features',
  'Bay', 'Channel', 'Cove', 'Dam', 'Delta', 'Gulf', 'Lagoon', 'Lake', 'Ocean', 'Reef', 'Reservoir', 'Sea', 'Sound', 'Strait', 'Waterfall', 'Wharf', // Water Features
  'Amusement Park', 'Historical Monument', 'Landmark', 'Tourist Attraction', 'Zoo', // POI/Arts and Entertainment
  'College', // POI/Education
  'Beach', 'Campground', 'Golf Course', 'Harbor', 'Nature Reserve', 'Other Parks and Outdoors', 'Park', 'Racetrack',
  'Scenic Overlook', 'Ski Resort', 'Sports Center', 'Sports Field', 'Wildlife Reserve', // POI/Parks and Outdoors
  'Airport', 'Ferry', 'Marina', 'Pier', 'Port', 'Resort', // POI/Travel
  'Postal', 'Populated Place'
]

const ESRI_OVERRIDES = {
  '08736, Manasquan, New Jersey, USA': { x: -74.037, y: 40.1128 },
  '32899, Orlando, Florida, USA': { x: -80.6774, y: 28.6143 },
  '97003, Beaverton, Oregon, USA': { x: -122.8752489, y: 45.5050916 },
  '99734, Prudhoe Bay, Alaska, USA': { x: -148.3372, y: 70.2552 },

  'Guam, Oceania': { x: 144.74, y: 13.46 },
  'Andover, Maine, United States': { x: -70.7525, y: 44.634167 },
  'Bear Creek, Pennsylvania, United States': { x: -75.772809, y: 41.204074 },
  'Bear Creek Village, Pennsylvania, United States': { x: -75.772809, y: 41.204074 },
  'New York City, New York, United States': { x: -74.0059, y: 40.7142 },
  'Pinnacles National Monument, San Benito County,California, United States': { x: -121.147278, y: 36.47075 },
  'Pinnacles National Park, CA-146, Paicines, California': { x: -121.147278, y: 36.47075 },
  'Welcome, Maryland, United States': { x: -77.081212, y: 38.4692469 }
}

const URL_BASE = 'https://geocode.arcgis.com/arcgis/rest/services/World/GeocodeServer'
const URL_FIND = `${URL_BASE}/find`
const URL_REVERSE = `${URL_BASE}/reverseGeocode`
const URL_SUGGEST = `${URL_BASE}/suggest`

export async function loadEsriLocation ({ magicKey, text }) {
  const params = {
    f: 'json',
    text: text
  }
  if (magicKey) {
    params.magicKey = magicKey
  }

  const options = {
    headers: { 'Accept': 'application/json' },
    params: params,
    responseType: 'json'
  }

  log.info(`Requesting ESRI location geocoding for "${text}"`)

  const loader = new ResourceLoader()
  return loader.load(URL_FIND, options, response => {
    try {
      const loc = response.data.locations[0]
      const coordinates = ESRI_OVERRIDES[text] ? [
        ESRI_OVERRIDES[text].x,
        ESRI_OVERRIDES[text].y
      ] : [
        loc.feature.geometry.x,
        loc.feature.geometry.y
      ]

      const location = new EsriLocation({
        coordinates: coordinates,
        magicKey: loc.magicKey ? loc.magicKey : null,
        name: loc.name.replace(/, United States$/, ''),
        text: text
      })
      log.debug(`Received location for "${text}"`, location)

      return location
    } catch (err) {
      throw new LoadingError(`Error reading location for "${text}"`, err)
    }
  })
}

export async function loadEsriReverseGeocoding ({ latitude, longitude }) {
  const options = {
    headers: { 'Accept': 'application/json' },
    params: {
      f: 'json',
      // This forces consistency so the response is either a city or a county if not within 500m of a city (e.g. coastal)
      featureTypes: 'Locality',
      langCode: 'en-us',
      location: `${longitude},${latitude}`
    },
    responseType: 'json'
  }

  log.info(`Requesting ESRI reverse geocoding for (${latitude},${longitude})`)

  const loader = new ResourceLoader()
  return loader.load(URL_REVERSE, options, response => {
    if (response.status === 200 && response.data.error && response.data.error.code === 400) {
      log.debug(`Invalid reverse geocoding for (${latitude},${longitude})`, location)

      return new EsriLocation({
        coordinates: [0, 0],
        name: 'Unknown Location',
        text: 'Unknown Location'
      })
    }
    try {
      const location = new EsriLocation({
        coordinates: [response.data.location.x, response.data.location.y],
        name: response.data.address.Match_addr,
        text: response.data.address.LongLabel.substring(0, response.data.address.LongLabel.lastIndexOf(', USA'))
      })
      log.debug(`Received reverse geocoding for (${latitude},${longitude})`, location)

      return location
    } catch (err) {
      throw new LoadingError(`Error reading reverse geocoding for (${latitude},${longitude})`, err)
    }
  })
}

export async function loadEsriSuggestions ({ text }) {
  const options = {
    headers: { 'Accept': 'application/json' },
    params: {
      f: 'json',
      countryCode: 'USA,PRI,VIR,GUM,ASM',
      category: ESRI_CATEGORIES.join(','),
      maxSuggestions: 5,
      text: text,
      _: 1502903455655
    },
    responseType: 'json'
  }

  log.info(`Requesting ESRI location suggestions for ${text}`)

  const loader = new ResourceLoader()
  return loader.load(URL_SUGGEST, options, response => {
    try {
      const suggestions = response.data.suggestions.map(suggestion => {
        return new EsriSuggestion({
          magicKey: suggestion.magicKey,
          text: suggestion.text
        })
      })
      log.debug(`Received location suggestions for "${text}"`, suggestions)

      return suggestions
    } catch (err) {
      throw new LoadingError(`Error reading location suggestions for "${text}"`, err)
    }
  })
}
