<template>
  <div
    ref="progress"
    class="progress"
  >
    <div
      class="marker"
      :style="{ width: markerWidth + 'px', left: markerLeft + 'px' }"
    />
  </div>
</template>

<script>
export default {
  props: {
    position: {
      type: Number,
      default: 0
    },
    total: {
      type: Number,
      default: 0
    }
  },
  data () {
    return {
      progressWidth: null
    }
  },
  computed: {
    markerWidth () {
      if (this.total > 0 && this.progressWidth) {
        return (this.progressWidth / this.total)
      }

      return '0'
    },
    markerLeft () {
      if (this.position) {
        return this.markerWidth * (this.position - 1)
      }

      return '0'
    }
  },
  watch: {
    position: {
      immediate: true,
      handler () {
        // Temporary fix to manage rendering glitches
        this.handleResize()
      }
    },
    markerWidth: {
      immediate: true,
      handler () {
        if (this.markerWidth === 0) {
          this.handleResize()
        }
      }
    }
  },
  mounted: function () {
    window.addEventListener('load', this.handleResize)
    window.addEventListener('resize', this.handleResize)
  },
  beforeDestroy: function () {
    window.addEventListener('load', this.handleResize)
    window.removeEventListener('resize', this.handleResize)
  },
  methods: {
    handleResize (event) {
      if (this.$refs.progress) {
        this.progressWidth = this.$refs.progress.clientWidth
      }
    }
  }
}
</script>

<style scoped>
.progress {
  position: relative;
  width: 100%;
  height: 3px;
  background: #727171;
}

.marker {
  position: absolute;
  top: 0;
  left: 0;
  width: 1px;
  height: 3px;
  background: #ebebeb;
}
</style>
