<script>
import { mapRender } from '~/cmi/mixins/map'
import { DateTime } from 'luxon'
import Layer from './layer'
import * as log from 'loglevel'

import TileGrid from 'ol/tilegrid/TileGrid'
import TileLayer from 'ol/layer/Tile'
import TileWMS from 'ol/source/TileWMS'
import { get as getProjection, transformExtent } from 'ol/proj.js'
import { getHeight as getExtentHeight, getWidth as getExtentWidth, getTopRight as getExtentTopRight } from 'ol/extent.js'
import { DEFAULT_MAX_ZOOM, DEFAULT_TILE_SIZE } from 'ol/tilegrid/common'
import { toSize } from 'ol/size'

import * as converters from '../../util/converters'
import * as validators from '../../util/validators'

export default {
  mixins: [Layer, mapRender],
  props: {
    extent: {
      type: Array,
      default: null
    },
    id: {
      type: String,
      default: undefined
    },
    layer: {
      type: String,
      required: true
    },
    maxZoom: {
      type: Number,
      default: 10
    },
    minZoom: {
      type: Number,
      default: 0
    },
    styles: {
      type: String,
      default: null
    },
    time: {
      type: [Date, Number, Object, String],
      validator: value => validators.convertibleToTime(value),
      default: null
    },
    transition: {
      type: Number,
      default: undefined
    },
    tileSize: {
      type: Array,
      default: () => [256, 256]
    },
    url: {
      type: String,
      required: true
    },
    version: {
      type: String,
      required: true
    }
  },
  data () {
    return {
      olLayer: null,
      slots: false,
      tiles: []
    }
  },
  computed: {
    _extent () {
      if (!this.extent) {
        return undefined
      }
      return transformExtent(this.extent, 'EPSG:4326', 'EPSG:3857')
    },
    _styles () {
      if (!this.styles) {
        return undefined
      }

      return this.styles
    },
    _time () {
      if (!this.time) {
        return undefined
      }
      return converters.convertToTime(this.time).toUTC().toISO()
    },
    tileGridFactory () {
      const size = 512
      const projExtent = getProjection('EPSG:3857').getExtent()
      let resolutions = this.resolutionsFromExtent(projExtent, this.maxZoom, [size, size], 0)
      return new TileGrid({
        extent: this._extent || projExtent,
        resolutions: resolutions,
        origin: getExtentTopRight(projExtent),
        tileSize: [size, size]
      })
    }
  },
  watch: {
    _time () {
      this.updateParameters({
        TIME: this._time
      })
    },
    url () {
      this.updateParameters({
        LAYERS: this.layer
      })
      this.olLayer.getSource().setUrl(this.url)
    },
    extent () {
      this.olLayer.setExtent(this._extent)
    },
    opacity () {
      this.olLayer.setOpacity(this.opacity)
    }
  },
  created () {
    this.olLayer = new TileLayer({
      properties: {
        who: this.id
      },
      extent: this._extent,
      visible: this.visible,
      opacity: this.opacity,
      zIndex: this.zIndex,
      source: new TileWMS({
        attributions: this.attributions,
        maxZoom: this.maxZoom,
        minZoom: this.minZoom,
        tileGrid: this.tileGridFactory,
        transition: this.transition,
        url: this.url,
        params: {
          TILES: true,
          LAYERS: this.layer,
          VERSION: this.version,
          STYLES: this.styles,
          TIME: this._time
        }
      })
    })
    this.olContainer.push(this.olLayer)
    this.$emit('created')
  },
  beforeDestroy () {
    this.olContainer.remove(this.olLayer)
  },
  methods: {
    tileLoadStart (tileEvent) {
      const key = tileEvent.tile.src_
      if (!this.tiles[key]) {
        this.tiles[key] = {
          start: new Date()
        }
      } else {
        log.debug(`Found duplicate key ${key}`)
      }
    },
    tileLoadEnd (tileEvent) {
      const now = new Date()
      const key = tileEvent.tile.src_
      if (this.tiles[key]) {
        const tile = this.tiles[key]
        const loadTime = DateTime.fromJSDate(tile.start).diff(DateTime.fromJSDate(now)).negate().as('milliseconds')
        this.$emit('track:tile', loadTime)
        delete this.tiles[key]
      } else {
        log.debug('Tile loading key not found')
      }
    },
    resolutionsFromExtent (extent, maxZoom, tileSize, maxResolution) {
      maxZoom = maxZoom !== undefined ? maxZoom : DEFAULT_MAX_ZOOM

      const height = getExtentHeight(extent)
      const width = getExtentWidth(extent)

      tileSize = toSize(tileSize !== undefined ? tileSize : DEFAULT_TILE_SIZE)
      maxResolution = maxResolution > 0
        ? maxResolution
        : Math.max(width / tileSize[0], height / tileSize[1])

      const length = maxZoom + 1
      const resolutions = new Array(length)
      for (let z = 0; z < length; ++z) {
        resolutions[z] = maxResolution / Math.pow(2, z)
      }

      return resolutions
    },
    updateParameters (parameters) {
      this.olLayer.getSource().updateParams(parameters)
    }
  }
}
</script>
