import { LoadingError, ResourceLoader } from '~/cmi/loaders'
import * as log from '~/cmi/log'
import { Office } from '~/entities'

export async function loadOffice (url, key) {
  const options = {
    headers: {
      'Accept': 'application/ld+json'
    },
    responseType: 'json'
  }
  if (key !== null) {
    options.headers['API-Key'] = key
  }

  log.info(`Requesting office data from ${url}`)

  const loader = new ResourceLoader()
  return loader.load(url, options, response => {
    try {
      const office = new Office({
        id: response.data.id,
        name: response.data.name,
        url: response.data.sameAs
      })
      log.debug(`Retrieved office data for ${response.data.id}`, office)

      return office
    } catch (err) {
      throw new LoadingError(`Error reading office data from ${url}`, err)
    }
  })
}
