import * as log from '~/cmi/log'
import { MAPS } from '~/config'

function createDefaultState () {
  return {
    filter: null,
    layerName: null,
    opacity: 0.6,
    stationOpacity: 0.8,
    closestCoordinates: null, // When map is clicked, this tracks the event coordinates to find the closest station
    station: null,
    stations: {
      error: null,
      loading: false,
      value: null
    },
    stationStatus: {
      error: null,
      loading: false,
      value: null
    }
  }
}

export default {
  namespaced: true,
  state: createDefaultState(),
  mutations: {
    closestCoordinates (state, input) {
      if (input !== null && !Array.isArray(input)) {
        log.error('Invalid event coordinates for local (must be a array or null):', input)
        return
      }
      state.closestCoordinates = input
    },
    filter (state, input) {
      if (input !== null && !(input in MAPS.local)) {
        log.error('Invalid radar stations filter: ', input)
        return
      }
      state.filter = input
    },
    layerName (state, input) {
      if (input !== null && typeof (input) !== 'string') {
        log.error('Invalid local radar layer name (must be a string or null):', input)
        return
      }
      state.layerName = input
    },
    opacity (state, input) {
      state.opacity = parseFloat(input)
    },
    stationOpacity (state, input) {
      state.stationOpacity = parseFloat(input)
    },
    reset (state) {
      Object.assign(state, createDefaultState())
    },
    station (state, input) {
      if (input !== null && typeof (input) !== 'string') {
        log.error('Invalid radar station name (must be a string or null):', input)
        return
      }
      state.station = input
      // Ensure that the layer has a sane value (requires stations to be loaded)
      if (state.station && state.stations.value && state.station in state.stations.value) {
        const stationData = state.stations.value[state.station]
        if (!state.layerName || !MAPS.local[stationData.type].find(map => map.name === state.layerName)) {
          state.layerName = MAPS.local[stationData.type][0].name
        }
      }
    },
    setShowRadarStationsIcons (state, input) {
      state.showRadarStationsIcons = Boolean(input)
    },
    setStations (state, input) {
      if (typeof input !== 'object') {
        log.error('Stations must be an object; received ', input)
        return
      }
      state.stations.value = input
    },
    setStationsError (state, input) {
      if (input !== null && !(input instanceof Error)) {
        log.error('Error must be null or an instance of Error; received ', input)
        return
      }
      state.stations.error = input
    },
    setStationsLoading (state, input) {
      state.stations.loading = Boolean(input)
    },
    setStationStatus (state, input) {
      if (typeof input !== 'string') {
        log.error('Stations status must be a string; received ', input)
        return
      }
      state.stationStatus.value = input
    },
    setStationStatusError (state, input) {
      if (input !== null && !(input instanceof Error)) {
        log.error('Error must be null or an instance of Error; received ', input)
        return
      }
      state.stationStatus.error = input
    },
    setStationStatusLoading (state, input) {
      state.stationStatus.loading = Boolean(input)
    }
  },
  getters: {
    closestCoordinates: state => state.closestCoordinates,
    filter: state => state.filter,
    filters: state => Object.keys(MAPS.local),
    filteredStations: (state, getters) => {
      const filter = getters.filter
      const stations = getters.stations

      if (!stations) {
        return {}
      }

      return Object.keys(stations)
        .filter(id => filter === null || filter === stations[id].type.toUpperCase())
        .reduce((map, id) => {
          map[id] = stations[id]
          return map
        }, {})
    },
    layer: (state, getters) => {
      if (!getters.layers.find(layer => layer.name === getters.layerName)) {
        return null
      }
      return `${getters.station.toLowerCase()}_${getters.layerName}`
    },
    layerData: (state, getters) => {
      const layer = getters.layers.find(layer => layer.name === getters.layerName)
      if (layer) {
        return layer
      }
      return null
    },
    layerName: (state, getters) => {
      return state.layerName
    },
    layers: (state, getters) => {
      const stationData = getters.stationData
      if (!stationData) {
        return []
      }
      return stationData.type in MAPS.local ? MAPS.local[stationData.type] : []
    },
    opacity: state => state.opacity,
    stationOpacity: state => state.stationOpacity,
    station: state => state.station,
    stationData: (state, getters) => {
      const name = getters.station
      const stations = getters.filteredStations

      if (!name) {
        return null
      }
      return name in stations ? stations[name] : null
    },
    stations: state => state.stations.value,
    stationsError: state => state.stations.error,
    stationsLoading: state => state.stations.loading,
    stationStatus: state => state.stationStatus.value,
    stationStatusError: state => state.stationStatus.error,
    stationStatusLoading: state => state.stationStatus.loading
  }
}
