import Vue from 'vue'

import * as log from '~/cmi/log'

export default {
  namespaced: true,
  state: {
    watched: {}
  },
  mutations: {
    addWatcher (state, input) {
      if (typeof state.watched[input] === 'undefined') {
        Vue.set(state.watched, input, 0)
      }
      state.watched[input] += 1
      log.debug(`Watcher count for ${input} = ${state.watched[input]}`)
    },
    removeWatcher (state, input) {
      if (typeof state.watched[input] === 'undefined') {
        Vue.set(state.watched, input, 0)
      }
      if (state.watched[input] === 0) {
        log.warn(`removeWatcher called on ${input} with a watcher count of zero`)
      } else {
        state.watched[input] -= 1
        log.debug(`Watcher count for ${input} = ${state.watched[input]}`)
      }
    }
  },
  getters: {
    count: (state, getters) => watched => {
      if (typeof state.watched[watched] === 'undefined') {
        return 0
      }
      return state.watched[watched]
    }
  }
}
