<template>
  <cmi-layer-group
    :id="`${id} (mapbox)`"
    :z-index="zIndex"
    @created="_created"
  />
</template>

<script>
import Layer from './layer'
import { apply } from 'ol-mapbox-style'

export default {
  mixins: [Layer],
  props: {
    accessToken: {
      type: String,
      required: true
    },
    extent: {
      type: Array,
      default: undefined
    },
    maxZoom: {
      type: Number,
      default: 10
    },
    minZoom: {
      type: Number,
      default: 0
    },
    sourceId: {
      type: String,
      default: undefined
    },
    styleUrl: {
      type: String,
      required: true
    },
    useTokenWithUrl: {
      type: Boolean,
      default: false
    }
  },
  computed: {
    _styleUrlWithToken () {
      if (!this.useTokenWithUrl) {
        return this.styleUrl
      }

      const url = new URL(this.styleUrl)
      const params = new URLSearchParams(url.search)

      params.append('token', this.accessToken)
      url.search = params.toString()

      return url.toString()
    }
  },
  methods: {
    _created (group) {
      apply(group, this._styleUrlWithToken)
    }
  }
}
</script>
