<template>
  <i v-if="false" />
</template>

<script>
import debounce from 'debounce-promise'
import { mapGetters, mapMutations } from 'vuex'
import { loadAlertsForExtent } from '~/loaders'

const DEBOUNCE_DELAY = 1000 // ms

const fetchAlertsForPoint = debounce(async ({ layer, location, time, url }) => {
  return loadAlertsForExtent({ extent: [...location, ...location], layer, time, url })
}, DEBOUNCE_DELAY, { leading: true })

export default {
  asyncComputed: {
    alertsForPoint: {
      async get () {
        return fetchAlertsForPoint({
          layer: this.layer,
          location: this.location,
          time: this.lastLayerTime,
          url: this.gisUrl('wwa')
        })
      },
      shouldUpdate () {
        return this.lastLayerTime
      },
      watch: ['lastReloadTime']
    }
  },
  computed: {
    ...mapGetters([
      'location'
    ]),
    ...mapGetters('persist', [
      'gisUrl'
    ]),
    ...mapGetters('alerts', [
      'lastLayerTime',
      'layer'
    ])
  },
  watch: {
    lastLayerTime (value) {
      if (value) {
        this.setAlertsForPointLoading(true)
      }
    },
    alertsForPoint (value) {
      this.setAlertsForPoint(value)
    },
    '$asyncComputed.alertsForPoint.exception' (value) {
      this.setAlertsForPointError(value)
    },
    '$asyncComputed.alertsForPoint.updating' (value) {
      this.setAlertsForPointLoading(value)
    }
  },
  methods: {
    ...mapMutations('alerts', [
      'setAlertsForPoint',
      'setAlertsForPointError',
      'setAlertsForPointLoading'
    ])
  }
}
</script>
