<template>
  <div class="menu-panels">
    <app-panel-config v-if="panel==='config'" />
    <app-panel-config-advanced v-if="panel==='configadvanced'" />
    <app-panel-search v-if="panel==='search'" />
    <app-panel-agenda v-if="panel === 'selectagenda'" />
    <app-panel-local-status v-if="panel === 'localstatus'" />
    <app-panel-local-product v-if="panel === 'localproduct'" />
    <app-panel-alerts-extent v-if="panel === 'alertsextent'" />
    <app-panel-alerts-point v-if="panel === 'alertspoint'" />
    <app-panel-local-options v-if="panel === 'localoptions'" />
    <app-panel-national-product v-if="panel === 'nationalproduct'" />
    <app-panel-national-options v-if="panel === 'nationaloptions'" />
    <app-panel-weather-options v-if="panel === 'weatheroptions'" />
    <app-panel-forecast-point v-if="panel === 'forecastpoint'" />
  </div>
</template>

<script>
import { mapGetters } from 'vuex'

import AppPanelConfig from './panels/Config.vue'
import AppPanelConfigAdvanced from './panels/ConfigAdvanced.vue'
import AppPanelSearch from './panels/Search.vue'
import AppPanelAgenda from './panels/Agenda.vue'
import AppPanelAlertsExtent from './panels/AlertsExtent.vue'
import AppPanelAlertsPoint from './panels/AlertsPoint.vue'
import AppPanelNationalOptions from './panels/NationalOptions.vue'
import AppPanelNationalProduct from './panels/NationalProduct.vue'
import AppPanelLocalOptions from './panels/LocalOptions.vue'
import AppPanelLocalStatus from './panels/LocalStatus.vue'
import AppPanelLocalProduct from './panels/LocalProduct.vue'
import AppPanelWeatherOptions from './panels/WeatherOptions.vue'
import AppPanelForecastPoint from './panels/ForecastPoint.vue'

export default {
  components: {
    AppPanelConfig,
    AppPanelConfigAdvanced,
    AppPanelSearch,
    AppPanelAgenda,
    AppPanelAlertsExtent,
    AppPanelAlertsPoint,
    AppPanelNationalOptions,
    AppPanelNationalProduct,
    AppPanelLocalOptions,
    AppPanelLocalStatus,
    AppPanelLocalProduct,
    AppPanelWeatherOptions,
    AppPanelForecastPoint
  },
  computed: {
    ...mapGetters('menu', [
      'panel'
    ])
  },
  watch: {
    panel () {
      if (this.$tracker && this.panel !== null) {
        this.$tracker('event', {
          action: 'panel',
          label: this.panel
        })
      }
    }
  }
}
</script>

<style scoped>
.menu-panels {
  flex: 0 1 auto;
  overflow: auto;
}
</style>
