<script>
import KML from 'ol/format/KML.js'
import VectorLayer from 'ol/layer/Vector'
import VectorSource from 'ol/source/Vector'
import { mapRender } from '~/cmi/mixins/map'

export default {
  mixins: [mapRender],
  inject: {
    getOLContainer: 'getOLContainer',
    getOLMap: 'getOLMap'
  },
  props: {
    autofocus: {
      type: Boolean,
      default: false
    },
    dataProjection: {
      type: String,
      default: 'EPSG:4326'
    },
    url: {
      type: String,
      required: true
    },
    opacity: {
      type: Number,
      default: 1
    },
    fitMaxZoom: {
      type: Number,
      default: 20
    },
    fitPadding: {
      type: Array,
      default: () => [0, 0, 0, 0]
    },
    styleFunction: {
      type: Function,
      default: undefined
    },
    zIndex: {
      type: Number,
      default: 0
    }
  },
  data () {
    return {
      olLayer: null,
      // this is a data property vs computed because arrays as props (e.g. features) are not reactive
      projection: 'EPSG:3857'
    }
  },
  computed: {
    olContainer () {
      return this.getOLContainer()
    },
    olMap () {
      return this.getOLMap()
    }
  },
  watch: {
    opacity () {
      this.olLayer.setOpacity(this.opacity)
    }
  },
  created () {
    this.olLayer = new VectorLayer({
      properties: {
        who: this.id
      },
      zIndex: this.zIndex,
      source: new VectorSource({
        url: this.url,
        format: new KML({
          extractStyles: typeof this.styleFunction === 'undefined'
        })
      }),
      style: this.styleFunction
    })
    this.olContainer.push(this.olLayer)

    this.olLayer.getSource().on('featuresloadend', () => {
      this.olMap.getView().fit(this.olLayer.getSource().getExtent(), {
        maxZoom: this.fitMaxZoom,
        padding: this.fitPadding
      })
    })
    this.$emit('created')
  },
  beforeDestroy () {
    this.olContainer.remove(this.olLayer)
  }
}
</script>
