import { ResourceLoader } from './base'

export class WFS {
  constructor (url, version) {
    this.__url = url
    this.__version = version
  }

  /**
   * Does whatever this does.
   *
   * @param {String} layer - the layer to query
   * @param {Object} property - the name of the property to get values for
   * @return {String[]}
   */
  async describeFeatureType (layer, property) {
    const options = {
      headers: { 'Accept': 'application/xml' },
      params: {
        service: 'wfs',
        version: this.__version,
        request: 'DescribeFeatureType',
        typeNames: layer
      }
    }

    const loader = new ResourceLoader()
    return loader.load(this.__url, options, response => {
      // TODO: process into object tree
      return response.data
    })
  }

  async getCapabilities () {
    const options = {
      headers: { 'Accept': 'application/xml' },
      params: {
        service: 'wfs',
        version: this.__version,
        request: 'GetCapabilities'
      }
    }

    const loader = new ResourceLoader()
    return loader.load(this.__url, options, response => {
      // TODO: process into object tree
      return response.data
    })
  }

  /**
   * Fetches a GeoJSON document describing the requested feature set.
   *
   * @param {String} layer - the layer to query
   * @param {Object} params - additional query parameters for the request
   * @return {Object}
   */
  async getFeature (layer, params) {
    const options = {
      headers: { 'Accept': 'application/geo+json' },
      responseType: 'json',
      params: Object.assign({
        service: 'wfs',
        version: this.__version,
        request: 'GetFeature',
        outputFormat: 'application/json',
        typeNames: layer,
        srsName: 'EPSG:4326'
      }, params)
    }

    const loader = new ResourceLoader()
    return loader.load(this.__url, options, response => {
      return response.data
    })
  }

  /**
   * Fetches a list of values for the requested property.
   *
   * @param {String} layer - the layer to query
   * @param {Object} property - the name of the property to get values for
   * @return {String[]}
   */
  async getPropertyValue (layer, property) {
    const options = {
      headers: { 'Accept': 'application/xml' },
      params: {
        service: 'wfs',
        version: this.__version,
        request: 'GetPropertyValue',
        typeNames: layer,
        valueReference: property
      }
    }

    const loader = new ResourceLoader()
    return loader.load(this.__url, options, response => {
      // TODO: process into object tree
      return response.data
    })
  }
}
