<template>
  <app-menu-agenda title="Weather for a location">
    <app-menu-agenda-actions options-panel="weatheroptions">
      <app-menu-agenda-message v-if="message !== null">
        {{ message }}
      </app-menu-agenda-message>
      <template v-else>
        <app-menu-agenda-action-item
          :icon="observationIcon"
          panel="forecastpoint"
        >
          <template v-if="observation && observation.temperature">
            {{ observation.temperature }}&deg;<span class="scale">F</span>
          </template>
          <template v-else>
            {{ observationLabel }}
          </template>
        </app-menu-agenda-action-item>
        <!--app-actions-alerts-point /-->
        <app-menu-agenda-action-item
          :icon="alertsIcon"
          :label="alertsLabel"
          panel="alertspoint"
        />
      </template>
    </app-menu-agenda-actions>
  </app-menu-agenda>
</template>

<script>
import debounce from 'debounce-promise'
import { mapGetters } from 'vuex'
import { OBSERVATIONICON } from '~/config'
import { createWatcherMixin } from '~/components/mixins'

import AppMenuAgenda from '../Agenda.vue'
import AppMenuAgendaActions from '../AgendaActions.vue'
import AppMenuAgendaActionItem from '../AgendaActionItem.vue'
import AppMenuAgendaMessage from '../AgendaMessage.vue'

// TODO: extract loaders into data component
import {
  loadObservation,
  loadObservationStations
} from '~/loaders'

const DEBOUNCE_DELAY = 1000 // ms

const fetchObservation = debounce(async function ({ url, key }) {
  // TODO: loop through obs till we find one that's "good"
  return loadObservation(url, key)
}, DEBOUNCE_DELAY, { leading: true })

const fetchObservationStations = debounce(async function ({ url, key }) {
  return loadObservationStations(url, key)
}, DEBOUNCE_DELAY, { leading: true })

export default {
  components: {
    AppMenuAgenda,
    AppMenuAgendaActions,
    AppMenuAgendaActionItem,
    AppMenuAgendaMessage
  },
  mixins: [
    createWatcherMixin('alertsForPoint'),
    createWatcherMixin('forecastPoint')
  ],
  asyncComputed: {
    stations: {
      async get () {
        if (!this.forecastPoint || !this.forecastPoint.valid) {
          return null
        }
        return fetchObservationStations({ url: this.forecastPoint.stationsUrl, key: this.apiKey })
      },
      default: null
    },
    observation: {
      async get () {
        if (this.stations === null || this.stations.length === 0) {
          return null
        }
        return fetchObservation({ url: this.stations[0].obsUrl, key: this.apiKey })
      },
      default: null
    }
  },
  computed: {
    ...mapGetters([
      'location',
      'forecastPoint',
      'forecastPointLoading',
      'forecastPointError'
    ]),
    ...mapGetters('alerts', [
      'alertsForPoint',
      'alertsForPointLoading'
    ]),
    ...mapGetters('persist', [
      'apiKey',
      'forecastBaseUrl'
    ]),
    ...mapGetters('menu', [
      'panel'
    ]),
    alertsIcon () {
      if (this.alertsForPointLoading) {
        return 'fa fa-circle-o-notch fa-spin'
      }
      if (this.alertsForPoint.length) {
        return 'fa fa-check-circle'
      }
      return 'fa fa-warning'
    },
    alertsLabel () {
      if (this.alertsForPoint) {
        const length = this.alertsForPoint.length
        if (length > 0) {
          return `${length} Alert${length > 1 ? 's' : ''}`
        } else {
          return 'No Alerts'
        }
      } else {
        return '--'
      }
    },
    observationIcon () {
      if (this.loadingObservation) {
        return 'fa fa-circle-o-notch fa-spin'
      } else if (this.observation && this.observation.icon && this.observation.icon.indexOf('/icons') >= 0) {
        const iconKeys = /icons\/land\/(day|night)\/(.*)\?/.exec(this.observation.icon)
        if (iconKeys !== null) {
          return 'wi ' + OBSERVATIONICON[iconKeys[2]][iconKeys[1]]
        }
      } else if (this.$asyncComputed.observation.error) {
        return 'fa fa-times-circle'
      }
      return null
    },
    observationLabel () {
      if (this.$asyncComputed.observation.error) {
        return 'N/A'
      }
      return '--'
    },
    forecastPointOutOfBounds () {
      return (this.forecastPointError && this.forecastPointException?.response.status === 404) ||
        (this.forecastPoint && !this.forecastPoint.valid)
    },
    loadingObservation () {
      const stations = this.$asyncComputed.stations && this.$asyncComputed.stations.success
      const observation = this.$asyncComputed.observation && this.$asyncComputed.observation.success

      if (stations && observation) {
        return false
      }
      return true
    },
    message () {
      if (!this.location) {
        return 'Select a location on the map or search.'
      } else if (this.forecastPointLoading) {
        return 'Loading the location...'
      } else if (!this.forecastPoint || this.forecastPointOutOfBounds || this.forecastPointError) {
        return 'Invalid location, please select again.'
      }
      return null
    }
  },
  watch: {
    location () {
      this.stations = null
      this.observation = null
    }
  }
}
</script>
