<template>
  <i v-if="false" />
</template>

<script>
import debounce from 'debounce-promise'
import { mapGetters, mapMutations } from 'vuex'
import { loadPoint } from '~/loaders'

const DEBOUNCE_DELAY = 1000 // ms

const fetchPoint = debounce(async function ({ apiBaseUrl, apiKey, coordinates }) {
  return loadPoint({ apiBaseUrl, apiKey, coordinates })
}, DEBOUNCE_DELAY, { leading: true })

export default {
  asyncComputed: {
    forecastPoint: {
      async get () {
        if (!this.location) {
          return null
        }
        return fetchPoint({
          apiBaseUrl: this.apiBaseUrl,
          apiKey: this.apiKey,
          coordinates: this.location
        })
      },
      default: null
    }
  },
  computed: {
    ...mapGetters([
      'location',
      'lastReloadTime'
    ]),
    ...mapGetters('persist', [
      'apiBaseUrl',
      'apiKey'
    ])
  },
  watch: {
    forecastPoint (value) {
      this.setForecastPoint(value)
    },
    '$asyncComputed.forecastPoint.exception' (value) {
      this.setForecastPointError(value)
    },
    '$asyncComputed.forecastPoint.updating' (value) {
      this.setForecastPointLoading(value)
    }
  },
  methods: {
    ...mapMutations([
      'setForecastPoint',
      'setForecastPointError',
      'setForecastPointLoading',
      'setForecastPointException'
    ])
  }
}
</script>
