<template>
  <app-panel :show-buttons="focus === null">
    <app-panel-section v-if="!focus">
      <div
        v-if="$asyncComputed.office.updating || !office"
      >
        Loading office...
      </div>
      <div
        v-else-if="$asyncComputed.office.updating.error"
      >
        The office location is not available.
      </div>
      <div
        v-else
      >
        <span>Your local forecast office is:</span><br>
        <a
          :href="office.url"
          target="_new"
          @click="viewForecastOffice"
        >
          {{ office.name }} ({{ office.id }})
        </a>
      </div>
    </app-panel-section>
    <app-panel-option
      v-show="!focus || focus === 'hourly'"
      id="hourly"
      label="Hourly Forecast"
      :expands="true"
      :default-expand="true"
    >
      <div
        v-if="$asyncComputed.forecast.updating || !hastemperatureChartData"
      >
        Loading hourly forecast graph...
      </div>
      <div
        v-else-if="$asyncComputed.forecastHourly.error"
      >
        The hourly forecast is not available.
      </div>
      <div
        v-else
        class="hourly"
      >
        <div class="hourly-graph">
          <line-chart
            :options="temperatureChartOptions"
            :data="temperatureChartData"
            :styles="temperatureChartStyles"
            :plugins="temperatureChartPlugins()"
          />
        </div>
        <div
          v-if="hourlyOverview && (hourlyOverview.date || hourlyOverview.title)"
          class="hourly-conditions"
        >
          <div v-if="hourlyOverview && hourlyOverview.date">
            {{ hourlyOverview.date }}
          </div>
          <div v-if="hourlyOverview && hourlyOverview.title">
            {{ hourlyOverview.title }}
          </div>
        </div>
        <div v-else>
          Calculating...
        </div>
        <div
          v-if="hourlyOverview"
          class="hourlyOverview"
        >
          <div
            class="hourlyOverviewTemp"
          >
            <div class="hourlyOverviewValuePrimary">
              <div>
                {{ parseInt(hourlyElementsByIndex.yTemp.value) }}
              </div>
              <div class="hourlyOverviewValueUnit">
                &deg;{{ hourlyElementsByIndex.yTemp.unit }}
              </div>
            </div>
            <div v-if="hourlyElementsByIndex.yTemp.trend">
              and {{ hourlyElementsByIndex.yTemp.trend }}
            </div>
          </div>
          <div
            v-if="hourlyOverview.icon"
            class="hourlyOverviewIcon"
          >
            <span
              :class="[
                hourlyOverview.icon
              ]"
            />
          </div>
          <div class="hourlyOverviewRain">
            <div class="hourlyOverviewValueSecondary">
              {{ parseInt(hourlyElementsByIndex.yPrecip.value) }}{{ hourlyElementsByIndex.yPrecip.unit }}
            </div>
            Rain
          </div>
          <div class="hourlyOverviewHigh">
            <div class="hourlyOverviewValueSecondary">
              <div v-if="hourlyOverview.high">
                {{ parseInt(hourlyOverview.high) }}
              </div>
              <div v-else>
                &mdash;
              </div>
              <div
                v-if="hourlyOverview.high"
                class="hourlyOverviewValueUnit"
              >
                &deg;
              </div>
              <div>/</div>
              <div v-if="hourlyOverview.low">
                {{ parseInt(hourlyOverview.low) }}
              </div>
              <div v-else>
                &mdash;
              </div>
              <div
                v-if="hourlyOverview.low"
                class="hourlyOverviewValueUnit"
              >
                &deg;
              </div>
            </div>
            Day temps
          </div>
        </div>
      </div>
    </app-panel-option>
    <app-panel-section v-if="!focus">
      <div
        v-if="$asyncComputed.forecast.updating || !forecast"
      >
        Loading forecast...
      </div>
      <div
        v-else-if="$asyncComputed.forecast.error"
      >
        The detailed forecast is not available.
      </div>
      <div
        v-else-if="forecastDays"
      >
        <div
          v-for="(day, index) in forecastDays"
          :key="index"
          class="details-period"
        >
          <div class="details-period-heading">
            <div class="details-period-label">
              {{ day.name }}
            </div>
            <div class="details-period-temperature">
              <span
                v-if="day.high !== null"
                class="temp-high"
              >
                {{ Math.round(day.high) }}&deg;<span class="details-period-temperature-unit">F</span>
              </span>
              <span
                v-else
                class="temp-high"
              >
                &mdash;
              </span>
              <span class="details-period-temperature-divider">/</span>
              <span
                v-if="day.low !== null"
                class="temp-low"
              >
                {{ Math.round(day.low) }}&deg;<span class="details-period-temperature-unit">F</span>
              </span>
              <span
                v-else
                class="temp-low"
              >
                &mdash;
              </span>
            </div>
          </div>
          <div
            class="details-period-description"
          >
            {{ day.periods[0].details }}
            <span
              v-if="day.periods[1]"
            >
              Then {{ day.periods[1].name.toLowerCase() }}, {{ day.periods[1].details }}
            </span>
          </div>
        </div>
      </div>
    </app-panel-section>
  </app-panel>
</template>

<script>
import debounce from 'debounce-promise'
import LineChart from '~/components/charts/Line.vue'
import { ForecastDay } from '~/entities'
import { createWatcherMixin } from '~/components/mixins'
import { mapGetters } from 'vuex'
import { OBSERVATIONICON } from '~/config'

import AppPanel from '~/components/menu/Panel.vue'
import AppPanelSection from '~/components/menu/PanelSection.vue'
import AppPanelOption from '~/components/menu/PanelOption.vue'

import {
  loadForecast,
  loadForecastHourly,
  loadOffice
} from '~/loaders'

const DEBOUNCE_DELAY = 1000 // ms

const fetchForecast = debounce(async function ({ url, key }) {
  return loadForecast(url, key)
}, DEBOUNCE_DELAY, { leading: true })

const fetchForecastHourly = debounce(async function ({ url, key }) {
  return loadForecastHourly(url, key)
}, DEBOUNCE_DELAY, { leading: true })

const fetchOffice = debounce(async function ({ url, key }) {
  return loadOffice(url, key)
}, DEBOUNCE_DELAY, { leading: true })

export default {
  components: {
    AppPanel,
    AppPanelSection,
    AppPanelOption,
    LineChart
  },
  mixins: [
    createWatcherMixin('forecastPoint'),
    createWatcherMixin('observation')
  ],
  asyncComputed: {
    forecast: {
      async get () {
        if (!this.validForecastPoint) {
          return []
        }
        return fetchForecast({ url: this.forecastPoint.forecastUrl, key: this.apiKey })
      },
      default: []
    },
    forecastHourly: {
      async get () {
        if (!this.validForecastPoint) {
          return []
        }
        return fetchForecastHourly({ url: this.forecastPoint.forecastHourlyUrl, key: this.apiKey })
      },
      default: null
    },
    office: {
      async get () {
        if (!this.validForecastPoint) {
          return null
        }
        return fetchOffice({ url: this.forecastPoint.officeUrl, key: this.apiKey })
      },
      default: null
    }
  },
  data () {
    return {
      hourlyHoverIndex: 0,
      hourlyDatasetVisibility: {
        x: true,
        yTemp: true,
        yPrecip: true,
        yHumid: false
      },
      showHourlyValues: true
    }
  },
  computed: {
    ...mapGetters([
      'location',
      'forecastPoint',
      'forecastPointLoading',
      'forecastPointError'
    ]),
    ...mapGetters('persist', [
      'apiKey'
    ]),
    ...mapGetters('menu', [
      'focus'
    ]),
    filteredForecastHourly () {
      if (!this.forecastHourly) {
        return null
      }

      // 7 days is enough and displays a consistent number of periods
      return this.forecastHourly.filter(hour => {
        const now = new Date()
        const start = new Date(hour.startTime)
        return start.getDate() - now.getDate() < 7
      })
    },
    forecastDays () {
      if (!this.filteredForecastHourly || this.forecast.length === 0) {
        return null
      }

      let periods = Array.from(this.forecast)
      let days = []

      // Check whether we're starting at night
      if (!periods[0].daytime) {
        days.push(new ForecastDay(periods.shift()))
      }
      while (periods.length) {
        days.push(new ForecastDay(...periods.splice(0, 2)))
      }

      return days
    },
    lastDataPointTime () {
      if (!this.filteredForecastHourly) {
        return null
      }
      const data = this.temperatureChartData.datasets[0].data
      return data[data.length - 1].x
    },
    firstDataPointTime () {
      if (!this.filteredForecastHourly) {
        return null
      }
      return this.temperatureChartData.datasets[0].data[0].x
    },
    temperatureChartOptions () {
      return {
        title: {
          display: false
        },
        legend: {
          display: false
        },
        animation: false,
        tooltips: {
          enabled: false
        },
        events: ['mousemove', 'click'],
        hover: {
          mode: null
        },
        layout: {
          padding: 0
        },
        maintainAspectRatio: false,
        scales: {
          x: {
            bounds: 'ticks',
            type: 'time',
            display: true,
            position: 'top',
            time: {
              unit: 'day',
              stepSize: 1,
              displayFormats: {
                day: 'L,LLL,d,ccc'
              }
            },
            max: this.lastDataPointTime,
            ticks: {
              font: {
                size: 12
              },
              crossAlign: 'near',
              callback: this.hourlyTimeForTick,
              align: 'start',
              labelOffset: 3
            }
          },
          yTemp: {
            type: 'linear',
            display: this.hourlyDatasetVisibility.yTemp,
            ticks: {
              font: {
                size: 12
              },
              callback: (value, index, ticks) => {
                return `${value}${String.fromCharCode(176)}F`
              },
              stepSize: 10
            }
          },
          yPrecip: {
            type: 'linear',
            display: !this.hourlyDatasetVisibility.yTemp,
            max: 100,
            min: 0
          },
          yHumid: {
            type: 'linear',
            display: false,
            max: 100,
            min: 0
          }
        },
        plugins: {
          backgroundDaylight: {
            colors: {
              day: 'rgb(255, 255, 255, 1)',
              night: 'rgb(240, 240, 240, 1)'
            },
            segments: this.temperatureChartDaylightSegments
          },
          backgroundBeforeForecast: {
            color: 'rgb(0, 0, 0, 0.05)',
            end: new Date(this.firstDataPointTime).getTime()
          },
          tooltip: {
            external: 'tooltipHandler'
          }
        }
      }
    },
    temperatureChartDaylightSegments () {
      if (!this.location || !this.filteredForecastHourly) {
        return []
      }
      let previousHour = null
      let segments = []
      let segmentStart = null
      for (let index in this.filteredForecastHourly) {
        const hour = this.filteredForecastHourly[index]
        if (!previousHour || previousHour.daytime !== hour.daytime || index === this.filteredForecastHourly.length - 1) {
          if (segmentStart) {
            segments.push({
              start: new Date(segmentStart).getTime(),
              end: new Date(previousHour.startTime).getTime(),
              daytime: previousHour.daytime
            })
          }
          segmentStart = hour.startTime
        }
        previousHour = hour
      }
      return segments
    },
    hastemperatureChartData () {
      if (this.temperatureChartData && this.temperatureChartData?.datasets[0]?.data.length > 0) {
        return true
      }
      return false
    },
    temperatureChartData () {
      if (!this.filteredForecastHourly) {
        return null
      }

      return {
        datasets: [
          {
            yAxisID: 'yTemp',
            label: 'Temperature',
            unit: 'F',
            hidden: !this.hourlyDatasetVisibility.yTemp,
            borderColor: '#f00',
            borderWidth: 1.5,
            fill: false,
            pointRadius: 0,
            data: this.filteredForecastHourly.map(hour => {
              return {
                x: hour.startTime,
                y: hour.temperature
              }
            })
          },
          {
            yAxisID: 'yPrecip',
            unit: '%',
            label: 'Probability of Precipitation',
            hidden: !this.hourlyDatasetVisibility.yPrecip,
            borderWidth: 1,
            borderColor: '#63d2f7',
            fill: true,
            backgroundColor: '#63d2f733',
            pointRadius: 0,
            data: this.filteredForecastHourly.map(hour => {
              return {
                x: hour.startTime,
                y: hour.probabilityOfPrecipitation
              }
            })
          },
          {
            yAxisID: 'yHumid',
            unit: '%',
            label: 'Relative Humidity',
            hidden: !this.hourlyDatasetVisibility.yHumid,
            borderWidth: 1,
            borderColor: '#333',
            pointRadius: 0,
            data: this.filteredForecastHourly.map(hour => {
              return {
                x: hour.startTime,
                y: hour.relativeHumidity
              }
            })
          }
        ]
      }
    },
    temperatureChartStyles () {
      return {
        height: '130px'
      }
    },
    hourlyOverview () {
      if (!this.filteredForecastHourly) {
        return null
      }

      const selectedDate = new Date(this.filteredForecastHourly[this.hourlyHoverIndex].startTime)

      let overview = {
        date: null,
        title: null,
        icon: null,
        high: null,
        low: null
      }

      overview.title = this.filteredForecastHourly[this.hourlyHoverIndex].short.toLowerCase().replace('and', '/')
      const startDate = new Date(this.filteredForecastHourly[0].startTime)
      if (this.hourlyHoverIndex === 0) {
        overview.date = `In the next hour...`
      } else if (this.sameDay(selectedDate, startDate)) {
        let when = selectedDate.toLocaleString('default', {
          hour: 'numeric',
          hour12: true
        }).replace(' ', '')
        when += selectedDate.getHours() >= 18 ? ' tonight' : ' today'
        overview.date = when
      } else {
        let when = selectedDate.toLocaleString('default', {
          month: 'long',
          day: 'numeric',
          hour: 'numeric'
        }).replace(/\s([AP]M)/, '$1')
        overview.date = when
      }

      const icon = this.filteredForecastHourly[this.hourlyHoverIndex].icon
      if (icon && icon.indexOf('/icons') >= 0) {
        const iconKeys = /icons\/land\/(day|night)\/(.*)\?/.exec(icon)
        if (iconKeys !== null) {
          overview.icon = 'wi ' + OBSERVATIONICON[iconKeys[2].split(',')[0]][iconKeys[1]]
        }
      }

      const date = selectedDate.getDate()
      if (this.forecastDays) {
        const day = this.forecastDays.find(day => day.date === date)
        if (day) {
          overview.high = day.high || overview.high
          overview.low = day.low || overview.low
        }
      }

      return overview
    },
    hourlyElementsByIndex () {
      if (this.hourlyHoverIndex === null) {
        return []
      }
      return this.temperatureChartData.datasets.reduce((result, dataset) => {
        let trend = 'steady'
        if (this.hourlyHoverIndex < dataset.data.length - 1) {
          const trendDiff = dataset.data[this.hourlyHoverIndex + 1].y - dataset.data[this.hourlyHoverIndex].y
          if (trendDiff !== 0) {
            trend = trendDiff > 0 ? 'rising' : 'cooling'
          }
        }

        result[dataset.yAxisID] = {
          label: dataset.label,
          value: dataset.data[this.hourlyHoverIndex].y,
          unit: dataset.unit,
          trend: trend
        }
        return result
      }, {})
    },
    validForecastPoint () {
      return this.forecastPoint && this.forecastPoint.valid
    }
  },
  methods: {
    hourlyLegendRowIcon (id) {
      return `fa fa-toggle${this.hourlyDatasetVisibility[id] ? '-on' : '-off'}`
    },
    hourlyTimeForTick (value, index, ticks) {
      const timeValues = value.split(',')
      if (timeValues[2] === '1' || index === 0) {
        return [`${timeValues[1]}`, `${timeValues[0]}/${timeValues[2]}`]
      }
      return [`${timeValues[3]}`, `${timeValues[0]}/${timeValues[2]}`]
    },
    toggleHourlyDatasetVisibility (id) {
      if (this.hourlyDatasetVisibility.hasOwnProperty(id)) {
        this.hourlyDatasetVisibility[id] = !this.hourlyDatasetVisibility[id]
      }
    },
    temperatureChartPlugins () {
      return [{
        id: 'backgroundDaylight',
        beforeDraw: (chart, args, pluginOptions) => {
          const { ctx, chartArea: { top, height }, scales: { x } } = chart
          ctx.save()

          const valueWidth = x.getPixelForValue(pluginOptions.segments[1].start) - x.getPixelForValue(pluginOptions.segments[0].end)

          pluginOptions.segments.forEach(segment => {
            const rectWidth = x.getPixelForValue(segment.end) - x.getPixelForValue(segment.start) + valueWidth
            ctx.fillStyle = segment.daytime ? pluginOptions.colors.day : pluginOptions.colors.night
            ctx.fillRect(x.getPixelForValue(segment.start), top, rectWidth, height)
          })
        }
      },
      {
        id: 'backgroundBeforeForecast',
        beforeDraw: (chart, args, pluginOptions) => {
          // diagonal lines before forecast hours
          const { ctx, chartArea: { top, height, left }, scales: { x } } = chart
          ctx.save()

          const pixelEnd = x.getPixelForValue(pluginOptions.end)
          const rectWidth = pixelEnd - left

          ctx.strokeStyle = 'rgb(0, 0, 0, 0.7)'
          ctx.lineWidth = 0
          ctx.moveTo(left + rectWidth, top)
          ctx.lineTo(left + rectWidth, top + height)
          ctx.stroke()

          ctx.beginPath()
          ctx.moveTo(left, top)
          ctx.lineTo(left + rectWidth, top)
          ctx.lineTo(left + rectWidth, top + height)
          ctx.lineTo(left, top + height)
          ctx.lineTo(left, top)
          ctx.closePath()
          ctx.clip()

          // these numbers are simply played with to get overall look and coverage of mask
          // comment out clip call above to see how it fully renders
          const numberOfStripes = 7
          for (var i = 0; i < numberOfStripes * 7; i += 2) {
            var thickness = rectWidth / numberOfStripes
            ctx.beginPath()
            ctx.strokeStyle = pluginOptions.color
            ctx.lineWidth = thickness
            ctx.lineCap = 'round'

            // lines draw from bottom left to top right
            ctx.moveTo(i * (thickness + 1) - 60, top + height)
            ctx.lineTo(height - 60 + i * (thickness + 1), top)
            ctx.stroke()
          }

          ctx.restore()
        }
      },
      {
        id: 'tooltipHandler',
        beforeEvent: (chart, { event, inChartArea }) => {
          if (inChartArea) {
            const elements = chart.getElementsAtEventForMode(event, 'index', { intersect: false }, true)
            this.hourlyHoverIndex = elements.length > 0 ? elements[0].index : 0
          }
        }
      }]
    },
    sameDay (dateA, dateB) {
      return dateA.getFullYear() === dateB.getFullYear() &&
        dateA.getMonth() === dateB.getMonth() &&
        dateA.getDate() === dateB.getDate()
    },
    viewForecastOffice () {
      if (this.$tracker) {
        this.$tracker('event', {
          action: 'forecast',
          label: 'office'
        })
      }
    }
  }
}

</script>

