<script>
import VectorLayer from 'ol/layer/Vector'
import VectorSource from 'ol/source/Vector'
import Feature from 'ol/Feature'
import Point from 'ol/geom/Point'
import { Fill, Style, Text } from 'ol/style'
import { v4 as uuid } from 'uuid'
import { mapRender } from '~/cmi/mixins/map'
import { transformPoint } from '~/cmi/util/proj'

import * as validators from '../../util/validators'

export default {
  mixins: [mapRender],
  inject: {
    getOLContainer: 'getOLContainer'
  },
  props: {
    textBaseline: {
      type: String,
      default: 'bottom'
    },
    color: {
      type: String,
      validator: value => /^#[0-9a-fA-F]{6}$/.test(value),
      default: '#333333'
    },
    coordinates: {
      validator: value => value === null || validators.lonLat(value),
      required: true
    },
    font: {
      type: String,
      default: '3em FontAwesome'
    },
    id: {
      type: String,
      validator: value => validators.notNull(value),
      default: () => uuid()
    },
    marker: {
      type: String,
      default: '\uf041'
    },
    offsetX: {
      type: Number,
      default: 3
    },
    offsetY: {
      type: Number,
      default: 12
    },
    zIndex: {
      type: Number,
      default: 100
    }
  },
  computed: {
    olContainer () {
      return this.getOLContainer()
    },
    viewCoordinates () {
      return transformPoint(this.coordinates, 'EPSG:4326', 'EPSG:3857')
    }
  },
  watch: {
    viewCoordinates () {
      if (this.viewCoordinates) {
        this.olFeature.setGeometry(new Point(this.viewCoordinates))
      }
    }
  },
  created () {
    const style = new Style({
      text: new Text({
        font: this.font,
        text: this.marker,
        textBaseline: this.textBaseline,
        fill: new Fill({
          color: this.color
        }),
        offsetY: this.offsetY,
        offsetX: this.offsetX
      })
    })
    this.olFeature = new Feature({
      geometry: this.viewCoordinates ? new Point(this.viewCoordinates) : null
    })
    this.olLayer = new VectorLayer({
      properties: {
        who: this.id
      },
      style: style,
      zIndex: this.zIndex,
      declutter: true,
      source: new VectorSource({
        features: [this.olFeature]
      })
    })
    this.olContainer.push(this.olLayer)
    this.$emit('created')
  },
  beforeDestroy () {
    this.olContainer.remove(this.olLayer)
  }
}
</script>
