<template>
  <cmi-layer-group
    v-if="true"
    id="activearea"
  >
    <!-- Polygon -->
    <cmi-layer-vector-shape
      v-if="hasPolygon"
      id="grid"
      :autofocus="true"
      :opacity="1"
      :z-index="zIndex"
      :features="polygonAsGeoJson"
      :fit-max-zoom="fitMaxZoom"
      :fit-padding="fitPadding"
      :style-function="styleFunction"
    />
    <!-- Zone -->
    <cmi-layer-kml
      v-if="hasZone"
      id="zone"
      :autofocus="true"
      :opacity="1"
      :z-index="zIndex"
      :url="zoneKMLUrl"
      :fit-max-zoom="fitMaxZoom"
      :fit-padding="fitPadding"
      :style-function="styleFunctionForZone"
    />
  </cmi-layer-group>
</template>

<script>
import { Fill, Stroke, Style } from 'ol/style'
import { mapGetters } from 'vuex'

export default {
  props: {
    maxZoom: {
      type: Number,
      default: 10
    },
    minZoom: {
      type: Number,
      default: 4
    },
    opacity: {
      type: Number,
      default: 0.6
    },
    zIndex: {
      type: Number,
      required: true
    }
  },
  computed: {
    ...mapGetters([
      'agendaSelected'
    ]),
    ...mapGetters('persist', [
      'forecastBaseUrl'
    ]),
    fitMaxZoom () {
      return this.agendaSelected?.area?.fitMaxZoom || this.maxZoom
    },
    fitPadding () {
      return this.agendaSelected?.area?.fitPadding || [0, 0, 0, 0]
    },
    hasZone () {
      return this.agendaSelected?.area?.zone !== undefined
    },
    zoneKMLUrl () {
      return this.hasZone && this.isValidHttpUrl(this.agendaSelected.area.zone) ? this.agendaSelected.area.zone : `${this.forecastBaseUrl}/kml/${this.agendaSelected.area.zone}.kml`
    },
    hasPolygon () {
      return this.agendaSelected?.area?.polygon !== undefined
    },
    styleFunctionForZone () {
      // if there is a zone but no style defined, do not apply any style function to allow KML styles to show
      if (this.hasZone && !this.agendaSelected?.area?.style) {
        return undefined
      } else {
        return this.styleFunction
      }
    },
    polygonAsGeoJson () {
      if (!this.hasPolygon) {
        return null
      }

      // Check if already GeoJSON (array of objects vs array of coordinates)
      if (!Array.isArray(this.agendaSelected.area.polygon[0])) {
        return this.agendaSelected.area.polygon
      }
      let area = [{
        type: "Feature",
        geometry: {
          type: "Polygon",
          coordinates: [[]]
        }
      }]
      for (let x = 0; x < this.agendaSelected.area.polygon.length; x++) {
        const coord = this.agendaSelected.area.polygon[x]
        area[0].geometry.coordinates[0].push([coord[1], coord[0]])
      }
      return area
    }
  },
  methods: {
    styleFunction (feature) {
      return new Style({
        stroke: new Stroke({
          color: this.agendaSelected?.area?.style?.stroke?.color || 'rgba(29, 130, 29, 1)',
          width: this.agendaSelected?.area?.style?.stroke?.width || 2
        }),
        fill: new Fill({
          color: this.agendaSelected?.area?.style?.fill?.color || 'rgba(0, 255, 0, 0.45)'
        })
      })
    },
    isValidHttpUrl (string) {
      let url
      try {
        url = new URL(string)
      } catch (_) {
        return false
      }
      return url.protocol === "http:" || url.protocol === "https:"
    }
  }
}
</script>
