import Vue from 'vue'

export class Attribution {
  constructor ({ title, url, logoUrl }) {
    this.__data = Vue.observable({
      title: title,
      url: url,
      logoUrl: logoUrl
    })
  }

  get logoUrl () {
    return this.__data.logoUrl
  }

  get title () {
    return this.__data.title
  }

  get url () {
    return this.__data.url
  }
}

export class DefinitionBuilder {
  constructor ({ attributions = [], description = null, id = null, name = null, type = null }) {
    this.__attributions = attributions
    this.__description = description
    this.__id = id
    this.__name = name
    this.__type = type
  }

  get attributions () {
    return this.__attributions
  }

  get description () {
    return this.__description
  }

  get id () {
    return this.__description
  }

  get name () {
    return this.__description
  }

  get type () {
    return this.__type
  }

  addAttribution ({ title, url, logoUrl = null }) {
    this.__attributions.append(new Attribution({ title, url, logoUrl }))
    return this
  }

  setDescription (description) {
    this.__description = description
    return this
  }

  setId (id) {
    this.__id = id
    return this
  }

  setName (name) {
    this.__name = name
    return this
  }

  create () {
    return {
      id: this.__id,
      attributions: this.__attributions,
      description: this.__description,
      name: this.__name,
      type: this.__type
    }
  }
}

export class WmsDefinitionBuilder extends DefinitionBuilder {
  constructor () {
    super({ type: 'wms' })

    this.__extent = null
    this.__times = []
    this.__url = null
    this.__version = null
  }

  get extent () {
    return this.__extent
  }

  setExtent (extent) {
    this.__extent = extent
    return this
  }

  get times () {
    return this.__times
  }

  setTimes (times) {
    this.__times = times
    return this
  }

  get url () {
    return this.__url
  }

  setUrl (url) {
    this.__url = url
    return this
  }

  get version () {
    return this.__version
  }

  setVersion (version) {
    this.__version = version
    return this
  }

  create () {
    return Object.assign(super.create(), {
      extent: this.__extent,
      times: this.__times,
      url: this.__url,
      version: this.__version
    })
  }
}

export class XyzDefinitionBuilder extends DefinitionBuilder {
  constructor () {
    super({ type: 'xyz' })

    this.__extent = null
    this.__url = null
  }

  get extent () {
    return this.__extent
  }

  setExtent (extent) {
    this.__extent = extent
    return this
  }

  create () {
    return Object.assign(super.create(), {
      extent: this.__extent,
      url: this.__url
    })
  }
}
