import { ResourceLoader } from '~/cmi/loaders'
import * as log from '~/cmi/log'
import { RadarStation } from '~/entities'
import { DateTime } from 'luxon'

const STATION_RADIUS = {
  'WSR-88D': 285.393, // 248 Nautical miles converted to statute miles
  'TDWR': 258.925 // 225 Nautical miles converted to statute miles
}

export async function loadRadarStations (apiBaseUrl, apiKey) {
  const url = `${apiBaseUrl}/radar/stations`
  const options = {
    headers: {
      'Accept': 'application/geo+json'
    },
    params: {
      stationType: 'WSR-88D,TDWR'
    },
    responseType: 'json'
  }
  if (apiKey !== null) {
    options.headers['API-Key'] = apiKey
  }

  log.info(`Requesting radar station data from ${url}`)

  const loader = new ResourceLoader()
  return loader.load(url, options, response => {
    const excludedStationIds = ['RKJK', 'RKSG', 'RODN']
    const stations = response.data.features.filter(data => !excludedStationIds.includes(data.properties.id)).reduce((map, data) => {
      try {
        const lastReceived = DateTime.fromISO(data.properties.latency.levelTwoLastReceivedTime)
        let latency = null
        let stationStatus = null

        if (lastReceived.isValid) {
          latency = Math.abs(lastReceived.diffNow('minutes').minutes)
          if (latency < 10) {
            stationStatus = 'up'
          } else if (latency < 30) {
            stationStatus = 'warning'
          } else {
            stationStatus = 'down'
          }
        }

        map[data.properties.id] = new RadarStation({
          id: data.properties.id,
          status: stationStatus,
          coordinates: data.geometry.coordinates,
          latency: latency,
          name: data.properties.name,
          radius: STATION_RADIUS[data.properties.stationType],
          type: data.properties.stationType
        })
      } catch (error) {
        log.warn(`Failed to process station data: ${error.stack}\n`, data)
      }

      return map
    }, {})
    log.debug('Found radar stations', stations)

    return stations
  })
}
