<template>
  <i v-if="false" />
</template>

<script>
import debounce from 'debounce-promise'
import { mapGetters, mapMutations } from 'vuex'

import { loadAlertColors } from '~/loaders'

const DEBOUNCE_DELAY = 1000 // ms

const fetchColors = debounce(async ({ url }) => {
  return loadAlertColors(url)
}, DEBOUNCE_DELAY, { leading: true })

export default {
  asyncComputed: {
    colors: {
      async get () {
        return fetchColors({ url: this.gisUrl('wwa') })
      },
      shouldUpdate () {
        return Object.keys(this.$store.getters['alerts/colors']).length === 0
      }
    }
  },
  computed: {
    ...mapGetters('persist', [
      'gisUrl'
    ])
  },
  watch: {
    colors (value) {
      this.setColors(value)
    }
  },
  methods: {
    ...mapMutations('alerts', [
      'setColors'
    ])
  }
}
</script>
