export class RadarStation {
  constructor ({ id, status, apiBaseUrl, coordinates, latency, name, radius, type }) {
    this.__id = id
    this.__status = status
    this.__coordinates = coordinates
    this.__latency = latency
    this.__name = name
    this.__radius = radius
    this.__type = type
  }

  get id () {
    return this.__id
  }

  get status () {
    return this.__status
  }

  get coordinates () {
    return this.__coordinates
  }

  get latency () {
    return this.__latency
  }

  get name () {
    return this.__name
  }

  get radius () {
    return this.__radius
  }

  get type () {
    return this.__type
  }
}
