<template>
  <cmi-layer-wms
    v-if="activeFrame && activeFrame.valid"
    :id="_id"
    :attributions="layerData.attributions"
    :extent="layerData.extent"
    :layer="layer"
    :max-zoom="maxZoom"
    :min-zoom="minZoom"
    :opacity="opacity"
    :styles="layerData.style"
    :time="activeFrame.time"
    :transition="0"
    :tile-size="tileSize"
    :url="layerData.url"
    :version="version"
    :z-index="zIndex"
    @track:tile="trackTileMetric"
  />
</template>

<script>
import { v4 as uuid } from 'uuid'

import CmiLayerWms from '../layers/LayerWms.vue'
import { WMS } from '../../loaders'
import * as log from '../../log'

/**
 * An animated timeline constructed from a WMS service.
 *
 * This component manages a collection of timeline frames based on a
 * GetCapabilities response from a WMS service.  The service must return a
 * time extent.  The list will automatically refresh according to the ancestor
 * Map's reload policy.
 *
 * Frames that fall entirely outside the Map's animation window are culled.  If
 * the window changes, the frame list will be recalculated automatically.
 */
export default {
  components: {
    CmiLayerWms
  },
  inject: {
    $reload: 'reload',
    $window: 'window'
  },
  props: {
    /**
     * The layer group ID for the timeline.
     *
     * @type {String}
     */
    id: {
      type: String,
      default: null
    },
    /**
     * The name of the layer to access from the WMS service.
     *
     * @type {String}
     */
    layer: {
      type: String,
      required: true
    },
    frameCount: {
      type: Number,
      default: null
    },
    maxZoom: {
      type: Number,
      default: 10
    },
    minZoom: {
      type: Number,
      default: 0
    },
    /**
     * The WMS service URL.
     *
     * @type {Number}
     */
    opacity: {
      type: Number,
      default: 1
    },
    /**
     * A primary timeline determins the displayed times
     * Non-primary timelines find the closest times to the primary timeline
     */
    primary: {
      type: Boolean,
      default: false
    },
    /**
     * The WMS service URL.
     *
     * @type {String}
     */
    url: {
      type: String,
      required: true
    },
    suppressExtent: {
      type: Boolean,
      default: false
    },
    /**
     * The size of the tiles requested from the WMS service.
     *
     * @type {Array}
     */
    tileSize: {
      type: Array,
      default: () => [256, 256]
    },
    /**
     * The version of the WMS service.
     *
     * @type {String}
     */
    version: {
      type: String,
      required: true
    },
    zIndex: {
      type: Number,
      default: 0
    }
  },
  data () {
    return {
      /**
       * A random UUID to use in the default ID.
       *
       * @type {String}
       */
      uuid: uuid()
    }
  },
  asyncComputed: {
    layerData: {
      async get () {
        log.debug(`Loading timeline data for ${this._id}`)

        const wms = new WMS(this.url, this.version)
        const layers = await wms.getLayers()

        if (!(this.layer in layers)) {
          log.error(`Could not find "${this.layer}" in the list of layers retrieved from server`)
        }
        // TODO: Investigate with Openlayers why view doesn't render past -180 when visible
        // Most obvious with alerts, which go beyond -180 over Aleutians near Alaska
        // This prop should probably be removed once/if resolved with Openlayers
        if (this?.suppressExtent === true) {
          layers[this.layer].extent = undefined
        }
        return layers[this.layer]
      },
      default: null,
      watch: ['lastReloadTime', 'layer']
    }
  },
  computed: {
    activeFrame () {
      if (!this.frames || !this.frames.length) {
        // if no calculated frames, use the first frame of the layer for all timeline frames
        if (this.layerData) {
          return {
            id: `${this._id}-static`,
            time: this.layerData.times[0].toISO(),
            valid: true
          }
        }
        // frame data still loading
        return null
      }

      return !this.frames[this.animationFrameNumber] ? {
        id: `${this._id}-invalid`,
        time: null,
        valid: false
      } : {
        id: this._id,
        time: this.frames[this.animationFrameNumber].toISO(),
        valid: true
      }
    },
    /**
     * The ancestor {@link Map}'s animation current frame number.
     *
     * If this is null, animations will be considered disabled.
     *
     * @type {Number}
     */
    animationFrameNumber () {
      return this.$window.getAnimationFrameNumber()
    },
    /**
     * The ancestor {@link Map}'s animation time.
     *
     * If this is null, animations will be considered disabled.
     *
     * @type {?luxon.DateTime}
     */
    animationPrimaryFrames () {
      return this.$window.getAnimationPrimaryFrames()
    },
    frames () {
      if (!this.animationPrimaryFrames) {
        log.warn(`No primary times available; falling back to static layer for ${this.layer}`)
        return []
      } else if (!this.layerData || this.layerData.times.length === 0) {
        log.warn(`No time extent available; falling back to static layer for ${this.layer}`)
        return []
      }
      log.debug(`Calculating frames for ${this.id}`)

      let mappedFrames = this.animationPrimaryFrames
      // Map non-primary layers to the primary layer
      if (!this.primary) {
        mappedFrames = mappedFrames.map((apFrameTime) => {
          return this.layerData.times.findLast(layerTime => layerTime < apFrameTime.plus({ seconds: 20 }))
        })
      }

      log.debug(
        `Mapped frame time list for ${this._id}: `, mappedFrames.map(frame => `${frame}`)
      )

      return mappedFrames
    },
    /**
     * The last time the WMS data for the timeline was reloaded.
     *
     * @type {luxon.DateTime}
     */
    lastReloadTime () {
      return this.$reload.getLastReloadTime()
    },
    /**
     * The computed ID.
     *
     * @type {String}
     */
    _id () {
      return this.id || `timeline-${this.uuid}`
    }
  },
  watch: {
    activeFrame () {
      this.$emit('change:active', this.activeFrame)
    },
    frames () {
      this.$emit('change:last', this.frames[this.frames.length - 1])
    },
    layerData () {
      if (this.primary) {
        log.debug(`Primary layer set to ${this.id}`)
        this.$window.setAnimationPrimaryFrames(this.layerData.times, this.frameCount)
      }
    }
  },
  methods: {
    trackTileMetric (metric) {
      this.$emit('track:tile', metric)
    }
  }
}
</script>
