<template>
  <i v-if="false" />
</template>

<script>
import debounce from 'debounce-promise'
import { mapGetters, mapMutations } from 'vuex'

import { loadRadarStations } from '~/loaders'

const DEBOUNCE_DELAY = 1000 // ms

const fetchRadarStations = debounce(async (url, key) => {
  return loadRadarStations(url, key)
}, DEBOUNCE_DELAY, { leading: true })

export default {
  asyncComputed: {
    stations: {
      async get () {
        return fetchRadarStations(this.apiBaseUrl, this.apiKey)
      },
      watch: ['lastReloadTime']
    }
  },
  computed: {
    ...mapGetters([
      'lastReloadTime'
    ]),
    ...mapGetters('persist', [
      'apiBaseUrl',
      'apiKey'
    ])
  },
  watch: {
    stations (value) {
      this.setStations(value)
    },
    '$asyncComputed.stations.exception' (value) {
      this.setStationsError(value)
    },
    '$asyncComputed.stations.updating' (value) {
      this.setStationsLoading(value)
    }
  },
  methods: {
    ...mapMutations('local', [
      'setStations',
      'setStationsError',
      'setStationsLoading'
    ])
  }
}
</script>
