import * as log from '~/cmi/log'

function createDefaultState () {
  return {
    activeLayerTime: null,
    alerts: {
      extent: {
        error: null,
        loading: false,
        value: []
      },
      point: {
        error: null,
        loading: false,
        value: []
      }
    },
    colors: {},
    lastLayerTime: null,
    shortFusedOnly: false,
    opacity: 0.8,
    // the parent app (Radar) watches this to display alert info in the template panel
    alertForPanel: null,
    highlightBbox: null,
    limitToExtent: false
  }
}

export default {
  namespaced: true,
  state: createDefaultState(),
  mutations: {
    opacity (state, input) {
      state.opacity = input
    },
    reset (state) {
      Object.assign(state, createDefaultState())
    },
    setActiveLayerTime (state, input) {
      if (input !== null && typeof input !== 'string') {
        log.error('Active layer time should be null or in ISO8601 string form; received ', input)
        return
      }
      state.activeLayerTime = input
    },
    setAlertsForExtent (state, input) {
      if (!Array.isArray(input)) {
        log.error('Alerts must be an array; received ', input)
        return
      }
      state.alerts.extent.value = input
    },
    setAlertsForExtentError (state, input) {
      if (input !== null && !(input instanceof Error)) {
        log.error('Error must be null or an instance of Error; received ', input)
        return
      }
      state.alerts.extent.error = input
    },
    setAlertsForExtentLoading (state, input) {
      state.alerts.extent.loading = Boolean(input)
    },
    setAlertsForExtentUpdated (state, input) {
      state.alerts.extent.updated = Boolean(input)
    },
    setAlertsForPoint (state, input) {
      if (!Array.isArray(input)) {
        log.error('Alerts must be an array; received ', input)
        return
      }
      state.alerts.point.value = input
    },
    setAlertsForPointError (state, input) {
      if (input !== null && !(input instanceof Error)) {
        log.error('Error must be null or an instance of Error; received ', input)
        return
      }
      state.alerts.point.error = input
    },
    setAlertsForPointLoading (state, input) {
      state.alerts.point.loading = Boolean(input)
    },
    setAlertsForPointUpdated (state, input) {
      state.alerts.point.updated = Boolean(input)
    },
    setColors (state, input) {
      if (typeof input !== 'object') {
        throw new Error('Colors must be an object with alert/color key/value pairs')
      }
      state.colors = input
    },
    setHighlightBbox (state, input) {
      if (input !== null && (!Array.isArray(input) || input.length !== 4 || input.find(coord => typeof coord !== 'number'))) {
        log.error('Highlight bbox must be null or an array of four numbers [minX, minY, maxX, maxY]; received ', input)
        return
      }
      state.highlightBbox = input
    },
    setLastLayerTime (state, input) {
      state.lastLayerTime = input
    },
    setLimitToExtent (state, input) {
      state.limitToExtent = Boolean(input)
    },
    setShortFusedOnly (state, input) {
      state.shortFusedOnly = Boolean(input)
    },
    alertForPanel (state, input) {
      if (input !== null && typeof input !== 'object') {
        log.error('Alert for panel must be null or an object; received ', input)
        return
      }
      state.alertForPanel = input
    }
  },
  actions: {
    setAlertForPanel ({ commit }, alert) {
      commit('alertForPanel', alert)
    }
  },
  getters: {
    /** @type {String} */
    activeLayerTime: state => state.activeLayerTime,
    alertsForExtent: state => state.alerts.extent.value,
    alertsForExtentError: state => state.alerts.extent.error,
    alertsForExtentLoading: state => state.alerts.extent.loading,
    alertsForPoint: state => state.alerts.point.value,
    alertsForPointError: state => state.alerts.point.error,
    alertsForPointLoading: state => state.alerts.point.loading,
    colors: state => state.colors,
    highlightBbox: state => state.highlightBbox,
    lastLayerTime: state => state.lastLayerTime,
    layer: state => state.shortFusedOnly ? 'warnings' : 'hazards',
    limitToExtent: state => state.limitToExtent,
    opacity: state => state.opacity,
    shortFusedOnly: state => state.shortFusedOnly,
    styles: state => state.styles
  }
}
