<template>
  <div
    class="agenda-menu-item"
  >
    <div class="agenda-menu-item-bar">
      <div
        class="agenda-menu-item-bar-label"
        @click="selectAgenda(id)"
      >
        {{ item.text }}
      </div>
      <div
        class="agenda-menu-item-bar-details fa search-option-icon"
        :class="{ 'agenda-menu-item-bar-details-open': showDetails }"
        @click="toggleDetails()"
      />
    </div>
    <div
      v-show="showDetails"
      class="agenda-menu-item-details"
    >
      {{ item.description }}
      <ul>
        <li
          v-for="(includeItem, index) in item.includes"
          :key="`${item.id}-include-${index}`"
        >
          {{ includeItem }}
        </li>
      </ul>
    </div>
  </div>
</template>

<script>
import { mapActions } from 'vuex'

export default {
  props: {
    id: {
      type: String,
      required: true
    },
    item: {
      type: Object,
      required: true
    }
  },
  data () {
    return {
      showDetails: false
    }
  },
  methods: {
    ...mapActions('menu', [
      'closePanel'
    ]),
    selectAgenda (id) {
      this.$emit('agenda:select', id)
      this.closePanel()
    },
    toggleDetails (forced) {
      if (typeof forced !== 'undefined') {
        this.showDetails = forced
      } else {
        this.showDetails = !this.showDetails
      }

      if (this.$tracker && this.showDetails) {
        this.$tracker('event', {
          action: 'view-info',
          label: this.id
        })
      }
    }
  }
}
</script>

