<template>
  <app-panel>
    <app-panel-section
      description="Select the national radar product:"
    >
      <app-panel-item
        v-for="map in maps"
        :key="map.name"
        :label="map.longText"
        @click.native="selectProduct(map.name)"
      />
    </app-panel-section>
  </app-panel>
</template>

<script>
import { MAPS } from '~/config'
import { mapActions } from 'vuex'

import AppPanel from '../Panel.vue'
import AppPanelItem from '../PanelItem.vue'
import AppPanelSection from '~/components/menu/PanelSection.vue'

export default {
  components: {
    AppPanel,
    AppPanelItem,
    AppPanelSection
  },
  data () {
    return {
      maps: MAPS.national
    }
  },
  computed: {
    nationalMap: {
      get () { return this.$store.getters.nationalMap },
      set (value) { this.$store.commit('nationalMap', value) }
    }
  },
  methods: {
    ...mapActions('menu', [
      'closePanel'
    ]),
    selectProduct (id) {
      this.nationalMap = id
      if (this.$tracker) {
        this.$tracker('event', {
          action: 'national',
          label: id
        })
      }
      this.closePanel()
    }
  }
}
</script>
