<template>
  <i v-if="false" />
</template>

<script>

import debounce from 'debounce-promise'
import { DateTime } from 'luxon'
import { mapGetters, mapMutations } from 'vuex'
import { loadAlertsForExtent } from '~/loaders'

const DEBOUNCE_DELAY = 1000 // ms

const fetchAlertsForExtent = debounce(async ({ extent, layer, time, url }) => {
  return loadAlertsForExtent({ extent, layer, time, url })
}, DEBOUNCE_DELAY, { leading: true })

export default {
  asyncComputed: {
    alertsForExtent: {
      async get () {
        return fetchAlertsForExtent({
          extent: this.extentForAlertData,
          layer: this.layer,
          time: this.validLastLayerTime,
          url: this.gisUrl('wwa')
        })
      },
      shouldUpdate () {
        return this.validLastLayerTime
      },
      watch: ['lastReloadTime']
    }
  },
  data () {
    return {
      validLastLayerTime: null
    }
  },
  computed: {
    ...mapGetters([
      'extentForAlertData'
    ]),
    ...mapGetters('persist', [
      'gisUrl'
    ]),
    ...mapGetters('alerts', [
      'lastLayerTime',
      'layer'
    ])
  },
  watch: {
    // TODO: There's an issue only during load that causes a rogue lastLayerTime to trigger. It has lost its inheritance from
    // DateTime, but retains the properties (likely from an unintentional copy?). It does not get set to the store, but perhaps by
    // pointing to the same memory address it triggers a get from the store. Don't have time to investigate, so for now
    // simply ignore any change that isn't a DateTime instance.
    lastLayerTime: {
      immediate: true,
      handler (value) {
        if (value instanceof DateTime) {
          this.validLastLayerTime = this.lastLayerTime
          this.setAlertsForExtentLoading(true)
        } else {
          this.$cmi.log.debug(`Alerts lastLayerTime not luxon DateTime, found ${typeof this.lastLayerTime}. Loading alerts aborted.`)
        }
      }
    },
    alertsForExtent (value) {
      this.setAlertsForExtent(value)
    },
    '$asyncComputed.alertsForExtent.exception' (value) {
      this.setAlertsForExtentError(value)
    },
    '$asyncComputed.alertsForExtent.updating' (value) {
      this.setAlertsForExtentLoading(value)
    }
  },
  methods: {
    ...mapMutations('alerts', [
      'setAlertsForExtent',
      'setAlertsForExtentError',
      'setAlertsForExtentLoading'
    ])
  }
}
</script>
