<script>
import VectorLayer from 'ol/layer/Vector'
import VectorSource from 'ol/source/Vector'
import GeoJSON from 'ol/format/GeoJSON'
import { transformPoint } from '~/cmi/util/proj'
import { mapRender } from '~/cmi/mixins/map'

export default {
  mixins: [mapRender],
  inject: {
    getOLContainer: 'getOLContainer',
    getOLMap: 'getOLMap'
  },
  props: {
    autofocus: {
      type: Boolean,
      default: false
    },
    dataProjection: {
      type: String,
      default: 'EPSG:4326'
    },
    features: {
      type: Array,
      required: true
    },
    location: {
      type: Array,
      default: null
    },
    styleFunction: {
      type: Function,
      default: undefined
    },
    featureId: {
      type: String,
      default: null
    },
    opacity: {
      type: Number,
      default: 1
    },
    maxZoom: {
      type: Number,
      default: 12
    },
    fitPadding: {
      type: Array,
      default: () => [0, 0, 0, 0]
    },
    fitMaxZoom: {
      type: Number,
      default: 20
    },
    zIndex: {
      type: Number,
      default: 0
    }
  },
  data () {
    return {
      olLayer: null,
      // this is a data property vs computed because arrays as props (e.g. features) are not reactive
      geoJsonFeatures: [],
      selectedFeature: null,
      projection: 'EPSG:3857'
    }
  },
  computed: {
    olContainer () {
      return this.getOLContainer()
    },
    olMap () {
      return this.getOLMap()
    }
  },
  watch: {
    features: {
      immediate: true,
      handler () {
        this.geoJsonFeatures = this.features.map((geojsonFeature) => {
          const feature = new GeoJSON().readFeature(geojsonFeature, {
            dataProjection: this.dataProjection,
            featureProjection: this.projection
          })
          if (this.selectedFeature && this.selectedFeature.getId() === feature.getId()) {
            this.selectedFeature = feature
            this.selectedFeature.set('selected', true)
          }
          return feature
        })
        // if immmediate, created will add features when initializing layer
        if (this.olLayer) {
          this.olLayer.getSource().clear()
          this.olLayer.getSource().addFeatures(this.geoJsonFeatures)
        }
      }
    },
    // if parent wants to select the nearest feature by location
    location () {
      if (this.location) {
        if (this.selectedFeature) {
          this.selectedFeature.unset('selected')
        }
        const projectedCoordinates = transformPoint(this.location, this.dataProjection, this.projection)
        this.selectedFeature = this.olLayer.getSource().getClosestFeatureToCoordinate(projectedCoordinates)
        if (this.selectedFeature) {
          this.selectedFeature.set('selected', true)
          this.olLayer.getSource().clear()
          this.olLayer.getSource().addFeatures(this.geoJsonFeatures)
          this.$emit('selectFeature', {
            id: this.selectedFeature.getId(),
            name: this.selectedFeature.get('name'),
            coordinates: this.selectedFeature.get('coordinates')
          })
        }
      }
    },
    // if parent sets selected feature by id
    featureId: {
      immediate: true,
      handler () {
        if (this.selectedFeature) {
          if (this.selectedFeature.getId() === this.featureId) {
            // feature already selected
            return
          }
          this.selectedFeature.unset('selected')
        }
        for (const feature of this.geoJsonFeatures) {
          if (feature.getId() === this.featureId) {
            feature.set('selected', true)
            this.selectedFeature = feature
            break
          }
        }
        if (this.olLayer) {
          this.olLayer.getSource().clear()
          this.olLayer.getSource().addFeatures(this.geoJsonFeatures)
        }
      }
    },
    opacity () {
      this.olLayer.setOpacity(this.opacity)
    }
  },
  created () {
    this.olLayer = new VectorLayer({
      properties: {
        who: this.id
      },
      zIndex: this.zIndex,
      source: new VectorSource({
        features: this.geoJsonFeatures
      }),
      style: this.styleFunction
    })
    this.olContainer.push(this.olLayer)

    if (this.autofocus) {
      // when data is syncronous from bookmark it needs to wait a tick to have the map ready
      this.$nextTick(() => {
        this.olMap.getView().fit(this.olLayer.getSource().getExtent(), {
          maxZoom: this.fitMaxZoom,
          padding: this.fitPadding
        })
      })
    }
    this.$emit('created')
  },
  beforeDestroy () {
    this.olContainer.remove(this.olLayer)
  }
}
</script>
