<template>
  <div class="alerts">
    <p>Active alerts are only for the most recent time.</p>
    <slot name="help" />
    <div v-if="!ready">
      {{ instructions }}
    </div>
    <div v-else-if="loading">
      Loading alerts {{ descriptor }}...
    </div>
    <div v-else-if="error">
      There was an error loading alerts.
    </div>
    <div v-else-if="!alertGroups">
      There are no {{ shortFusedOnly ? 'storm based ' : '' }} alerts {{ descriptor }}.
    </div>
    <div v-else>
      <div
        v-for="(alertGroup, name) in alertGroups"
        :key="name"
        class="alerts-container"
        :style="{ 'border-left-color': name in colors ? colors[name] : '#cccccc' }"
      >
        <div
          :class="[
            'alerts-group-header',
            expandable ? 'alerts-group-header-expandable' : ''
          ]"
          @click="toggleAlertGroup(name, alertGroup.length)"
        >
          <div
            :class="[
              'alerts-group-header-label',
              selectedAlertGroup === name ? 'alerts-group-header-label-selected' : ''
            ]"
          >
            {{ alertName(name, alertGroup.length) }}
          </div>
          <div
            v-if="expandable"
            :class="[
              'alerts-group-header-expand',
              'fa',
              'fa-chevron-down',
              selectedAlertGroup === name ? 'fa-rotate-180' : ''
            ]"
          />
        </div>
        <div
          v-if="selectedAlertGroup === name || !expandable"
          class="alerts-group-alerts"
        >
          <div
            v-for="alert in alertGroup"
            :key="alert.id"
            class="alerts-group-alert"
          >
            <app-panel-alert
              :alert="alert"
              :color="alert.event in colors ? colors[alert.event] : '#cccccc'"
              :expanded="alert.id == selectedAlert"
              :grouped="true"
              @collapse="selectAlert(alert.id, false)"
              @expand="selectAlert(alert.id, true)"
            />
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { mapGetters } from 'vuex'
import { createWatcherMixin } from '~/components/mixins'

import AppPanelAlert from '~/components/menu/PanelAlert.vue'

export default ({
  components: {
    AppPanelAlert
  },
  mixins: [
    createWatcherMixin('alertColors')
  ],
  props: {
    alerts: {
      type: Array,
      default: null
    },
    descriptor: {
      type: String,
      default: null
    },
    error: {
      type: Boolean,
      default: false
    },
    expandable: {
      type: Boolean,
      default: false
    },
    instructions: {
      type: String,
      default: null
    },
    loading: {
      type: Boolean,
      default: false
    },
    ready: {
      type: Boolean,
      default: false
    }
  },
  data () {
    return {
      selectedAlert: null,
      selectedAlertGroup: null
    }
  },
  computed: {
    ...mapGetters('alerts', {
      colors: 'colors',
      shortFusedOnly: 'shortFusedOnly'
    }),
    alertGroups () {
      if (!this.alerts || !this.alerts.length) {
        return null
      }
      return this.alerts.reduce(function (groups, alert) {
        (groups[alert['event']] = groups[alert['event']] || []).push(alert)
        return groups
      }, {})
    }
  },
  methods: {
    alertName (name, length) {
      return name + (this.expandable ? ` (${length})` : '')
    },
    selectAlert (alertId, isSelected) {
      if (isSelected) {
        this.selectedAlert = alertId
      } else if (this.selectedAlert === alertId) {
        this.selectedAlert = null
      }
    },
    toggleAlertGroup (name, length) {
      if (this.expandable) {
        if (this.selectedAlertGroup !== name) {
          this.selectedAlertGroup = name
        } else {
          this.selectedAlertGroup = null
        }
      }
    }
  }
})
</script>

