.alerts-container {
  overflow: hidden;
  width: 100%;
  clear: both;
  padding: 3px 0 3px 10px;
  margin-bottom: 2px;
  border-left: 7px solid;
}

.alerts-group-header {
  display: flex;
  width: 100%;
}

.alerts-group-header-expandable {
  cursor: pointer;
}

.alerts-group-header-label {
  flex: 1;
}

.alerts-group-header-label-selected {
  font-weight: bold;
}

.alerts-group-header-expand {
  flex: 0;
  transition: all 0.3s;
}

.alerts-group-alerts {
  clear: both;
}

.alerts-header {
  font-weight: bold;
  font-family: Merriweather, serif;
  padding-bottom: 10px;
}

.alerts-recent-link {
  color: #00e;
  cursor: pointer;
}
</style>
