<template>
  <i v-if="false" />
</template>

<script>
import * as validators from '../util/validators'
import { Timer } from '../util/timer'

/**
 * Convenience wrapper for a repeating {@link Timer} object.
 */
export default {
  props: {
    /**
     * The delay before firing the timer event.
     *
     * @return {Number|String}
     */
    delay: {
      type: [Number, Object, String],
      validator: value => validators.convertibleToDuration(value),
      required: true
    },
    /**
     * Whether the timer should be running currently.
     *
     * @return {Boolean}
     */
    enabled: {
      type: Boolean,
      default: true
    },
    /**
     * The name to give to the timer.
     *
     * @return {String}
     */
    name: {
      type: String,
      default: null
    }
  },
  data () {
    return {
      timer: new Timer(this.delay, {
        autostart: this.enabled,
        listeners: [this._onTimer],
        name: this.name,
        repeat: true
      })
    }
  },
  watch: {
    delay () {
      this.timer.delay = this.delay
    },
    enabled () {
      if (this.enabled && !this.timer.isRunning) {
        this.timer.start()
      } else if (!this.enabled && this.timer.isRunning) {
        this.timer.stop()
      }
    },
    name () {
      this.timer.name = this.name
    }
  },
  destroyed () {
    this.timer.stop()
  },
  methods: {
    _onTimer () {
      if (this.name) {
        this.$emit('timer', this.name)
      } else {
        this.$emit('timer')
      }
    }
  }
}
</script>
