<template>
  <cmi-layer-group
    v-if="filteredStations"
    id="localradar"
  >
    <!-- Local radar if a station is selected -->
    <cmi-timeline-wms
      v-if="layer"
      :id="`timeline-local-${layer}`"
      :layer="layer"
      :frame-count="mapFrames"
      :min-zoom="minZoom"
      :max-zoom="maxZoom"
      :opacity="opacity"
      :primary="true"
      :tile-size="[512,512]"
      :url="gisUrl(`${station.toLowerCase()}/${layer}`)"
      version="1.1.1"
      :z-index="zIndex"
    />
    <!-- Stations -->
    <cmi-layer-vector-shape
      id="stations"
      :opacity="stationOpacity"
      :z-index="zIndexStations"
      :features="stationsAsGeoJson"
      :location="closestCoordinates"
      :feature-id="station"
      :style-function="styleFunction"
      @selectFeature="setSelectedFeature"
    />
  </cmi-layer-group>
</template>

<script>
import { mapActions, mapGetters, mapMutations } from 'vuex'
import { Circle, RegularShape, Fill, Stroke, Style } from 'ol/style'

export default {
  props: {
    maxZoom: {
      type: Number,
      default: 10
    },
    minZoom: {
      type: Number,
      default: 4
    },
    opacity: {
      type: Number,
      default: 0.6
    },
    zIndex: {
      type: Number,
      required: true
    },
    zIndexStations: {
      type: Number,
      required: true
    }
  },
  data () {
    return {
      stationStatusColors: {
        up: {
          fill: 'rgba(84, 114, 210, 0.7)',
          stroke: 'rgba(42, 57, 105, 1)'
        },
        warning: {
          fill: 'rgba(255, 189, 51, 1)',
          stroke: 'rgba(127, 94, 25, 1)'
        },
        down: {
          fill: 'rgba(255, 0, 0, 0.3)',
          stroke: 'rgba(127, 0, 0, 1)'
        },
        unknown: {
          fill: 'rgba(127, 127, 127, 0.5)',
          stroke: 'rgba(63, 63, 63, 1)'
        }
      },
      unwatchLoadCheck: null
    }
  },
  computed: {
    ...mapGetters([
      'agenda',
      'zoom'
    ]),
    ...mapGetters('persist', {
      gisUrl: 'gisUrl',
      zoomDefaults: 'zoom',
      suppressBookmarkUntil: 'suppressBookmarkUntil'
    }),
    ...mapGetters('local', [
      'closestCoordinates',
      'filteredStations',
      'layer',
      'layers',
      'layerName',
      'layerData',
      'filter',
      'station',
      'stations',
      'stationData',
      'stationOpacity'
    ]),
    mapFrames () {
      if (this.layerData) {
        return this.layerData.frames
      }
      return undefined
    },
    stationsAsGeoJson () {
      return this.convertStationsToGeoJson(this.filteredStations)
    }
  },
  created () {
    // verify local data if the application was loaded with a bookmark or quick set url for a local agenda
    this.unwatchLoadCheck = this.$watch('stations', (newVal, oldVal) => {
      if (!this.suppressBookmarkUntil.includes('local')) {
        this.unwatchLoadCheck()
      } else if (this.stations && !this.stationData) {
        // invalid station in bookmark or url
        this.setStation(null)

        this.unwatchLoadCheck()
        this.removeBookmarkSuppress('local')
      } else if (this.stationData) {
        // stations loaded and valid station
        this.setSelected(`Station ${this.stationData.id} in ${this.stationData.name}`)
        //  Verify the selected radar has a valid default product layer
        if (this.layers.length > 0 && !this.layers.find(layer => layer.name === this.layerName)) {
          this.setLayerName(this.layers[0].name)
        }
        // Enable the map bookmark suppress until after map pans to local station
        this.addBookmarkSuppress('map')
        const zoom = this.zoom === this.zoomDefaults.default ? this.zoomDefaults.focus : this.zoom
        this.panTo({ center: this.stationData.coordinates, zoom: zoom, duration: 0 })

        this.unwatchLoadCheck()
        this.removeBookmarkSuppress('local')
      }
    })
  },
  methods: {
    ...mapActions('persist', [
      'panTo',
      'addBookmarkSuppress',
      'removeBookmarkSuppress'
    ]),
    ...mapMutations('local', {
      setLayerName: 'layerName',
      setStation: 'station'
    }),
    ...mapMutations('search', {
      setSelected: 'selected'
    }),
    convertStationsToGeoJson (stations) {
      let geojsonStations = []
      for (const stationId of Object.keys(stations)) {
        geojsonStations.push(this.createGeoJsonFeature(stations[stationId]))
      }
      return geojsonStations
    },
    createGeoJsonFeature (station) {
      return {
        type: 'Feature',
        id: station.id,
        geometry: {
          type: 'Point',
          coordinates: station.coordinates
        },
        properties: this.getStationProperties(station)
      }
    },
    getStationProperties (station) {
      const isTDWR = station.type === 'TDWR'
      const status = isTDWR ? 'unknown' : station.status

      return {
        status: status,
        coordinates: [station.coordinates[0], station.coordinates[1]],
        name: station.name,
        radius: station.radius,
        type: station.type,
        selected: station.id === this.station,
        style: {
          shape: isTDWR ? 'reg' : 'circle',
          points: isTDWR ? 4 : null,
          fill: this.stationStatusColors[status].fill,
          stroke: this.stationStatusColors[status].stroke,
          radius: isTDWR ? 13 : 10
        }
      }
    },
    styleFunction (feature) {
      let style = new Style({
        image: new Circle({
          stroke: new Stroke({
            color: 'green'
          }),
          fill: new Fill({
            color: 'white'
          }),
          radius: 3
        })
      })

      let styleOptions = feature.get('style')
      if (styleOptions) {
        if (styleOptions?.shape === 'reg') {
          style = new Style({
            image: new RegularShape({
              stroke: new Stroke({
                color: styleOptions?.stroke
              }),
              fill: new Fill({
                color: styleOptions?.fill
              }),
              points: styleOptions?.points,
              radius: styleOptions?.radius
            })
          })
        } else if (styleOptions?.shape === 'circle') {
          style = new Style({
            image: new Circle({
              stroke: new Stroke({
                color: styleOptions?.stroke
              }),
              fill: new Fill({
                color: styleOptions?.fill
              }),
              radius: styleOptions?.radius
            })
          })
        }
      }
      if (feature.get('selected') === true) {
        style.getImage().setOpacity(0)
      }
      return style
    },
    setSelectedFeature (feature) {
      if (feature) {
        if (feature.id !== this.station) {
          this.setStation(feature.id)
          this.setSelected(`Station ${feature.id} in ${feature.name}`)
          const zoom = this.zoom === this.zoomDefaults.default ? this.zoomDefaults.focus : this.zoom
          this.panTo({ center: feature.coordinates, zoom: zoom })
        } else {
          this.$cmi.log.debug(`${feature.id} station already selected`)
        }
      } else {
        this.$cmi.log.debug('Did not find any station upon map click')
      }
    }
  }
}
</script>
