<template>
  <app-panel>
    <app-panel-section>
      <app-panel-alerts
        :alerts="alerts"
        descriptor="viewable on the map"
        :error="alertsError"
        :expandable="true"
        instructions="Map calculating, please wait..."
        :loading="alertsLoading"
        :ready="extent !== null"
      >
        <template #help>
          <div class="alerts-help">
            <div>Too many alerts?</div>
            <div class="alerts-help-quickset">
              <div
                class="alerts-help-quickset-option"
                @click="limitToExtent(!alertsLimitToExtent)"
              >
                <span
                  :class="[
                    'fa',
                    alertsLimitToExtent ? 'fa-toggle-on' : 'fa-toggle-off'
                  ]"
                /> Limit alerts to map view
              </div>
              <div
                class="alerts-help-quickset-option"
                @click="setViewToWeather()"
              >
                <span class="fa fa-clone" /> Switch to Weather for a Location
              </div>
            </div>
          </div>
        </template>
      </app-panel-alerts>
    </app-panel-section>
  </app-panel>
</template>

<script>
import { mapGetters, mapActions, mapMutations } from 'vuex'
import { createWatcherMixin } from '~/components/mixins'

import AppPanel from '~/components/menu/Panel.vue'
import AppPanelAlerts from '~/components/menu/PanelAlerts.vue'
import AppPanelSection from '~/components/menu/PanelSection.vue'

export default {
  components: {
    AppPanel,
    AppPanelAlerts,
    AppPanelSection
  },
  mixins: [
    createWatcherMixin('alertsForExtent')
  ],
  computed: {
    ...mapGetters([
      'extent'
    ]),
    ...mapGetters('alerts', {
      alerts: 'alertsForExtent',
      alertsError: 'alertsForExtentError',
      alertsLoading: 'alertsForExtentLoading',
      alertsLimitToExtent: 'limitToExtent'
    })
  },
  methods: {
    ...mapActions([
      'setAgenda'
    ]),
    ...mapMutations('alerts', [
      'setLimitToExtent'
    ]),
    ...mapActions('menu', [
      'closePanel'
    ]),
    setViewToWeather () {
      this.closePanel()
      this.setAgenda('weather')
      if (this.$tracker) {
        this.$tracker('event', {
          action: 'alerts-view',
          label: 'weather'
        })
      }
    },
    limitToExtent (limit) {
      this.setLimitToExtent(limit)
      if (this.$tracker) {
        this.$tracker('event', {
          action: 'alerts-extent',
          label: 'limit'
        })
      }
    }
  }
}
</script>

