export class ForecastHour {
  constructor ({ daytime, details, number, short, temperature, probabilityOfPrecipitation, relativeHumidity, startTime, endTime, icon }) {
    this.__daytime = daytime
    this.__details = details
    this.__number = number
    this.__short = short
    this.__temperature = temperature
    this.__probabilityOfPrecipitation = probabilityOfPrecipitation
    this.__relativeHumidity = relativeHumidity
    this.__startTime = startTime
    this.__endTime = endTime
    this.__icon = icon
  }

  get daytime () {
    return this.__daytime
  }

  get details () {
    return this.__details
  }

  get number () {
    return this.__number
  }

  get short () {
    return this.__short
  }

  get temperature () {
    return this.__temperature
  }

  get probabilityOfPrecipitation () {
    return this.__probabilityOfPrecipitation
  }

  get relativeHumidity () {
    return this.__relativeHumidity
  }

  get startTime () {
    return this.__startTime
  }

  get endTime () {
    return this.__endTime
  }

  get icon () {
    return this.__icon
  }
}
