const mapRender = {
  render (h) {
    // borrowed heavily from https://github.com/ghettovoice/vuelayers/blob/master/src/mixins/stub-vnode.js
    const attrs = {
      id: this.id,
      class: this.class
    }

    const data = {
      attrs,
      style: {
        display: 'none !important'
      }
    }

    let children
    if (this.slots === false) {
      children = undefined
    } else {
      children = extractChildren(this.$scopedSlots.default?.({}))
    }

    return h('i', data, children)
  }
}

function extractChildren (slots, slotNames = []) {
  if (!slots) {
    return null
  }
  return Object.keys(slots).reduce((all, name) => {
    if (!slotNames.length || slotNames.includes(name)) {
      all = all.concat(slots[name])
    }
    return all
  }, [])
}

export {
  mapRender
}
