import 'core-js/stable'

import 'font-awesome/css/font-awesome.min.css'
import 'typeface-merriweather/index.css'
import 'weather-icons2/css/weather-icons.min.css'

import deepmerge from 'deepmerge'
import * as logLevel from 'loglevel'
import CMI from './cmi'
import * as log from './cmi/log'
import { SchemaValidationError, SchemaValidator } from './cmi/schema'
import App from './components/App.vue'
import Vue from 'vue'
import CmiRadar from './index'
import { SCHEMA_CMI_RADAR_CONFIG } from './schema'
import { createStore } from './store'

const DEFAULTS = {
  componentPrefix: 'cmi-radar-',
  instanceName: 'cmiRadar',
  urls: {
    alerts: 'https://alerts.weather.gov',
    api: 'https://api.weather.gov',
    forecast: 'https://forecast-v3.weather.gov',
    gis: 'https://opengeo-bldr.ncep.noaa.gov/geoserver'
  }
}

function plugin (Vue, options = {}, tracker) {
  options = deepmerge(DEFAULTS, options)

  let level = logLevel.levels.DEBUG
  if (process.env.NODE_ENV !== 'production') {
    level = logLevel.levels.SILENT
  }

  logLevel.getLogger('event').setDefaultLevel(level)
  logLevel.getLogger('vuex').setDefaultLevel(level)

  Vue.prototype.$tracker = tracker || function () {} // does nothing if not provided
  Vue.prototype[`$${options.instanceName}`] = {}
  Vue.component(`${options.componentPrefix}app`, App)
  Vue.use(CMI)

  const validator = new SchemaValidator({ schemas: [SCHEMA_CMI_RADAR_CONFIG] })
  try {
    validator.validate('/cmi-radar/config', options)
  } catch (err) {
    if (err instanceof SchemaValidationError) {
      log.error(err.message, err.config, err.errors)
    }
    throw err
  }

  Vue.prototype.$tracker = tracker || function () {} // does nothing if not provided

  Vue.prototype[`$${options.instanceName}`] = {}
  Vue.use(CMI)

  Vue.component(`${options.componentPrefix}app`, App)

  log.debug(
    'CMI radar initialized:' +
    `\n  Component prefix: ${options.componentPrefix}` +
    `\n  Instance name: ${options.instanceName}`
  )
}

export default plugin

export { createStore } from './store'

export function createApp (element, options, tracker) {
  if (options === undefined) {
    options = {}
  }
  Vue.use(CmiRadar, options, tracker)
  Vue.config.productionTip = false

  const store = createStore({
    settings: deepmerge({}, options.settings || {}),
    urls: deepmerge({}, options.urls || {}),
    apiKey: options.apiKey || null,
    esriKey: options.esriKey || null,
    timezone: options.timezone || undefined
  })

  return new Vue({
    el: element,
    store,
    template: '<cmi-radar-app />'
  })
}
