<template>
  <app-panel>
    <app-panel-section>
      <div
        class="station-heading"
      >
        Local Station Information
      </div>
      <div class="station-information">
        Station latency: {{ latencyMessage }}
      </div>
      <div class="station-information">
        <template
          v-if="stationStatusLoading"
        >
          Loading station information...
        </template>
        <template
          v-else-if="stationStatusError"
        >
          There was an error loading station information.
        </template>
        <template
          v-else-if="stationData && stationData.type === 'TDWR'"
        >
          TDWR stations are not monitored for status
        </template>
        <template
          v-else-if="!stationStatus"
        >
          There is no additional information available.
        </template>
        <template
          v-else
        >
          {{ stationStatus }}
        </template>
      </div>
    </app-panel-section>
  </app-panel>
</template>

<script>
import { mapGetters } from 'vuex'
import { createWatcherMixin } from '~/components/mixins'

import AppPanel from '~/components/menu/Panel.vue'
import AppPanelSection from '~/components/menu/PanelSection.vue'

export default {
  components: {
    AppPanel,
    AppPanelSection
  },
  mixins: [createWatcherMixin('radarStationStatus')],
  computed: {
    ...mapGetters('local', [
      'stationData',
      'stationStatus',
      'stationStatusError',
      'stationStatusLoading'
    ]),
    latencyMessage () {
      if (this.stationData && this.stationData.latency) {
        const latency = Math.round(this.stationData.latency)
        if (latency === 0) {
          return 'none'
        } else if (latency < 60) {
          return `${latency} minute${latency > 1 ? 's' : ''}`
        } else {
          return 'over an hour'
        }
      }
      return 'unknown'
    }
  }
}
</script>

<style scoped>
.station-heading {
  font-weight: bold;
  font-family: Merriweather, serif;
  padding-bottom: 10px;
}

.station-information {
  padding-bottom: 10px;
}
</style>
