
export class Point {
  constructor ({ coordinates, forecastUrl, forecastHourlyUrl, officeUrl, stationsUrl, valid }) {
    this.__coordinates = coordinates
    this.__forecastUrl = forecastUrl
    this.__forecastHourlyUrl = forecastHourlyUrl
    this.__officeUrl = officeUrl
    this.__stationsUrl = stationsUrl
    this.__valid = valid
  }

  get coordinates () {
    return this.__coordinates
  }

  get forecastUrl () {
    return this.__forecastUrl
  }

  get forecastHourlyUrl () {
    return this.__forecastHourlyUrl
  }

  get officeUrl () {
    return this.__officeUrl
  }

  get stationsUrl () {
    return this.__stationsUrl
  }

  get valid () {
    return this.__valid
  }
}
