import convert from 'convert-units'
import { DateTime } from 'luxon'

import { LoadingError, ResourceLoader } from '~/cmi/loaders'
import * as log from '~/cmi/log'
import { Observation, ObservationStation } from '~/entities'

export async function loadObservation (url, key) {
  const options = {
    headers: {
      'Accept': 'application/geo+json'
    },
    responseType: 'json'
  }
  if (key !== null) {
    options.headers['API-Key'] = key
  }

  log.info(`Requesting observation data from ${url}`)

  const loader = new ResourceLoader()
  return loader.load(url, options, response => {
    try {
      const stationId = response.data.properties.station.split('/').pop()

      let temperature = response.data.properties.temperature.value
      if (temperature !== null) {
        temperature = Math.round(convert(temperature).from('C').to('F'))
      }

      const obs = new Observation({
        station: stationId,
        temperature: temperature,
        text: response.data.properties.textDescription,
        time: DateTime.fromISO(response.data.properties.timestamp, { zone: 'UTC' }),
        icon: response.data.properties.icon
      })
      log.debug(`Received latest observation for ${stationId}`, obs)

      return obs
    } catch (err) {
      throw new LoadingError(`Error reading latest observation from ${url}`, err)
    }
  })
}

export async function loadObservationStations (url, key) {
  const options = {
    headers: {
      'Accept': 'application/geo+json'
    },
    responseType: 'json'
  }
  if (key !== null) {
    options.headers['API-Key'] = key
  }
  log.info(`Requesting observation station data from ${url}`)

  const loader = new ResourceLoader()
  return loader.load(url, options, response => {
    const stations = response.data.features.map(data => {
      return new ObservationStation({
        id: data.properties.stationIdentifier,
        coordinates: data.geometry.coordinates,
        name: data.properties.name,
        obsUrl: `${data.properties['@id']}/observations/latest`,
        timeZone: data.properties.timeZone
      })
    })
    log.debug(`Retrieved obs station data from ${url}`, stations)

    return stations
  })
}
