import { DateTime } from 'luxon'
import xmldom from 'xmldom'
import xpath from 'xpath'

import { LoadingError, ResourceLoader, WFS, WMS } from '~/cmi/loaders'
import * as log from '~/cmi/log'
import { Alert, AlertSummary } from '~/entities'

export async function loadAlert (apiBaseUrl, apiKey, id) {
  const url = `${apiBaseUrl}/alerts/${id}`
  const options = {
    headers: {
      'Accept': 'application/geo+json'
    },
    responseType: 'json'
  }
  if (apiKey !== null) {
    options.headers['API-Key'] = apiKey
  }

  log.info(`Requesting alert data for ${id} from ${url}`)

  const loader = new ResourceLoader()
  return loader.load(url, options, response => {
    try {
      const properties = response.data.properties
      const capId = properties.id
      const capEvent = properties.event

      let vtec = null
      if (properties.parameters && properties.parameters.VTEC && properties.parameters.VTEC.length > 0) {
        vtec = properties.parameters.VTEC[0]
      }

      const alert = new Alert({
        id: capId,
        areaDesc: properties.areaDesc,
        affectedZones: properties.affectedZones,
        certainty: properties.certainty,
        category: properties.category,
        description: properties.description,
        ends: properties.ends !== null ? DateTime.fromISO(properties.ends, { zone: 'UTC' }) : null,
        eventCode: `${properties.eventCode?.SAME?.[0] || ''}/${properties.eventCode?.NationalWeatherService?.[0] || ''}`,
        event: capEvent,
        expiration: DateTime.fromISO(properties.ends ? properties.ends : properties.expires, { zone: 'UTC' }),
        // Correctly defining "expires" property since CAP does not officially have an expiration time
        // I believe naming it expiration was derrived from the shapefile when pulled from GIS
        // This will be corrected "soon" for cmi-radar, but Radar needs it correct as "expires"
        expires: DateTime.fromISO(properties.ends ? properties.ends : properties.expires, { zone: 'UTC' }),
        headline: properties.headline,
        instruction: properties.instruction,
        issuance: DateTime.fromISO(properties.effective, { zone: 'UTC' }),
        // Correctly defining "effective" property since CAP does not officially have an issuance time
        // I believe naming it issuance was derrived from the shapefile when pulled from GIS
        // This will be corrected "soon" for cmi-radar, but Radar needs it correct as "effective"
        effective: DateTime.fromISO(properties.effective, { zone: 'UTC' }),
        onset: properties.onset !== null ? DateTime.fromISO(properties.onset, { zone: 'UTC' }) : null,
        response: properties.response,
        messageType: properties.messageType,
        sender: properties.sender,
        senderName: properties.senderName,
        sent: DateTime.fromISO(properties.sent, { zone: 'UTC' }),
        status: properties.status,
        severity: properties.severity,
        urgency: properties.urgency,
        url: properties['@id'],
        vtec: vtec
      })
      log.debug(`Found details for ${capEvent} alert ${capId}`, alert)

      return alert
    } catch (err) {
      throw new LoadingError(`Error reading alert details for ${id}`, err)
    }
  })
}

export async function loadAlertsForExtent ({ layer, url, extent, time }) {
  let params = {
    srsName: 'EPSG:4326',
    cql_filter: extent ? `BBOX(geom,${extent},'EPSG:4326')` : '',
    propertyName: 'cap_id,expiration,issuance,prod_type,url,warnid,wfo'
  }
  // if not specified, current alerts will be returned
  if (time instanceof DateTime) {
    params.cql_filter += `${params.cql_filter.length > 0 ? ' AND ' : ''}IDP_FileDate = ${time.toISO()}`
  }

  log.info(`Requesting alerts list for ${time ? time.toISO() : 'current'} from ${url}`)

  const wfs = new WFS(url, '2.0.0')
  const featureCollection = await wfs.getFeature(layer, params)

  try {
    const alerts = featureCollection.features.reduce((map, feature) => {
      const capId = feature.properties.cap_id
      if (capId === null) {
        return map
      }

      const bbox = feature.properties.bbox || feature.bbox // support for new and old geojson schema

      // If we have already seen this alert (e.g. alert has multiple UGC codes), merge the bounding boxes
      if (map.hasOwnProperty(capId)) {
        // make sure a previous bbox exists
        if (map[capId].bbox === undefined) {
          map[capId].bbox = bbox
        } else {
          map[capId].bbox = mergeBoundingBoxes([map[capId].bbox, bbox])
          map[capId].incZoneCount()
        }
      } else {
        map[capId] = new AlertSummary({
          id: capId,
          event: feature.properties.prod_type,
          expiration: feature.properties.expiration
            ? DateTime.fromISO(feature.properties.expiration, { zone: 'UTC' })
            : null,
          issuance: DateTime.fromISO(feature.properties.issuance, { zone: 'UTC' }),
          // Alerts Shapefile Generator uses the VTEC to determine the issuing office
          // Keith approved using "NWS" as default for alerts without VTEC
          office: feature.properties.wfo || 'NWS',
          url: feature.properties.url,
          vtec: feature.properties.warnid === null ? null : `/${feature.properties.warnid}/`,
          bbox: bbox
        })
      }

      return map
    }, {})
    log.debug(`Retrieved alerts for ${time ? time.toISO() : 'current'}`, alerts)

    return Object.values(alerts)
  } catch (err) {
    throw new LoadingError('Error reading alerts', err)
  }
}

export async function loadAlertColors (url) {
  log.info(`Requesting alerts styles (hazards layer) from ${url}`)

  try {
    const wms = new WMS(url, '1.1.1')
    const xml = await wms.getStyles('hazards')

    const doc = new xmldom.DOMParser().parseFromString(xml)
    const select = xpath.useNamespaces({ sld: 'http://www.opengis.net/sld' })
    const userStyles = select('//sld:StyledLayerDescriptor/sld:NamedLayer/sld:UserStyle', doc)

    // Use the default style if one is set.
    // Otherwise, assume that the first is the one we want.
    let userStyle = userStyles[0]
    for (const userStyleChoice of userStyles) {
      const isDefault = select('number(sld:IsDefault)', userStyleChoice)
      if (isDefault) {
        userStyle = userStyleChoice
      }
    }

    const styles = select('sld:FeatureTypeStyle', userStyle).reduce((map, style) => {
      try {
        for (const rule of select('sld:Rule', style)) {
          try {
            const name = select('string(sld:Name)', rule)
            // Disregard the outline styles
            if (name !== 'outline') {
              map[name] = select('string(sld:PolygonSymbolizer/sld:Fill/sld:CssParameter)', rule)
            }
          } catch (error) {
            log.warn(`Could not read name or color for style rule: ${error.stack}\n`, rule)
          }
        }
      } catch (error) {
        log.warn('Could not read name or color for style', style)
      }

      return map
    }, {})
    log.debug(`Received styles from ${url}`, styles)

    return styles
  } catch (err) {
    throw new LoadingError(`Error reading styles from ${url}`, err)
  }
}

const mergeBoundingBoxes = (boundingBoxes) => {
  let minLeft = 180
  let minBottom = 90
  let maxRight = -180
  let maxTop = -90

  boundingBoxes.forEach(([left, bottom, right, top]) => {
    if (left < minLeft) minLeft = left
    if (bottom < minBottom) minBottom = bottom
    if (right > maxRight) maxRight = right
    if (top > maxTop) maxTop = top
  })

  return [minLeft, minBottom, maxRight, maxTop]
}
