import { LoadingError, ResourceLoader } from '~/cmi/loaders'
import * as log from '~/cmi/log'
import { TextProduct, TextProductSummary } from '~/entities'

export async function loadTextProduct (url, key) {
  const options = {
    headers: {
      'Accept': 'application/ld+json'
    },
    responseType: 'json'
  }
  if (key !== null) {
    options.headers['API-Key'] = key
  }

  log.info(`Requesting text product from ${url}`)

  const loader = new ResourceLoader()
  return loader.load(url, options, response => {
    try {
      const product = new TextProduct({
        id: response.data.id,
        code: response.data.productCode,
        name: response.data.productName,
        text: response.data.productText,
        url: response.data['@id']
      })
      log.debug(`Retrieved text product ${response.data.id}`, product)

      return product
    } catch (err) {
      throw new LoadingError(`Error reading product summary from ${url}`, err)
    }
  })
}

export async function loadTextProductSummary ({ apiBaseUrl, apiKey, productType, locationId }) {
  const url = `${apiBaseUrl}/products/types/${productType}/locations/${locationId}`
  const options = {
    headers: {
      'Accept': 'application/ld+json'
    },
    responseType: 'json'
  }
  if (apiKey !== null) {
    options.headers['API-Key'] = apiKey
  }

  log.info(`Requesting text products from ${url}`)

  const loader = new ResourceLoader()
  return loader.load(url, options, response => {
    try {
      if (response.data['@graph'].length === 0) {
        log.debug(`Found no text products at ${url}`)
        return []
      }

      const products = response.data['@graph'].map(data => {
        return new TextProductSummary({
          id: data.id,
          code: data.productCode,
          name: data.productName,
          url: data['@id']
        })
      })
      log.debug(`Retrieved text product summaries from ${url}`, products)

      return products
    } catch (err) {
      throw new LoadingError(`Error reading product summary from ${url}`, err)
    }
  })
}
