import axios from 'axios'
import { setupCache } from 'axios-cache-adapter'
import localforage from 'localforage'

import * as log from '~/cmi/log'

const storage = localforage.createInstance({ name: 'http-cache' })
const cache = setupCache({
  readHeaders: true,
  maxAge: 1 * 60 * 1000, // 1 minute default
  store: storage
})

const client = axios.create({
  adapter: cache.adapter
})

export const HTTP = {
  createCancellationToken: () => {
    const source = axios.CancelToken.source()
    source.token.cancel = function () {
      log.warn(`Cancelling request`)
      source.cancel()
    }
    source.token.isCancelled = function () {
      return Boolean(source.token.reason)
    }
    return source.token
  },
  delete: (...args) => {
    log.debug(`Sending DELETE request`, args)
    return client.delete(...args)
  },
  get: (...args) => {
    log.debug(`Sending GET request`, args)
    return client.get(...args)
  },
  isCancellation: (error) => axios.isCancel(error),
  head: (...args) => {
    log.debug(`Sending HEAD request`, args)
    return client.head(...args)
  },
  post: (...args) => {
    log.debug(`Sending POST request`, args)
    return client.post(...args)
  },
  put: (...args) => {
    log.debug(`Sending PUT request`, args)
    return client.put(...args)
  }
}
