<template>
  <app-panel>
    <app-panel-option
      v-show="!focus"
      :label="kmlOptionLabel"
      :default-expand="!!kmlName"
      :expands="!!kmlName"
    >
      <template #icon>
        <span class="fa fa-download" />
      </template>
      <ul
        v-if="kmlName"
        class="option-content-list"
      >
        <li>
          <a
            :href="kmlLink('alaska')"
            target="_new"
            @click="downloadKML('alaska')"
          >Alaska
          </a>
        </li>
        <li>
          <a
            :href="kmlLink('conus')"
            target="_new"
            @click="downloadKML('conus')"
          >Conus
          </a>
        </li>
        <li>
          <a
            :href="kmlLink('carib')"
            target="_new"
            @click="downloadKML('carib')"
          >Caribbean
          </a>
        </li>
        <li>
          <a
            :href="kmlLink('guam')"
            target="_new"
            @click="downloadKML('guam')"
          >Guam
          </a>
        </li>
        <li>
          <a
            :href="kmlLink('hawaii')"
            target="_new"
            @click="downloadKML('hawaii')"
          >Hawaii
          </a>
        </li>
      </ul>
    </app-panel-option>
    <app-panel-option-group
      v-show="!focus || focus === 'hazards' || focus === 'nationalradar'"
      label="Layer Options"
    >
      <template #icon>
        <span class="config-item-icon fa fa-tasks" />
      </template>
      <app-panel-hazards-option
        v-show="!focus || focus == 'hazards'"
      />
      <app-panel-national-radar-option
        v-show="!focus || focus == 'nationalradar'"
        :agenda-bar-override="{
          product: true
        }"
      />
    </app-panel-option-group>
  </app-panel>
</template>

<script>
import AppPanel from '~/components/menu/Panel.vue'
import AppPanelOption from '~/components/menu/PanelOption.vue'
import AppPanelOptionGroup from '~/components/menu/PanelOptionGroup.vue'
import AppPanelHazardsOption from '~/components/menu/panels/options/Hazards.vue'
import AppPanelNationalRadarOption from '~/components/menu/panels/options/NationalRadar.vue'

import { MAPS } from '~/config'
import { mapGetters } from 'vuex'

export default {
  components: {
    AppPanel,
    AppPanelOption,
    AppPanelOptionGroup,
    AppPanelHazardsOption,
    AppPanelNationalRadarOption
  },
  data () {
    return {
      nationalProducts: MAPS.national
    }
  },
  computed: {
    ...mapGetters([
      'nationalMap'
    ]),
    ...mapGetters('persist', [
      'gisBaseUrl'
    ]),
    ...mapGetters('menu', [
      'focus'
    ]),
    kmlName () {
      for (let i = 0; i < this.nationalProducts.length; i++) {
        if (this.nationalProducts[i].name === this.nationalMap) {
          return `Mosaic ${this.nationalProducts[i].text}`
        }
      }
      return null
    },
    kmlOptionLabel () {
      if (this.kmlName) {
        return `Download KML for ${this.kmlName}`
      } else {
        return 'KML not provided for this product'
      }
    }
  },
  methods: {
    downloadKML (name) {
      if (this.$tracker) {
        this.$tracker('event', {
          action: 'download',
          label: `national-${name}`
        })
      }
    },
    kmlLink (region) {
      return `${this.gisBaseUrl}/wms/kml?layers=${region}:${region}_${this.nationalMap}`
    }
  }
}
</script>
