<template>
  <app-menu-agenda :title="title">
    <app-menu-agenda-actions options-panel="localoptions">
      <app-menu-agenda-message v-if="!station || !stations">
        <template v-if="!stations">
          Loading stations...
        </template>
        <template v-else>
          Select a <span class="fa iconWSR88D">&#xf111;</span> WSR-88D or <span class="fa iconTdwr">&#xf04d;</span> TDWR station
        </template>
      </app-menu-agenda-message>
      <template v-else>
        <app-menu-agenda-action-item
          :icon="statusIcon"
          :label="station !== null ? 'Status' : '--'"
          panel="localstatus"
        />
        <app-menu-agenda-action-item
          label="Product"
          panel="localproduct"
        />
        <app-menu-agenda-action-item
          :icon="alertsIcon"
          :label="alertsLabel"
          panel="alertsextent"
        />
      </template>
    </app-menu-agenda-actions>
  </app-menu-agenda>
</template>

<script>
import { mapGetters } from 'vuex'
import { createWatcherMixin } from '~/components/mixins'

import AppMenuAgenda from '../Agenda.vue'
import AppMenuAgendaActions from '../AgendaActions.vue'
import AppMenuAgendaActionItem from '../AgendaActionItem.vue'
import AppMenuAgendaMessage from '../AgendaMessage.vue'

export default {
  components: {
    AppMenuAgenda,
    AppMenuAgendaActions,
    AppMenuAgendaActionItem,
    AppMenuAgendaMessage
  },
  mixins: [
    createWatcherMixin('alertsForExtent', 'persist/suppressBookmark', false),
    createWatcherMixin('radarStations')
  ],
  computed: {
    ...mapGetters([
      'extent'
    ]),
    ...mapGetters('persist', [
      'suppressBookmarkUntil',
      'zoom'
    ]),
    ...mapGetters('menu', [
      'panel'
    ]),
    ...mapGetters('local', [
      'filter',
      'layers',
      'layerData',
      'station',
      'stations',
      'stationData'
    ]),
    ...mapGetters('alerts', [
      'alertsForExtent',
      'alertsForExtentLoading'
    ]),
    title () {
      let title = 'Local radar'
      if (this.layerData) {
        title = title + ` for ${this.layerData.longText}`
      }
      return title
    },
    alertsIcon () {
      if (this.alertsForExtentLoading) {
        return 'fa fa-circle-o-notch fa-spin'
      }
      if (this.alertsForExtent.length) {
        return 'fa fa-check-circle'
      }
      return 'fa fa-warning'
    },
    alertsLabel () {
      if (this.alertsForExtent) {
        const length = this.alertsForExtent.length
        if (length > 0) {
          return `${length} Alert${length > 1 ? 's' : ''}`
        } else {
          return 'No Alerts'
        }
      } else {
        return '--'
      }
    },
    statusIcon () {
      if (this.stationData) {
        if (this.stationData.status === 'up') {
          return 'fa fa-check-circle'
        } else if (this.stationData.status === 'warning') {
          return 'fa fa-exclamation-circle'
        } else {
          return 'fa fa-times-circle'
        }
      }
      return null
    }
  }
}
</script>

<style lang="scss" scoped>
.iconTdwr {
  transform: rotate(-45deg);
  padding-left: 2px;
  font-size: 88%;
}
</style>
