<template>
  <app-menu-option
    :class="[
      'menu-item menu-item-allclick',
      expanded ? '' : 'menu-itemStatic',
    ]"
    @click.native="panel = 'selectagenda'"
  >
    <span class="icon" />
    <span
      v-if="expanded"
    >
      Select View
    </span>
  </app-menu-option>
</template>

<script>
import AppMenuOption from '../MenuOption.vue'

export default {
  components: {
    AppMenuOption
  },
  props: {
    expanded: {
      type: Boolean,
      default: false
    }
  },
  computed: {
    panel: {
      get () { return this.$store.getters['menu/panel'] },
      set (input) { this.$store.dispatch('menu/togglePanel', input) }
    }
  }
}
</script>

<style lang="scss" scoped>
.menu-item {
  .icon::before { /* stylelint-disable-line no-descending-specificity */
    content: '\f24d';
  }
}
</style>
