<template>
  <app-menu-option
    class="menu-item menu-itemStatic"
    @click.native="onClick"
  >
    <span class="icon" />
  </app-menu-option>
</template>

<script>
import AppMenuOption from '../MenuOption.vue'

export default {
  components: {
    AppMenuOption
  },
  computed: {
    showMenu: {
      get () { return this.$store.getters['menu/show'] },
      set (value) { this.$store.commit('menu/show', value) }
    },
    currentPanel: {
      get () { return this.$store.getters['menu/panel'] },
      set (value) { this.$store.dispatch('menu/togglePanel', value) }
    }
  },
  methods: {
    onClick () {
      if (!this.showMenu) {
        this.showMenu = true
      } else {
        this.currentPanel = 'config'
      }
    }
  }
}
</script>

<style lang="scss" scoped>
.menu-item {
  .icon::before { /* stylelint-disable-line no-descending-specificity */
    content: '\f0c9';
  }
}
</style>
