<template>
  <app-panel>
    <app-panel-section>
      <app-panel-alerts
        :alerts="alerts"
        descriptor="for this location"
        :error="alertsError"
        :expandable="false"
        instructions="Please select a location"
        :loading="alertsLoading"
        :ready="location !== null"
      />
    </app-panel-section>
  </app-panel>
</template>

<script>
import { mapGetters } from 'vuex'
import { createWatcherMixin } from '~/components/mixins'

import AppPanel from '~/components/menu/Panel.vue'
import AppPanelAlerts from '~/components/menu/PanelAlerts.vue'
import AppPanelSection from '~/components/menu/PanelSection.vue'

export default {
  components: {
    AppPanel,
    AppPanelAlerts,
    AppPanelSection
  },
  mixins: [
    createWatcherMixin('alertsForPoint')
  ],
  computed: {
    ...mapGetters([
      'location'
    ]),
    ...mapGetters('alerts', {
      alerts: 'alertsForPoint',
      alertsError: 'alertsForPointError',
      alertsLoading: 'alertsForPointLoading'
    })
  }
}
</script>

