<template>
  <div class="control-bar">
    <div :class="timelineClasses">
      <slot name="info">
        <cmi-control-bar-info :animation-enabled="showAnimationControl">
          <div>Radar Times</div>
          <div>Not Available</div>
        </cmi-control-bar-info>
      </slot>
      <cmi-control-bar-progress
        v-if="status === 'valid'"
        :position="currentFrame"
        :total="totalFrames"
      />
    </div>
    <div class="controls">
      <div
        v-if="showZoomControl"
        class="button button-zoomin"
        title="Zoom in"
        @click="$emit('zoomIn')"
      />
      <div
        v-if="showZoomControl"
        class="button button-zoomout"
        title="Zoom out"
        @click="$emit('zoomOut')"
      />
      <div
        :class="['button', 'offset', animationRunning ? 'button-pause' : 'button-play', !showAnimationControl ? 'disabled' : '']"
        :title="animationRunning ? 'Pause' : 'Play'"
        @click="toggleAnimation"
      />
      <template v-if="animationRunning">
        <div class="speedBar">
          <div
            class="button button-speeddown"
            title="Slower"
            @click="changeFrameSpeed(-1)"
          />
          <div
            class="speedBarIndicator"
          >
            <div
              v-for="speed in animationFrameDelayMax"
              :key="`speed${speed}`"
              class="speedBarStep"
              :class="{'active':speed <= animationFrameSpeed}"
            >
              &nbsp;
            </div>
          </div>
          <div
            class="button button-speedup"
            title="faster"
            @click="changeFrameSpeed(1)"
          />
        </div>
      </template>
      <template v-else>
        <div
          :class="['button', 'button-stepstart', !showAnimationControl ? 'disabled' : '']"
          title="Step to Start"
          @click="emitAction('gotoFirstFrame')"
        />
        <div
          :class="['button', 'button-stepback', !showAnimationControl ? 'disabled' : '']"
          title="Step Back"
          @click="emitAction('gotoPreviousFrame')"
        />
        <div
          :class="['button', 'button-stepfwd', !showAnimationControl ? 'disabled' : '']"
          title="Step Forward"
          @click="emitAction('gotoNextFrame')"
        />
        <div
          :class="['button', 'button-stepend', !showAnimationControl ? 'disabled' : '']"
          title="Step to End"
          @click="emitAction('gotoLastFrame')"
        />
      </template>
    </div>
    <cmi-legend
      :legend="legend"
      :width-override="30"
    />
  </div>
</template>

<script>
import CmiLegend from './Legend.vue'
import CmiControlBarInfo from './ControlBarInfo.vue'
import CmiControlBarProgress from './ControlBarProgress.vue'

export default {
  components: {
    CmiLegend,
    CmiControlBarInfo,
    CmiControlBarProgress
  },
  props: {
    animationFrameSpeed: {
      type: Number,
      default: 4
    },
    animationFrameDelayMax: {
      type: Number,
      default: 1
    },
    /**
     * Whether or not the map is animating.
     *
     * @type {Boolean}
     */
    animationRunning: {
      type: Boolean,
      required: true
    },
    status: {
      type: String,
      default: 'invalid',
      fallback: true
    },
    currentFrame: {
      type: Number,
      default: 0
    },
    legend: {
      type: String,
      default: null
    },
    maxZoom: {
      type: Number,
      validator: value => value >= 0,
      default: 10
    },
    minZoom: {
      type: Number,
      validator: value => value >= 0,
      default: 0
    },
    totalFrames: {
      type: Number,
      default: 0
    },
    zoom: {
      type: Number,
      default: 3
    }
  },
  computed: {
    showAnimationControl () {
      return this.totalFrames > 0 && this.$status === 'valid'
    },
    showZoomControl () {
      return true
    },
    timelineClasses () {
      return {
        timeline: true,
        timelineWarning: this.$status === 'warning',
        timelineError: this.$status === 'error'
      }
    }
  },
  methods: {
    changeFrameSpeed (delta) {
      if ((delta < 0 && this.animationFrameSpeed > 1) ||
          (delta > 0 && this.animationFrameSpeed < this.animationFrameDelayMax)) {
        this.$emit('update:animationFrameSpeed', this.animationFrameSpeed + delta)
      }
    },
    emitAction (action) {
      if (this.showAnimationControl) {
        this.$emit(action)
      }
    },
    toggleAnimation () {
      if (this.showAnimationControl) {
        this.$emit('update:animationRunning', !this.animationRunning)

        if (this.$tracker) {
          this.$tracker('event', {
            action: 'play',
            label: !this.animationRunning ? 'start' : 'stop'
          })
        }
      }
    }
  }
}
</script>

