<template>
  <app-panel-option
    id="hazards"
    label="Hazards"
    :expands="true"
  >
    <template #fixed>
      <app-panel-option-slider
        store="alerts/opacity"
      />
    </template>
    <app-panel-option-list
      title="Type"
    >
      <div
        v-for="alertType in alertTypes"
        :key="alertType.id"
      >
        <input
          v-model="shortFusedOnly"
          name="shortFusedOnly"
          type="radio"
          :value="alertType.id === 'warnings'"
        >
        {{ alertType.name }}
      </div>
    </app-panel-option-list>
  </app-panel-option>
</template>

<script>
import AppPanelOption from '~/components/menu/PanelOption.vue'
import AppPanelOptionList from '~/components/menu/PanelOptionList.vue'
import AppPanelOptionSlider from '~/components/menu/PanelOptionSlider.vue'

import { ALERTS } from '~/config'

export default {
  components: {
    AppPanelOption,
    AppPanelOptionList,
    AppPanelOptionSlider
  },
  data () {
    return {
      alertTypes: ALERTS
    }
  },
  computed: {
    shortFusedOnly: {
      get () { return this.$store.getters['alerts/shortFusedOnly'] },
      set (value) { this.$store.commit('alerts/setShortFusedOnly', value) }
    }
  }
}
</script>
