import * as log from '~/cmi/log'

function createDefaultState () {
  return {
    focus: null,
    panel: null,
    panelButtons: [],
    showMenu: true,
    disableMenu: false
  }
}

export default {
  namespaced: true,
  state: createDefaultState(),
  mutations: {
    focus (state, input) {
      state.focus = input
    },
    panel (state, input) {
      if (input !== null && typeof (input) !== 'string') {
        log.error('Invalid panel name (must be a string or null):', input)
        return
      }
      state.panel = input
    },
    panelButtons (state, input) {
      state.panelButtons = input
    },
    reset (state) {
      Object.assign(state, createDefaultState())
    },
    show (state, input) {
      state.showMenu = input
    },
    disable (state, input) {
      state.disableMenu = input
    }
  },
  actions: {
    addPanelButton: ({ commit, getters }, input) => {
      commit('panelButtons', getters.panelButtons.concat(input))
    },
    closePanel: ({ commit, dispatch }) => {
      dispatch('togglePanel')
    },
    togglePanel: ({ commit, getters }, input) => {
      commit('panelButtons', [])
      if (getters.panel !== null && (typeof input === 'undefined' || input === getters.panel)) {
        log.debug(`Closing menu panel "${getters.panel}"`)
        commit('panel', null)
      } else if (input) {
        log.debug(`Toggling menu panel "${input}"`)
        commit('panel', input)
      }
      commit('focus', null)
    }
  },
  getters: {
    focus: state => state.focus,
    panel: state => state.panel,
    panelButtons: state => state.panelButtons,
    show: state => state.showMenu,
    disable: state => state.disableMenu
  }
}
