import deepmerge from 'deepmerge'
import { mapGetters } from 'vuex'

// "when" defines a store property that determines when to add the watcher
// "value" defines what the "when" value should be to add the watcher; defaults to truthy store property value
export function createWatcherMixin (watched, when, value) {
  let mixin = {
    created () {
      if (!when) {
        this.$store.commit('watchers/addWatcher', watched)
      }
    },
    destroyed () {
      this.$store.commit('watchers/removeWatcher', watched)
    }
  }
  if (when) {
    // compute a unique name to avoid conflicts with components
    const computedName = `watcherWhen_${when.replace('/', '')}`
    return deepmerge(mixin, {
      computed: {
        // associate getter to computed name
        ...mapGetters({
          [computedName]: when
        })
      },
      data () {
        return {
          watcherWhenValues: {
            [computedName]: value
          }
        }
      },
      watch: {
        [computedName]: {
          immediate: true,
          handler () {
            if ((this.watcherWhenValues[computedName] !== 'undefined' && this[computedName] === this.watcherWhenValues[computedName]) ||
              (this.watcherWhenValues[computedName] === 'undefined' && this[computedName])) {
              this.$store.commit('watchers/addWatcher', watched)
            }
          }
        }
      }
    })
  }
  return mixin
}
