import { DateTime, Duration } from 'luxon'

/**
 * Checks whether a value can be used with convertDuration.
 *
 * This method extends ISO8601 to recognize a leading minus for a duration
 * string.
 *
 * @private
 * @param {*} value
 * @returns {boolean}
 */
export function convertibleToDuration (value) {
  if (value === null || isInteger(value) || Duration.isDuration(value)) {
    return true
  }
  if (typeof value === 'string') {
    if (value.length) {
      if (value[0] === '-') {
        value = value.substring(1)
      }
      return Duration.fromISO(value).isValid
    }
  }
  return false
}

/**
 * Checks whether a value can be used with convertDurationOrTime.
 *
 * @private
 * @param {*} value
 * @returns {boolean}
 */
export function convertibleToDurationOrTime (value) {
  return convertibleToDuration(value) || convertibleToTime(value)
}

/**
 * Checks whether a value can be used with convertTime.
 *
 * @private
 * @param {*} value
 * @returns {boolean}
 */
export function convertibleToTime (value) {
  return value === null ||
    value instanceof Date ||
    isInteger(value) ||
    DateTime.isDateTime(value) ||
    (typeof value === 'string' && DateTime.fromISO(value).isValid)
}

/**
 * Checks whether a value is an integer or string representation of one.
 *
 * @private
 * @param {*} value
 * @returns {boolean}
 */
export function isInteger (value) {
  if (isNaN(value)) {
    return false
  }
  let x = parseInt(value, 10)
  return (x | 0) === x
}

/**
 * Checks whether a value is a valid longitude/latitude pair.
 *
 * @private
 * @param {*} value
 * @returns {boolean}
 */
export function lonLat (value) {
  return Array.isArray(value) && value.length === 2 &&
    value[0] >= -180 &&
    value[0] <= 180 &&
    value[1] >= -90 &&
    value[1] <= 90
}

/**
 * Checks whether a value is defined and non-null (but can be empty).
 *
 * @private
 * @param {*} value
 * @returns {boolean}
 */
export function notNull (value) {
  return value !== undefined && value !== null
}
