<template>
  <app-panel>
    <app-panel-section
      description="Select a view to display relevant radar products and weather information. Use the down arrow to see details about each view."
    >
      <app-agenda-option
        v-for="item in agendas"
        :id="item.id"
        :key="item.id"
        :item="item"
        @agenda:select="onAgendaSelect"
      />
    </app-panel-section>
  </app-panel>
</template>

<script>
import { mapActions } from 'vuex'
import { AGENDAS } from '~/config'

import AppAgendaOption from '~/components/menu/AgendaOption.vue'
import AppPanel from '~/components/menu/Panel.vue'
import AppPanelSection from '~/components/menu/PanelSection.vue'

export default {
  components: {
    AppAgendaOption,
    AppPanel,
    AppPanelSection
  },
  data () {
    return {
      agendas: AGENDAS
    }
  },
  computed: {
    generalAgendas () {
      return this.agendas.reduce((generalAgendas, agenda) => {
        if (!agenda.isAdvanced) {
          generalAgendas.push(agenda)
        }
        return generalAgendas
      }, [])
    },
    advancedAgendas () {
      return this.agendas.reduce((advancedAgendas, agenda) => {
        if (agenda.isAdvanced) {
          advancedAgendas.push(agenda)
        }
        return advancedAgendas
      }, [])
    }
  },
  methods: {
    ...mapActions([
      'setAgenda'
    ]),
    ...mapActions('menu', [
      'closePanel'
    ]),
    onAgendaSelect (id) {
      this.setAgenda(id)
      if (this.$tracker) {
        this.$tracker('event', {
          action: 'view',
          label: id
        })
      }
      this.closePanel()
    }
  }
}
</script>
