<template>
  <app-menu-agenda :title="title">
    <app-menu-agenda-actions options-panel="nationaloptions">
      <app-menu-agenda-action-item
        label="Product"
        panel="nationalproduct"
      />
      <app-menu-agenda-action-item
        :icon="alertsIcon"
        :label="alertsLabel"
        panel="alertsextent"
      />
      <app-menu-agenda-action-item
        @click.native="toggleHazards"
      >
        <span
          :class="[
            'fa',
            shortFusedOnly ? 'fa-toggle-off' : 'fa-toggle-on',
            'short-fused-toggle'
          ]"
        />
        All Hazards
      </app-menu-agenda-action-item>
    </app-menu-agenda-actions>
  </app-menu-agenda>
</template>

<script>
import { mapGetters, mapMutations } from 'vuex'
import { createWatcherMixin } from '~/components/mixins'

import AppMenuAgenda from '../Agenda.vue'
import AppMenuAgendaActions from '../AgendaActions.vue'
import AppMenuAgendaActionItem from '../AgendaActionItem.vue'

export default {
  components: {
    AppMenuAgenda,
    AppMenuAgendaActions,
    AppMenuAgendaActionItem
  },
  mixins: [createWatcherMixin('alertsForExtent')],
  computed: {
    ...mapGetters([
      'nationalMap',
      'nationalMapData'
    ]),
    ...mapGetters('alerts', [
      'alertsForExtent',
      'alertsForExtentLoading',
      'shortFusedOnly'
    ]),
    alertsIcon () {
      if (this.alertsForExtentLoading) {
        return 'fa fa-circle-o-notch fa-spin'
      }
      if (this.alertsForExtent.length) {
        return 'fa fa-check-circle'
      }
      return 'fa fa-warning'
    },
    alertsLabel () {
      if (this.alertsForExtent) {
        const length = this.alertsForExtent.length
        if (length > 0) {
          return `${length} Alert${length > 1 ? 's' : ''}`
        } else {
          return 'No Alerts'
        }
      } else {
        return '--'
      }
    },
    title () {
      let title = 'National radar'
      if (this.nationalMapData) {
        title = title + ` for ${this.nationalMapData.longText}`
      }
      return title
    }
  },
  methods: {
    ...mapMutations('alerts', [
      'setShortFusedOnly'
    ]),
    toggleHazards () {
      this.setShortFusedOnly(!this.shortFusedOnly)
    }
  }
}
</script>

<style scoped>
.short-fused-toggle {
  font-size: 18px;
}
</style>
