<template>
  <div
    class="alert"
    :style="{ 'border-left-color': color }"
  >
    <div
      v-if="!grouped"
      class="alert-name"
    >
      {{ alert.event }}
    </div>
    <div
      class="alert-actions"
      @mouseover="setHighlightBbox(alert.bbox)"
      @mouseleave="setHighlightBbox(null)"
    >
      <div class="alert-actions-button">
        <a
          href="#"
          @click.stop.prevent="centerOnAlert(alert)"
        >Show on Map</a>
      </div>
      <div class="alert-actions-button">
        <a
          href="#"
          @click.stop.prevent="viewAlertDetails(alert)"
        >Show Details</a>
      </div>
      <div class="alert-actions-info">
        <span v-if="status === 'loading'">...loading</span>
        <span v-else-if="status === 'failed'">failed, try again</span>
        <span v-else>{{ `${alert.zoneCount} zone${alert.zoneCount > 1 ? 's' : '&nbsp;'}` }} {{ alert.office }}</span>
      </div>
    </div>
  </div>
</template>

<script>
import { loadAlert } from '~/loaders'
import { mapActions, mapGetters, mapMutations } from 'vuex'

export default {
  props: {
    alert: {
      type: Object, // expects AlertSummary
      required: true
    },
    color: {
      type: String,
      required: true
    },
    grouped: {
      type: Boolean,
      default: false
    }
  },
  data () {
    return {
      details: null,
      status: ''
    }
  },
  computed: {
    ...mapGetters([
      'agendaSupportsLayer',
      'zoom'
    ]),
    ...mapGetters('persist', {
      alertsBaseUrl: 'alertsBaseUrl',
      apiBaseUrl: 'apiBaseUrl',
      apiKey: 'apiKey',
      zoomDefaults: 'zoom'
    })
  },
  methods: {
    ...mapActions([
      'markLocation'
    ]),
    ...mapActions('persist', [
      'fitTo'
    ]),
    ...mapActions('search', [
      'geolocateSelected'
    ]),
    ...mapActions('alerts', [
      'setAlertForPanel'
    ]),
    ...mapMutations('alerts', [
      'setHighlightBbox'
    ]),
    centerOnAlert (alert) {
      if (alert && alert.bbox) {
        const coords = this.findBboxCenter(alert.bbox)
        this.fitTo({
          bounds: alert.bbox,
          duration: 100
        })
        this.geolocateSelected(coords)
      } else {
        this.$cmi.log.warn('Cannot center on alert: no bbox', alert)
      }

      if (this.$tracker) {
        this.$tracker('event', {
          action: 'alert',
          label: 'center'
        })
      }
    },
    findBboxCenter (bbox) {
      // account for international date line
      const bboxIntl = bbox.map((coord, i) => {
        if (coord > 0 && !(i % 2)) {
          return 360 - coord
        } else {
          return coord
        }
      })
      return [(bboxIntl[0] + bboxIntl[2]) / 2, (bboxIntl[1] + bboxIntl[3]) / 2]
    },
    viewAlertDetails () {
      if (this.details) {
        this.setAlertForPanel(this.details)
      } else {
        this.status = 'loading'
        loadAlert(this.apiBaseUrl, this.apiKey, this.alert.id).then((data) => {
          this.details = {
            details: data,
            options: {
              color: this.color
            },
            summary: this.alert
          }
          this.status = 'success'
          this.setAlertForPanel(this.details)
        }).catch((error) => {
          this.status = 'failed'
          this.$cmi.log.error('Error loading alert details', error)
        })
      }
      if (this.$tracker) {
        this.$tracker('event', {
          action: 'alert',
          label: 'details'
        })
      }
    }
  }
}
</script>

