<template>
  <div class="slider">
    <vue-slider
      v-model="value"
      v-bind="sliderOptions"
    />
  </div>
</template>

<script>
import VueSlider from 'vue-slider-component'
import 'vue-slider-component/theme/default.css'

export default {
  components: {
    VueSlider
  },
  props: {
    store: {
      type: String,
      required: true
    }
  },
  data () {
    return {
      sliderOptions: {
        clickable: true,
        dotSize: 18,
        height: 24,
        lazy: true,
        tooltip: 'none'
      }
    }
  },
  computed: {
    value: {
      get () { return this.$store.getters[`${this.store}`] * 100 },
      set (value) { this.$store.commit(`${this.store}`, parseFloat(value) / 100) }
    }
  }
}
</script>

<style scoped>
.slider {
  padding: 0 10px;
}
</style>
