<template>
  <app-panel>
    <app-panel-option
      v-if="!focus"
      label="Use my location"
      @click="geolocate()"
    >
      <template #icon>
        <span class="fa fa-location-arrow" />
      </template>
    </app-panel-option>
    <app-panel-option
      v-if="!focus"
      :expands="true"
      :default-expand="true"
      label="Search Results"
    >
      <div v-if="!criteria || criteria.length < 3">
        Provide at least three letters to search
      </div>
      <div v-else-if="searchResultsLoading">
        Loading locations...
      </div>
      <div v-else-if="searchResultsLoadingError">
        Could not retrieve location results
      </div>
      <div v-else-if="esriSuggestions.length === 0">
        No location results found
      </div>
      <div v-else>
        <div
          v-for="(suggestion, index) in esriSuggestions"
          :key="`esriSuggestion-${index}`"
          class="search-option search-option-result"
          @click="selectEsriSuggestion(suggestion, 'result')"
        >
          <div
            class="search-option-icon fa"
            @click.stop="addFavoriteFromEsriSuggestion(suggestion)"
          />
          <div class="search-option-label">
            {{ suggestion.text }}
          </div>
        </div>
      </div>
      <app-panel-option-list
        v-if="radarSuggestions && radarSuggestions.length > 0"
        title="Local Radar Stations"
        :indent="false"
      >
        <div
          v-for="(suggestion, index) in radarSuggestions"
          :key="`radarSuggestion-${index}`"
          class="search-option search-option-result"
          @click="selectRadarSuggestion(suggestion, 'result')"
        >
          <div
            class="search-option-icon fa"
            @click.stop="addFavoriteFromRadarSuggestion(suggestion)"
          />
          <div class="search-option-label">
            Station {{ suggestion.id }} in {{ suggestion.name }}
          </div>
        </div>
      </app-panel-option-list>
    </app-panel-option>
    <app-panel-option
      v-if="!focus"
      label="Favorites"
      :expands="true"
      :default-expand="true"
    >
      <template #icon>
        <span class="fa fa-star" />
      </template>
      <div v-if="!favorites.length">
        Click a search result star to add a favorite
      </div>
      <div
        v-for="(location, index) in favorites"
        :key="`favorite-${index}`"
        class="search-option search-option-favorite"
        @click="selectLocation(location, 'favorite')"
      >
        <div
          class="search-option-icon fa"
          @click.stop="removeFavorite(location)"
        />
        <div
          class="search-option-label"
        >
          {{ location.name }}
        </div>
      </div>
    </app-panel-option>
    <app-panel-option
      v-if="!focus"
      label="Recent Searches"
      :expands="true"
      :default-expand="true"
    >
      <template #icon>
        <span class="fa fa-clock-o" />
      </template>
      <div v-if="!recent.length">
        You do not have any recent searches
      </div>
      <div
        v-for="(location, index) in recent"
        :key="`recent-${index}`"
        class="search-option search-option-recent"
        @click="selectLocation(location, 'recent')"
      >
        <div
          class="search-option-icon fa"
          @click.stop="addFavorite(location)"
        />
        <div
          class="search-option-label"
        >
          {{ location.name }}
        </div>
      </div>
    </app-panel-option>
  </app-panel>
</template>

<script>
import debounce from 'debounce-promise'
import { mapActions, mapGetters, mapMutations } from 'vuex'

import AppPanel from '~/components/menu/Panel.vue'
import AppPanelOption from '~/components/menu/PanelOption.vue'
import AppPanelOptionList from '~/components/menu/PanelOptionList.vue'

import { createWatcherMixin } from '~/components/mixins'
import { loadEsriLocation, loadEsriSuggestions } from '~/loaders'
import { Location } from '~/entities'
import { getCurrentPosition } from '~/util'

const DEBOUNCE_DELAY = 400 // ms
const MAX_FAVORITES = 5
const MAX_RECENT = 5
const DEFAULT_SEARCH_ZOOM_LEVEL = 7

const fetchEsriSuggestions = debounce(function ({ text }) {
  return loadEsriSuggestions({ text })
}, DEBOUNCE_DELAY)

export default {
  components: {
    AppPanel,
    AppPanelOption,
    AppPanelOptionList
  },
  mixins: [createWatcherMixin('radarStations')],
  data () {
    return {
      selectedEsriLocation: null,
      selectedEsriSuggestion: null
    }
  },
  asyncComputed: {
    selectedEsriLocation: {
      get () {
        if (!this.selectedEsriSuggestion) {
          return null
        }

        return loadEsriLocation({
          magicKey: this.selectedEsriSuggestion.magicKey,
          text: this.selectedEsriSuggestion.text
        })
      },
      default: null
    },
    esriSuggestions: {
      async get () {
        if (this.criteria.length < 3) {
          return []
        }

        return fetchEsriSuggestions({ text: this.criteria })
      },
      default: []
    },
    radarSuggestions: {
      async get () {
        if (this.criteria.length < 3) {
          return []
        }
        const criteria = this.criteria.toLowerCase()
        let stations = []
        const stationSuggestions = this.stations
        Object.keys(stationSuggestions).map(stationId => {
          const station = stationSuggestions[stationId]
          if (station.id.toLowerCase().indexOf(criteria) >= 0 || station.name.toLowerCase().indexOf(criteria) >= 0) {
            stations.push(station)
          }
        })
        return stations
      },
      default: []
    }
  },
  computed: {
    ...mapGetters([
      'agenda',
      'agendaSupportsLayer',
      'location'
    ]),
    ...mapGetters('search', [
      'selected'
    ]),
    ...mapGetters('local', [
      'stations'
    ]),
    ...mapGetters('menu', [
      'focus'
    ]),
    criteria: {
      get () { return this.$store.getters['search/criteria'] },
      set (value) { this.$store.commit('search/criteria', value) }
    },
    favorites: {
      get () { return this.$store.getters['persist/favorites'] },
      set (value) { this.$store.commit('persist/favorites', value) }
    },
    recent: {
      get () { return this.$store.getters['persist/recent'] },
      set (value) { this.$store.commit('persist/recent', value) }
    },
    searchResultsLoadingError () {
      return this.$asyncComputed.esriSuggestions.exception
    },
    searchResultsLoading () {
      return this.$asyncComputed.esriSuggestions.updating
    },
    searching: {
      get () { return this.$store.getters['search/searching'] },
      set (value) { this.$store.commit('search/searching', value) }
    }
  },
  watch: {
    selectedEsriLocation () {
      if (this.selectedEsriLocation) {
        this.selectLocation(new Location({
          coordinates: this.selectedEsriLocation.coordinates,
          name: this.selectedEsriLocation.text,
          type: 'location'
        }),
        'location'
        )
      }
    }
  },
  methods: {
    ...mapActions([
      'markLocation',
      'setAgenda'
    ]),
    ...mapActions('search', [
      'geolocateSelected'
    ]),
    ...mapActions('persist', [
      'panTo'
    ]),
    ...mapActions('menu', [
      'closePanel'
    ]),
    ...mapMutations('search', {
      setSelected: 'selected'
    }),
    ...mapMutations('local', {
      setStation: 'station'
    }),
    /**
     * Adds the suggestion to the list of favorites.
     *
     * If the suggestion is already in the list, it will be moved to the top.
     *
     * @param {EsriSuggestion} suggestion
     */
    addFavorite (location) {
      let favorites = this.favorites
      let index = favorites.findIndex(item => item.name === location.name)
      if (index !== -1) {
        favorites.splice(index, 1)
      }
      favorites.unshift(location)

      this.favorites = favorites.slice(0, MAX_FAVORITES)
    },
    async addFavoriteFromEsriSuggestion (suggestion) {
      let location = await loadEsriLocation({
        magicKey: suggestion.magicKey,
        text: suggestion.text
      })
      if (location) {
        this.addFavorite(new Location({
          coordinates: location.coordinates,
          name: location.text,
          type: 'location'
        }))
      }
    },
    addFavoriteFromRadarSuggestion (suggestion) {
      this.addFavorite(new Location({
        id: suggestion.id,
        coordinates: suggestion.coordinates,
        name: `Station ${suggestion.id} in ${suggestion.name}`,
        type: 'radar'
      }))
    },
    /**
     * Adds the suggestion to the list of recent selections.
     *
     * If the suggestion is already in the list, it will be moved to the top.
     *
     * @param {EsriSuggestion} suggestion
     */
    addRecent (location) {
      let recent = this.recent
      let index = recent.findIndex(item => item.name === location.name)
      if (index !== -1) {
        recent.splice(index, 1)
      }

      recent.unshift(location)
      this.recent = recent.slice(0, MAX_RECENT)
    },
    async geolocate () {
      this.$cmi.log.info('Selecting user location')
      this.criteria = ''

      if (this.$tracker) {
        this.$tracker('event', {
          action: 'search',
          label: 'geolocation'
        })
      }

      const currentPosition = await getCurrentPosition()
      if (currentPosition) {
        this.geolocateSelected(currentPosition)
        this.updateLocation({
          coordinates: currentPosition
        })
      }
    },
    removeFavorite (suggestion) {
      let favorites = this.favorites
      const index = favorites.findIndex(item => item.magicKey === suggestion.magicKey)
      if (index === -1) {
        this.$cmi.log.error(`Didn't find favorite "${suggestion.text}" to remove`)
        return
      }

      favorites.splice(index, 1)
      this.favorites = favorites
    },
    /**
     * Sets the location to a place which triggers the
     * map to change based on the new location type
     *
     * @param {EsriSuggestion} suggestion
     */
    selectEsriSuggestion (suggestion) {
      this.$cmi.log.info(`Selecting search suggestion ${suggestion.text}`)
      this.selectedEsriSuggestion = suggestion
    },
    selectRadarSuggestion (suggestion) {
      this.selectLocation(
        new Location({
          id: suggestion.id,
          coordinates: suggestion.coordinates,
          name: `Station ${suggestion.id} in ${suggestion.name}`,
          type: 'radar'
        }),
        'radar'
      )
    },
    selectLocation (location, from) {
      this.criteria = ''
      this.addRecent(location)
      this.updateLocation(location)
      this.setSelected(location)

      if (this.$tracker) {
        this.$tracker('event', {
          action: 'search',
          label: from
        })
      }
    },
    updateLocation (location) {
      if (location?.type === 'radar' && location.id) {
        this.setStation(location.id)
        this.panTo({ center: location.coordinates, zoom: DEFAULT_SEARCH_ZOOM_LEVEL })
        this.setAgenda('local')
      } else {
        this.markLocation(location.coordinates)
        this.panTo({ center: location.coordinates, zoom: DEFAULT_SEARCH_ZOOM_LEVEL })
        if (!this.agendaSupportsLayer('marker')) {
          this.setAgenda('weather')
        }
      }
      this.closePanel()
    }
  }
}
</script>

