<template>
  <app-panel-option
    id="localstations"
    label="Local Stations"
    :expands="true"
  >
    <template #fixed>
      <app-panel-option-slider
        store="local/stationOpacity"
      />
    </template>
    <app-panel-option-list
      title="Type"
    >
      <div key="null">
        <input
          v-model="filter"
          name="showLocal"
          type="radio"
          :value="null"
        > All Types
      </div>
      <div
        v-for="radarType in radarTypes"
        :key="radarType.id"
      >
        <input
          v-model="filter"
          name="showLocal"
          type="radio"
          :value="radarType.id"
        >
        {{ radarType.id }}
      </div>
    </app-panel-option-list>
  </app-panel-option>
</template>

<script>
import AppPanelOption from '~/components/menu/PanelOption.vue'
import AppPanelOptionList from '~/components/menu/PanelOptionList.vue'
import AppPanelOptionSlider from '~/components/menu/PanelOptionSlider.vue'

export default {
  components: {
    AppPanelOption,
    AppPanelOptionList,
    AppPanelOptionSlider
  },
  data () {
    return {
      radarTypes: [
        {
          id: 'WSR-88D'
        },
        {
          id: 'TDWR'
        }
      ]
    }
  },
  computed: {
    filter: {
      get () { return this.$store.getters['local/filter'] },
      set (value) { this.$store.commit('local/filter', value) }
    },
    showRadarStationsIcons: {
      get () { return this.$store.getters['local/showRadarStationsIcons'] },
      set (value) {
        this.$store.commit('local/setShowRadarStationsIcons', value)

        if (this.$tracker) {
          this.$tracker('event', {
            action: 'local-option-station-icons',
            label: value ? 'on' : 'off'
          })
        }
      }
    }
  },
  watch: {
    filter () {
      if (this.$tracker) {
        this.$tracker('event', {
          action: 'local-option-station-type',
          label: this.filter ? this.filter.toLowerCase() : 'All'
        })
      }
    }
  }
}
</script>
