<script>
import { Group as LayerGroup } from 'ol/layer'
import { mapRender } from '~/cmi/mixins/map'

export default {
  mixins: [mapRender],
  inject: {
    getOLContainer: 'getOLContainer'
  },
  provide () {
    return {
      getOLContainer: () => this.olLayerGroup.getLayers()
    }
  },
  props: {
    id: {
      type: String,
      default: '<anonymous group>'
    },
    zIndex: {
      type: Number,
      default: 0
    }
  },
  data () {
    return {
      olLayerGroup: null,
      slots: true
    }
  },
  computed: {
    olContainer () {
      return this.getOLContainer()
    }
  },
  created () {
    this.olLayerGroup = new LayerGroup({
      properties: {
        who: this.id
      },
      zIndex: this.zIndex
    })
    this.olContainer.push(this.olLayerGroup)
    this.$emit('created', this.olLayerGroup)
  },
  beforeDestroy () {
    this.olContainer.remove(this.olLayerGroup)
  }
}
</script>

<style scoped>
.cmi-map-container {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
}

.cmi-map {
  height: 100%;
  width: 100%;
  overflow: hidden;
  display: block;
}
</style>
