<template>
  <app-panel-option
    id="nationalradar"
    label="National Radar"
    :expands="true"
  >
    <template #fixed>
      <app-panel-option-slider
        store="nationalMapOpacity"
      />
    </template>
    <app-panel-option-list
      title="Product"
    >
      <span v-if="agendaBarOverride.product && agendaBarOverride.product === true">
        The radar product can be selected above.
      </span>
      <template v-else>
        <div
          v-for="map in maps"
          :key="map.name"
        >
          <input
            v-model="nationalMap"
            name="nationalMap"
            type="radio"
            :value="map.name"
          >
          {{ map.longText }}
        </div>
      </template>
    </app-panel-option-list>
  </app-panel-option>
</template>

<script>
import AppPanelOption from '~/components/menu/PanelOption.vue'
import AppPanelOptionList from '~/components/menu/PanelOptionList.vue'
import AppPanelOptionSlider from '~/components/menu/PanelOptionSlider.vue'

import { MAPS } from '~/config'

export default {
  components: {
    AppPanelOption,
    AppPanelOptionList,
    AppPanelOptionSlider
  },
  props: {
    agendaBarOverride: {
      type: Object,
      default: () => ({})
    }
  },
  data () {
    return {
      maps: MAPS.national
    }
  },
  computed: {
    nationalMap: {
      get () { return this.$store.getters.nationalMap },
      set (value) { this.$store.commit('nationalMap', value) }
    }
  }
}
</script>
