<template>
  <cmi-layer-group id="basemaps">
    <cmi-layer-mapbox
      v-for="(map, index) in vectorMaps"
      :id="`${map.name}-${index}`"
      :key="`${map.name}-${index}`"
      :enable-reload="false"
      :min-zoom="minZoom"
      :max-zoom="maxZoom"
      :style-url="map.url"
      :z-index="zIndex"
      :access-token="baseMapsToken"
      :use-token-with-url="true"
    />
  </cmi-layer-group>
</template>

<script>
import { mapGetters } from 'vuex'

import { ARCGIS, MAPS } from '~/config'

export default {
  props: {
    maxZoom: {
      type: Number,
      default: 10
    },
    minZoom: {
      type: Number,
      default: 4
    },
    zIndex: {
      type: Number,
      required: true
    }
  },
  data () {
    return {
      baseMaps: MAPS.base,
      tileType: 'vector'
    }
  },
  computed: {
    ...mapGetters([
      'baseMap',
      'baseMapLabels'
    ]),
    ...mapGetters('persist', [
      'esriKey'
    ]),
    baseMapsToken () {
      return this.esriKey || ARCGIS.token.vector
    },
    vectorMaps () {
      // openlayers will request styles even if layer visibilty is false, so only return if active layer
      let basemaps = []
      this.getMapsByType('vector').reduce((activeBasemaps, basemap) => {
        return basemap.name === this.baseMap ? activeBasemaps.concat(basemap) : activeBasemaps
      }, []).map((basemap) => {
        basemap.url.vector.forEach(url => {
          basemaps.push({
            name: basemap.name,
            url: url
          })
        })
      })
      // assume the any additional layers are labels
      if (!this.baseMapLabels) {
        return [basemaps[0]]
      }
      return basemaps
    },
    rasterMaps () {
      return this.getMapsByType('raster')
    }
  },
  methods: {
    getMapsByType (type) {
      // empty array effectively disables the render of that tile type due to loop
      return this.tileType === type ? this.baseMaps : []
    }
  }
}
</script>
