import { LoadingError, ResourceLoader } from '~/cmi/loaders'
import * as log from '~/cmi/log'
import { ForecastHour } from '~/entities'

export async function loadForecastHourly (url, key) {
  const options = {
    headers: {
      'Accept': 'application/geo+json'
      // FIXME: include this again once hourly forecast bug is fixed in dev
      // 'Feature-Flags': 'forecast_temperature_qv, forecast_wind_speed_qv'
    },
    responseType: 'json'
  }
  if (key !== null) {
    options.headers['API-Key'] = key
  }

  log.info(`Requesting hourly forecast data from ${url}`)

  const loader = new ResourceLoader()
  return loader.load(url, options, response => {
    try {
      const forecast = response.data.properties.periods.map(data => {
        return new ForecastHour({
          number: data.number,
          daytime: data.isDaytime,
          // FIXME: use new endpoint schema once hourly forecast bug is fixed in dev
          // temperature: convert(data.temperature.value).from('C').to('F'),
          temperature: data.temperature,
          probabilityOfPrecipitation: data.probabilityOfPrecipitation?.value,
          relativeHumidity: data.relativeHumidity.value,
          short: data.shortForecast,
          details: data.detailedForecast,
          startTime: data.startTime,
          endTime: data.endTime,
          icon: data.icon
        })
      })
      log.debug(`Retrieved hourly forecasts from ${url}`, forecast.reduce((map, period) => {
        map[period.startTime] = period
        return map
      }, {}))

      return forecast
    } catch (err) {
      throw new LoadingError(`Error reading hourly forecasts from ${url}`, err)
    }
  })
}
