import * as log from 'loglevel'
import Vue from 'vue'

/**
 * A map of log level names to their respective integers.
 *
 * @type {Object}
 */
export const levels = log.levels

/**
 * Manager for internal loggers and log levels.
 */
class LoggerSettings {
  constructor (prefix) {
    this._loggers = {}
    this._prefix = prefix
  }

  /**
   * Returns a logger by name, creating it if necessary.
   *
   * @param {String} name - the name of the logger to retrieve
   *
   * @return {loglevel.Logger}
   */
  getLogger (name) {
    if (typeof name !== 'string' || name.length === 0) {
      throw new Error('Logger name must be a non-empty string')
    }
    if (!this._loggers.hasOwnProperty(name)) {
      this._createLoggerEntry(name)
    }
    return this._loggers[name]['logger']
  }

  /**
   * Returns the level of the named logger, creating it if necessary.
   *
   * @param {String} name - the name of the logger to retrieve a level from
   *
   * @return {Number}
   */
  getLevel (name) {
    if (typeof name !== 'string' || name.length === 0) {
      throw new Error('Logger name must be a non-empty string')
    }
    if (!this._loggers.hasOwnProperty(name)) {
      this._createLoggerEntry(name)
    }
    return this._loggers[name]['level']
  }

  /**
   * Sets a logger level, creating the logger if necessary.
   *
   * @param {String} name - the logger to set a level for
   * @param {Number|String} level - the level to set the logger to
   */
  setLevel (name, level) {
    let logger = this.getLogger(name)
    logger.setLevel(level, true)
    this._loggers[name]['level'] = logger.getLevel()
  }

  _createLoggerEntry (name) {
    let logger = log.getLogger(`${this._prefix}-${name}`)
    this._loggers[name] = Vue.observable({
      logger: logger,
      level: logger.getLevel()
    })
  }
}

var loggers = null
var enabledExtras = null

/**
 * Initializes the loggers.
 *
 * This is an internal method and should not be called outside the CMI.
 *
 * @private
 */
export function initialize (prefix) {
  loggers = new LoggerSettings(prefix)
  enabledExtras = Vue.observable({
    event: loggers.getLevel('event') < log.levels.SILENT
  })

  if (process.env.NODE_ENV === 'production') {
    loggers.getLogger('main').setDefaultLevel(log.levels.INFO)
  } else {
    loggers.getLogger('main').setDefaultLevel(log.levels.DEBUG)
  }
  loggers.getLogger('event').setDefaultLevel(log.levels.SILENT)
}

/**
 * Returns the level of the main logger.
 *
 * @return {Number}
 * @see levels
 */
export function getLevel () {
  return loggers.getLevel('main')
}

/**
 * Returns whether the event logger is enabled.
 *
 * @return {Boolean}
 */
export function isEventLoggingEnabled () {
  return enabledExtras['event']
}

/**
 * Sets the main logging level.
 *
 * The available levels are "debug", "info", "warn", "error", and "silent" (to
 * disable).  The values in {@link levels} may also be provided.
 *
 * @param {Number|String} level - the minimum level for logging
 */
export function setLevel (level) {
  loggers.setLevel('main', level)
}

/**
 * Enables or disables the event logger.
 *
 * @param {Boolean} enabled - true to enable the logger, false to disable it
 */
export function setEventLoggingEnabled (enabled) {
  loggers.setLevel('event', enabled ? log.levels.DEBUG : log.levels.SILENT)
  enabledExtras['event'] = loggers.getLevel('event') < log.levels.SILENT
}

/**
 * Logs an event message.
 *
 * @param {String} message - the message to log
 */
export function event (...args) {
  loggers.getLogger('event').info(...args)
}

/**
 * Logs a standard message at DEBUG level.
 *
 * @param {String} message - the message to log
 */
export function debug (...args) {
  loggers.getLogger('main').debug(...args)
}

/**
 * Logs a standard message at ERROR level.
 *
 * @param {String} message - the message to log
 */
export function error (...args) {
  loggers.getLogger('main').error(...args)
}

/**
 * Logs a standard message at INFO level.
 *
 * @param {String} message - the message to log
 */
export function info (...args) {
  loggers.getLogger('main').info(...args)
}

/**
 * Logs a standard message at WARN level.
 *
 * @param {String} message - the message to log
 */
export function warn (...args) {
  loggers.getLogger('main').warn(...args)
}
