import { v4 as uuid } from 'uuid'

export default {
  inject: {
    getOLMap: 'getOLMap',
    getOLContainer: 'getOLContainer',
    getOLView: 'getOLView',
    $reload: 'reload'
  },
  props: {
    attributions: {
      type: Array,
      validator: value => value.every(item => {
        return typeof item === 'string' ||
          (typeof item === 'object' && item.hasOwnPropertyDescriptor('text') && item.hasOwnPropertyDescriptor('url'))
      }),
      default: () => []
    },
    enableReload: {
      type: Boolean,
      default: true
    },
    id: {
      type: String,
      default: null
    },
    opacity: {
      type: Number,
      validator: value => value >= 0 && value <= 1,
      default: 1
    },
    visible: {
      type: Boolean,
      default: true
    },
    zIndex: {
      type: Number,
      default: 0
    }
  },
  data () {
    return {
      uuid: uuid()
    }
  },
  computed: {
    olMap () {
      return this.getOLMap()
    },
    olContainer () {
      return this.getOLContainer()
    },
    olView () {
      return this.getOLView()
    },
    /**
     * The last time layer data was reloaded.
     *
     * @type {luxon.DateTime}
     */
    lastReloadTime () {
      return this.$reload.getLastReloadTime()
    },
    _attributions () {
      this.attributions.map(attribution => {
        if (typeof attribution === 'string') {
          return attribution
        }
        if (attribution.url) {
          return `<a href="${attribution.url}" target="_blank">${attribution.text}</a>`
        }
        return attribution.text
      })
    },
    _id () {
      return this.id || `layer-${this.uuid}`
    }
  },
  watch: {
    lastReloadTime () {
      if (this.enableReload) {
        this.reload()
      }
    }
  },
  methods: {
    reload () {
      this?.olLayer.getSource().refresh()
    }
  }
}
