export class Location {
  constructor ({ id, coordinates, name, type }) {
    this.__id = id
    this.__coordinates = coordinates
    this.__name = name
    this.__type = type
  }

  get id () {
    return this.__id
  }

  get coordinates () {
    return this.__coordinates
  }

  get name () {
    return this.__name
  }

  get type () {
    return this.__type
  }
}
