import { ResourceLoader } from './base'

export class EsriWFS {
  constructor (url) {
    this.__url = url
  }

  async getFeatures (layer, params) {
    const options = {
      headers: { 'Accept': 'application/geo+json' },
      responseType: 'json',
      params: Object.assign({
        f: 'json',
        geometryType: 'esriGeometryEnvelope',
        inSR: {
          wkid: 4326
        },
        outSR: {
          wkid: 4326
        },
        returnGeometry: 'true',
        spatialRel: 'esriSpatialRelIntersects'
      }, params)
    }

    const layerUrl = `${this.__url}/${layer}/query/`

    const loader = new ResourceLoader()
    return loader.load(layerUrl, options, response => {
      return response.data
    })
  }
}
