<template>
  <cmi-map
    animation-frame-delay-multiplier="PT0.5S"
    :animation-frame-delay-max="8"
    :animation-frame-max="10"
    :animation-running.sync="animating"
    :initial-values="initialMapValues"
    :legend="legend"
    :min-zoom="zoomDefaults.min"
    :max-zoom="zoomDefaults.max"
    reload-delay="PT10M"
    :disabled="disableControls"
    :timezone="timezone"
    @created="onMapCreate"
    @frames="setAnimationFrames"
    @click="onClick"
    @moveend="onMoveEnd"
    @movestart="onMoveStart"
    @reload="setLastReloadTime"
  >
    <template #layers>
      <app-base-maps
        :min-zoom="zoomDefaults.min"
        :max-zoom="zoomDefaults.max"
        :z-index="-1000"
      />
      <app-local-radar
        v-if="showLocalRadar"
        ref="localRadar"
        :min-zoom="zoomDefaults.min"
        :max-zoom="zoomDefaults.max"
        :z-index="5"
        :z-index-stations="10"
        :opacity="localMapOpacity"
      />
      <app-national-radar
        v-if="showNationalRadar"
        :max-zoom="zoomDefaults.max"
        :min-zoom="zoomDefaults.min"
        :opacity="nationalMapOpacity"
        :z-index="5"
      />
      <app-alerts
        v-if="showAlerts"
        :max-zoom="zoomDefaults.max"
        :min-zoom="zoomDefaults.min"
        :opacity="alertOpacity"
        :z-index="10"
      />
      <app-activearea
        v-if="showActivearea"
        :max-zoom="zoomDefaults.max"
        :min-zoom="zoomDefaults.min"
        :z-index="50"
      />
      <app-boundary-overlays
        :max-zoom="zoomDefaults.max"
        :min-zoom="zoomDefaults.min"
        :z-index="50"
      />
      <cmi-map-marker
        v-if="showMarker"
        :coordinates="location"
        :z-index="100"
      />
    </template>
  </cmi-map>
</template>

<script>
import { mapActions, mapGetters, mapMutations } from 'vuex'

import AppActivearea from '~/components/map/ActiveArea.vue'
import AppAlerts from '~/components/map/Alerts.vue'
import AppBaseMaps from '~/components/map/BaseMaps.vue'
import AppBoundaryOverlays from '~/components/map/BoundaryOverlays.vue'
import AppLocalRadar from '~/components/map/LocalRadar.vue'
import AppNationalRadar from '~/components/map/NationalRadar.vue'

export default {
  components: {
    AppActivearea,
    AppAlerts,
    AppBaseMaps,
    AppBoundaryOverlays,
    AppLocalRadar,
    AppNationalRadar
  },
  computed: {
    ...mapGetters([
      'agenda',
      'lastReloadTime',
      'location',
      'nationalMap',
      'nationalMapOpacity',
      'showActivearea',
      'showAlerts',
      'showLocalRadar',
      'showMarker',
      'showNationalRadar'
    ]),
    ...mapGetters('local', {
      localMap: 'layerName',
      localMapTransparent: 'transparent',
      localMapOpacity: 'opacity',
      localStation: 'station'
    }),
    ...mapGetters('alerts', {
      alertOpacity: 'opacity'
    }),
    ...mapGetters('persist', {
      suppressBookmark: 'suppressBookmark',
      zoomDefaults: 'zoom',
      disableControls: 'disableControls',
      timezone: 'timezone'
    }),
    animating: {
      get () { return this.$store.getters.animating },
      set (value) { this.$store.commit('setAnimating', value) }
    },
    animationPrimaryFrames: {
      get () { return this.$store.getters['persist/animationPrimaryFrames'] },
      set (value) { this.$store.commit('persist/animationPrimaryFrames', value) }
    },
    center: {
      get () { return this.$store.getters.center },
      set (value) { this.$store.commit('center', value) }
    },
    extent: {
      get () { return this.$store.getters.extent },
      set (value) { this.$store.commit('extent', value) }
    },
    cmi: {
      get () { return this.$store.getters['persist/cmi'] },
      set (value) { this.$store.commit('persist/cmi', value) }
    },
    initialMapValues () {
      return {
        view: {
          zoom: this.$store.getters.zoom,
          center: this.$store.getters.center,
          extent: this.$store.getters.extent
        }
      }
    },
    legend () {
      if (this.showLocalRadar) {
        return (this.localStation && this.localMap) ? this.localMap : 'stat'
      }
      return this.nationalMap
    },
    zoom: {
      get () { return this.$store.getters.zoom },
      set (value) {
        if (value !== this.$store.getters.zoom) {
          this.$store.commit('zoom', value)
        }
      }
    }
  },
  methods: {
    ...mapActions([
      'markLocation',
      'setAgenda'
    ]),
    ...mapActions('persist', [
      'removeBookmarkSuppress',
      'panTo'
    ]),
    ...mapMutations([
      'setLastReloadTime',
      'setAnimationFrames'
    ]),
    ...mapMutations('local', [
      'closestCoordinates'
    ]),
    ...mapActions('search', [
      'geolocateSelected'
    ]),
    async onClick (event) {
      // let app determine what to do on click
      this.$emit('click')

      // only zoom on click if user has not otherwise set the zoom level or is back to minimum zoom level
      const zoomTo = this.zoom === this.zoomDefaults.default ? this.zoomDefaults.focus : this.zoom

      if (this.showLocalRadar) {
        this.closestCoordinates(event.coordinates)
        // Rest is handled by LocalRadar.vue
      } else {
        this.markLocation(event.coordinates)
        this.panTo({ center: event.coordinates, zoom: zoomTo })
        if (this.agenda === null) {
          this.setAgenda('weather')
        }
        this.geolocateSelected(event.coordinates)
      }
    },
    onMapCreate (event, cmi) {
      this.cmi = cmi
    },
    onMoveEnd (event) {
      this.center = event.center
      this.zoom = event.zoom
      this.extent = event.extent
      if (this.suppressBookmark) {
        this.$nextTick(() => {
          this.removeBookmarkSuppress('map')
        })
      }
    },
    onMoveStart (event) {
      // this.extent = null
    }
  }
}
</script>
