/**
 * index.js
 * The initial loader for all Vuex store data and methods
 *
 */
import Vue from 'vue'
import Vuex from 'vuex'
import VuexPersistence from 'vuex-persist'

import alertsStore from './alerts'
import localRadarStore from './local'
import menuStore from './menu'
import persisstStore from './persist'
import searchStore from './search'
import watchersStore from './watchers'
import * as log from '~/cmi/log'
import * as logLevel from 'loglevel'
import { validators } from '~/cmi'
import { AGENDAS, MAPS, DOMAINS } from '~/config'
import localforage from 'localforage'

Vue.use(Vuex)

const DEFAULT_BASE_MAP = 'standard'
const DEFAULT_NATIONAL_RADAR_MAP = MAPS.national[0].name
// This will include default agendas plus any custom agendas
let allAgendas = AGENDAS.concat()

function createDefaultState () {
  return {
    animating: false,
    bookmark: null,
    extent: null,
    lastReloadTime: null,
    forecastPoint: {
      error: null,
      loading: false,
      value: null
    },
    animationFrames: undefined,
    settings: {
      // Map orientation
      center: [-95, 37],
      zoom: 4,
      // Maps and stations
      baseMap: DEFAULT_BASE_MAP,
      baseMapLabels: true,
      nationalMap: DEFAULT_NATIONAL_RADAR_MAP,
      nationalMapOpacity: 0.6,
      // Boundary overlays
      artccMap: false,
      countyMap: false,
      cwaMap: false,
      rfcMap: false,
      stateMap: false,
      // Other map settings
      agenda: null,
      location: null
    }
  }
}

/**
 * Creates a store for cmi-radar.
 *
 * NOTE: as a library, cmi-radar should NOT use Vuex!  This library should NOT
 * be released to the public until Vuex is removed!
 *
 * @todo Replace the store with an alternative state management system, possibly
 *       provide/inject.
 */
export function createStore (options) {
  const persistence = new VuexPersistence({
    key: 'cmi-radar',
    storage: localforage,
    reducer: state => ({
      persist: {
        favorites: state.persist.favorites,
        recent: state.persist.recent
      }
    }),
    map: {
      persist: {
        favorites: `persist/favorites`,
        recent: `persist/recent`
      }
    },
    shallow: mutation => ['persist'].includes(mutation),
    filter: mutation => ['persist/favorites', 'persist/recent'].includes(mutation.type),
    asyncStorage: true,
    restoreSavedOnly: true
  })

  const store = new Vuex.Store({
    modules: {
      alerts: alertsStore,
      local: localRadarStore,
      menu: menuStore,
      persist: persisstStore,
      search: searchStore,
      watchers: watchersStore
    },
    state: createDefaultState(),
    mutations: {
      setAnimating (state, input) {
        state.animating = Boolean(input)
      },
      setAnimationFrames (state, input) {
        state.animationFrames = Array.isArray(input) ? input : undefined
      },
      extent (state, input) {
        state.extent = input
      },
      setLastReloadTime (state, input) {
        if (typeof input !== 'string' && input !== null) {
          log.error('Last reload time should be in ISO8601 string form; received ', input)
          return
        }
        state.lastReloadTime = input
      },
      // Settings
      agenda (state, input) {
        if (input !== null && !allAgendas.find(map => map.id === input)) {
          log.error(`Invalid agenda: ${input}`)
          return
        }
        state.settings.agenda = input
      },
      artccMap (state, input) {
        state.settings.artccMap = Boolean(input)
      },
      baseMap (state, input) {
        if (!MAPS.base.find(map => map.name === input)) {
          log.error(`Invalid base map: ${input}`)
          return
        }
        state.settings.baseMap = input
      },
      baseMapLabels (state, input) {
        state.settings.baseMapLabels = Boolean(input)
      },
      center (state, input) {
        if (!validators.lonLat(input)) {
          log.error(`Invalid center coordinates: ${input}`)
          return
        }
        state.settings.center = input
      },
      countyMap (state, input) {
        state.settings.countyMap = Boolean(input)
      },
      cwaMap (state, input) {
        state.settings.cwaMap = Boolean(input)
      },
      location (state, input) {
        if (!validators.lonLat(input) && input !== null) {
          log.error(`Invalid location coordinates: ${input}`)
          return
        }
        state.settings.location = input
      },
      nationalMap (state, input) {
        if (input !== null && !MAPS.national.find(map => map.name === input)) {
          log.error(`Invalid national map: ${input}, autoselecting default: ${DEFAULT_NATIONAL_RADAR_MAP}`)
          state.settings.nationalMap = DEFAULT_NATIONAL_RADAR_MAP
        } else {
          state.settings.nationalMap = input
        }
      },
      nationalMapOpacity (state, input) {
        state.settings.nationalMapOpacity = parseFloat(input)
      },
      reset (state) {
        Object.assign(state, createDefaultState())
      },
      rfcMap (state, input) {
        state.settings.rfcMap = Boolean(input)
      },
      stateMap (state, input) {
        state.settings.stateMap = Boolean(input)
      },
      zoom (state, input) {
        if (isNaN(input)) {
          log.error(`Invalid zoom level: ${input}`)
          return
        }
        state.settings.zoom = Number(input)
      },
      setForecastPoint (state, input) {
        state.forecastPoint.value = input
      },
      setForecastPointError (state, input) {
        if (input !== null && !(input instanceof Error)) {
          log.error('Error must be null or an instance of Error; received ', input)
          return
        }
        state.forecastPoint.error = input
      },
      setForecastPointLoading (state, input) {
        state.forecastPoint.loading = Boolean(input)
      },

      // persistence
      RESTORE_MUTATION: persistence.RESTORE_MUTATION
    },
    actions: {
      markLocation: ({ commit }, input) => {
        commit('location', input)
      },
      reset: ({ commit, getters, dispatch }) => {
        commit('alerts/reset')
        commit('local/reset')
        commit('search/reset')
        commit('menu/reset')
        commit('reset')
        dispatch('persist/panTo', {
          center: getters.center,
          zoom: getters.zoom
        })
      },
      /**
       * Commits the items required by the current agenda selection to the store
       *
       * @param commit
       * @param input String
       */
      setAgenda: ({ commit, getters }, input) => {
        if (getters.agenda !== input) {
          commit('setAnimating', false)
          switch (input) {
            case 'local':
              commit('location', null)
              commit('alerts/setShortFusedOnly', true)
              commit('search/selected', null)
              break
            case 'national':
              commit('local/filter', null)
              commit('local/station', null)
              commit('alerts/setShortFusedOnly', true)
              if (getters.agenda === 'local') {
                commit('search/selected', null)
              }
              break
            case 'weather':
              commit('local/filter', null)
              commit('local/station', null)
              commit('alerts/setShortFusedOnly', false)
              if (getters.agenda === 'local') {
                commit('search/selected', null)
              }
              break
            default:
              throw new Error(`Unknown agenda: ${input}`)
          }
          commit('agenda', input)
        }
      }
    },
    getters: {
      agenda: state => state.settings.agenda, // get the current agenda
      agendaSelected: (state, getters) => {
        return allAgendas.find(item => item.id === getters.agenda)
      },
      agendaSupportsLayer: (state, getters) => layer => {
        return Boolean(getters.agenda && allAgendas.find(item => item.id === getters.agenda).layers.includes(layer))
      },
      animating: state => state.animating,
      animationFrames: state => state.animationFrames,
      animationFramesRaw: (state) => {
        if (Array.isArray(state.animationFrames)) {
          return [...state.animationFrames]
        } else {
          return state.animationFrames
        }
      },
      artccMapEnabled: state => state.settings.artccMap, // get the show/hide for artcc overlay
      baseMap: state => state.settings.baseMap, // get the name of the current basemap
      baseMapLabels: state => state.settings.baseMapLabels, // get the flag to display basemap labels
      bookmark: state => state.bookmark,
      center: state => state.settings.center, // get the position the map is centered on
      countyMapEnabled: state => state.settings.countyMap, // get the show/hide for counties overlay
      cwaMapEnabled: state => state.settings.cwaMap, // get the show/hide for cwa overlay
      extent: state => state.extent,
      lastReloadTime: state => state.lastReloadTime,
      location: state => state.settings.location, // get the selected location coordinates
      nationalMap: state => state.settings.nationalMap, // get the name of the current national map, if any
      nationalMapData: (state, getters) => {
        const layer = MAPS.national.find(layer => layer.name === getters.nationalMap)
        if (layer) {
          return layer
        }
        return null
      },
      nationalMapOpacity: state => state.settings.nationalMapOpacity, // if user selects to override product transparency for agenda
      rfcMapEnabled: state => state.settings.rfcMap, // get the show/hide for rfc overlay
      stateMapEnabled: state => state.settings.stateMap, // get the show/hide for states overlay
      showActivearea: (state, getters) => getters.agendaSupportsLayer('activearea'),
      showAlerts: (state, getters) => getters.agendaSupportsLayer('alerts'),
      showLocalRadar: (state, getters) => getters.agendaSupportsLayer('local'),
      showMarker: (state, getters) => getters.agendaSupportsLayer('marker') && !getters.showLocalRadar,
      showNationalRadar: (state, getters) =>
        (getters.agenda === null || getters.agendaSupportsLayer('national')) || (getters.showLocalRadar && !getters['local/station']),
      zoom: state => state.settings.zoom, // get the current zoom level,
      forecastPoint: state => state.forecastPoint.value,
      forecastPointError: state => state.forecastPoint.error,
      forecastPointLoading: state => state.forecastPoint.loading,
      forecastPointException: state => state.forecastPoint.exception,
      encodedBookmark: (state, getters) => exportBookmark(getters, state),
      extentForAlertData: (state, getters, rootState, rootGetters) => {
        if (rootGetters['alerts/limitToExtent']) {
          return state.extent
        }
        return null
      }
    },
    plugins: [
      persistence.plugin,
      store => store.subscribe(({ payload, type }) => {
        logLevel.getLogger('vuex').info(`Vuex mutation "${type}": `, payload)
      }),
      store => store.subscribeAction(({ payload, type }) => {
        logLevel.getLogger('vuex').info(`Vuex action "${type}": `, payload)
      })
    ]
  })

  function commitByPath (path, value, normalizedValues) {
    if (typeof value !== 'undefined') {
      // for older bookmarks that used a different value for the option but didn't warrant a new bookmark version
      store.commit(path, normalizedValues && normalizedValues.hasOwnProperty(value) ? normalizedValues[value] : value)
    }
  }

  function resolvePath (object, path, defaultValue) {
    return path.split('.').reduce((o, p) => o ? o[p] : defaultValue, object)
  }

  function limitCoordinatePrecision (coordinates) {
    return coordinates ? coordinates.map(coord => parseFloat(coord.toFixed(3))) : null
  }

  // basic options
  commitByPath('persist/alertsBaseUrl', resolvePath(options, 'urls.alerts'))
  commitByPath('persist/apiBaseUrl', resolvePath(options, 'urls.api'))
  commitByPath('persist/forecastBaseUrl', resolvePath(options, 'urls.forecast'))
  commitByPath('persist/gisBaseUrl', resolvePath(options, 'urls.gis'))
  commitByPath('persist/apiKey', resolvePath(options, 'apiKey'))
  commitByPath('persist/esriKey', resolvePath(options, 'esriKey'))
  commitByPath('persist/timezone', resolvePath(options, 'timezone'))

  // quickset options
  if (options.settings.quickset) {
    quickset(options.settings.quickset)
  }

  // bookmark options
  if (options.settings.bookmark) {
    const parts = options.settings.bookmark.split('_', 2)
    if (parts.length !== 0) {
      switch (parts[0]) {
        case 'v1':
          importBookmark(parts[1])
          break
        default:
          console.error(`Unknown bookmark settings version: ${parts[0]}`)
      }
    }
  }

  // supress bookmark updates until map suppress key is processed (search for removeBookmarkSuppress)
  store.dispatch('persist/addBookmarkSuppress', 'map')

  async function quickset (settings) {
    if (settings.hasOwnProperty('location')) {
      commitByPath('agenda', 'weather')
      if (!validators.lonLat(settings.location)) {
        log.error(`Invalid location quickset coordinates: ${settings.location}`)
        return
      }
      let center = settings.location.slice()
      if (settings.focus) {
        store.commit('menu/focus', settings.focus)
        store.dispatch('menu/togglePanel', 'forecastpoint')
        // pan the map down if on small display so not hidden by focus pannel
        if (window.innerWidth < 400) {
          center[1] = center[1] + 1
        }
      }
      commitByPath('zoom', 7)
      commitByPath('center', center)
      commitByPath('location', settings.location)
      // uses esri lookup to convert coordinates to location name
      store.dispatch('search/geolocateSelected', settings.location)
    } else if (settings.hasOwnProperty('station')) {
      store.dispatch('persist/addBookmarkSuppress', 'local')
      commitByPath('agenda', 'local')
      commitByPath('local/station', settings.station.toUpperCase())
      commitByPath('alerts/setShortFusedOnly', true)
    } else if (settings.hasOwnProperty('region')) {
      commitByPath('agenda', 'national')
      commitByPath('alerts/setShortFusedOnly', settings.hazards !== 'all')
      const region = DOMAINS.find(domain => domain.layer === settings.region)
      if (region) {
        commitByPath('extent', region?.extent || null)
      }
    }
  }

  function importBookmark (bookmark) {
    const settings = JSON.parse(atob(bookmark))
    commitByPath('baseMap', resolvePath(settings, 'base'))
    commitByPath('artccMap', resolvePath(settings, 'artcc'))
    commitByPath('cwaMap', resolvePath(settings, 'cwa'))
    commitByPath('countyMap', resolvePath(settings, 'county'))
    commitByPath('stateMap', resolvePath(settings, 'state'))
    commitByPath('rfcMap', resolvePath(settings, 'rfc'))
    commitByPath('menu/show', resolvePath(settings, 'menu'))
    commitByPath('menu/disable', resolvePath(settings, 'menudis'))
    commitByPath('persist/disableControls', resolvePath(settings, 'controldis'))
    commitByPath('setAnimating', resolvePath(settings, 'animating'))
    commitByPath('zoom', resolvePath(settings, 'agenda.zoom'))
    commitByPath('center', resolvePath(settings, 'agenda.center'))
    commitByPath('location', resolvePath(settings, 'agenda.location'))
    commitByPath('alerts/setShortFusedOnly', resolvePath(settings, 'shortFusedOnly'), {
      'storm-based': true,
      'hazards': false
    })
    commitByPath('alerts/opacity', resolvePath(settings, 'opacity.alerts'))
    commitByPath('local/opacity', resolvePath(settings, 'opacity.local'))
    commitByPath('local/stationOpacity', resolvePath(settings, 'opacity.localStations'))
    commitByPath('nationalMapOpacity', resolvePath(settings, 'opacity.national'))
    if (settings.agenda.id) {
      commitByPath('agenda', resolvePath(settings, 'agenda.id'))
      switch (settings.agenda.id) {
        case 'local':
          commitByPath('local/layerName', resolvePath(settings, 'agenda.layer'))
          commitByPath('local/station', resolvePath(settings, 'agenda.station'))
          commitByPath('local/filter', resolvePath(settings, 'agenda.filter'))
          store.dispatch('persist/addBookmarkSuppress', 'local')
          break
        case 'national':
          commitByPath('nationalMap', resolvePath(settings, 'agenda.layer'))
          store.dispatch('search/geolocateSelected', resolvePath(settings, 'agenda.center'))
          break
        case 'weather':
          commitByPath('nationalMap', resolvePath(settings, 'agenda.layer'))
          store.dispatch('search/geolocateSelected', resolvePath(settings, 'agenda.center'))
          break
      }
    }
    if (settings.agenda.custom) {
      allAgendas.push(settings.agenda.custom)
      commitByPath('agenda', settings.agenda.custom.id || 'custom')
    }
    log.debug('Bookmark applied to session state')
  }

  function exportBookmark (getters, state) {
    // Only for debugging; replace null with commented code
    const previousBookmark = null // getters.bookmark

    let bookmark = {
      agenda: {
        id: getters.agenda,
        center: limitCoordinatePrecision(getters.center),
        location: limitCoordinatePrecision(getters.location),
        zoom: getters.zoom
      },
      animating: getters.animating,
      base: getters.baseMap,
      artcc: getters.artccMapEnabled,
      county: getters.countyMapEnabled,
      cwa: getters.cwaMapEnabled,
      rfc: getters.rfcMapEnabled,
      state: getters.stateMapEnabled,
      menu: getters['menu/show'],
      shortFusedOnly: getters['alerts/shortFusedOnly'],
      opacity: {
        alerts: getters['alerts/opacity'],
        local: getters['local/opacity'],
        localStations: getters['local/stationOpacity'],
        national: getters['nationalMapOpacity']
      }
    }
    switch (getters.agenda) {
      case 'local':
        bookmark.agenda.filter = getters['local/filter']
        if (getters['local/station']) {
          bookmark.agenda.layer = getters['local/layerName']
          bookmark.agenda.station = getters['local/station']
        }
        break
      case 'national':
        bookmark.agenda.layer = getters['nationalMap']
        break
      case 'weather':
        bookmark.agenda.layer = getters['nationalMap']
        break
    }

    state.bookmark = btoa(JSON.stringify(bookmark))

    // Only for debugging if defined above
    if (previousBookmark) {
      compareSettings(bookmark, JSON.parse(atob(previousBookmark)))
    }

    // if initial view rendered and the bookmark has changed since initial render
    if (!getters['persist/suppressBookmark']) {
      return `v1_${getters.bookmark}`
    }
    return null
  }

  function compareSettings (newSettings, previousSettings, parentSetting) {
    for (let setting in newSettings) {
      if (!(setting in previousSettings)) {
        console.log(`Cannot compare setting: ${setting} not found`)
        continue
      }
      if (typeof newSettings[setting] === 'object') {
        compareSettings(newSettings[setting], previousSettings[setting], setting)
      } else {
        if (newSettings[setting] !== previousSettings[setting]) {
          let settingName = parentSetting ? `${parentSetting}.${setting}` : setting
          console.log(`New setting for ${settingName}: ${newSettings[setting]}, previously ${previousSettings[setting]}`)
        }
      }
    }
  }

  return store
}
