import * as log from '~/cmi/log'
import { Location } from '~/entities'
import { loadEsriReverseGeocoding } from '~/loaders'

function createDefaultState () {
  return {
    criteria: '',
    searching: false,
    selected: null
  }
}

export default {
  namespaced: true,
  state: createDefaultState(),
  mutations: {
    criteria (state, input) {
      if (typeof input !== 'string') {
        log.error('Invalid search criteria: ', input)
        return
      }
      state.criteria = input
    },
    selected (state, input) {
      if (typeof input === 'string') {
        state.selected = input
      } else if (input instanceof Location) {
        state.selected = input.name
      } else if (typeof input === 'undefined' || input === null || input === '') {
        state.selected = null
      } else {
        log.error('Selected location should be empty, a string, or a Location object')
      }
    },
    reset (state) {
      Object.assign(state, createDefaultState())
    },
    searching (state, input) {
      state.searching = Boolean(input)
    }
  },
  actions: {
    async geolocateSelected ({ commit }, input) {
      if (!(input instanceof Array)) {
        log.error('Selected geolocation should be an array')
        return false
      }
      const selectedLocation = await loadEsriReverseGeocoding({
        latitude: input[1],
        longitude: input[0]
      })
      commit('selected', selectedLocation.text)
    }
  },
  getters: {
    criteria: state => state.criteria,
    searching: state => state.searching,
    selected: state => {
      return state.selected
    }
  }
}
