<template>
  <div class="cmi-map-container">
    <div
      ref="ol-map"
      class="cmi-map"
    >
      <slot name="layers" />
    </div>
    <cmi-timer
      v-if="animationPrimaryFrames"
      :delay="animationFrameDelay"
      :enabled="_animationRunning"
      name="animation"
      @timer="_animate"
    />
    <cmi-timer
      v-if="_reloadDelay.valueOf() > 0"
      :delay="_reloadDelay"
      name="reload"
      @timer="reload"
    />
    <cmi-control-bar
      v-if="!disabled"
      :animation-frame-speed.sync="animationFrameSpeed"
      :animation-frame-delay-max="animationFrameDelayMax"
      :animation-running.sync="_animationRunning"
      :current-frame="animationFrameNumber + 1"
      :total-frames="animationPrimaryFrames ? animationPrimaryFrames.length : null"
      :status="controlbarStatus"
      :legend="legend"
      :min-zoom="minZoom"
      :max-zoom="maxZoom"
      :zoom="zoom"
      @gotoFirstFrame="_gotoFirstFrame"
      @gotoLastFrame="_gotoLastFrame"
      @gotoNextFrame="_gotoNextFrame"
      @gotoPreviousFrame="_gotoPreviousFrame"
      @zoomIn="_zoomIn"
      @zoomOut="_zoomOut"
    >
      <template
        v-if="controlbarStatus !== 'invalid' && controlbarStatus.length > 0"
        #info
      >
        <cmi-control-bar-info :status="controlbarStatus">
          <div
            v-for="(info, i) in controlBarInfo"
            :key="`info-${i}`"
          >
            {{ info }}
          </div>
        </cmi-control-bar-info>
      </template>
    </cmi-control-bar>
  </div>
</template>

<script>
import deepmerge from 'deepmerge'
import CmiControlBar from './controls/ControlBar.vue'
import Collection from 'ol/Collection'
import { DateTime } from 'luxon'
import { transformPoint, transformExtent } from '~/cmi/util/proj'
import { Map, View } from 'ol/index'
import { Group as LayerGroup } from 'ol/layer'

import * as proj from 'ol/proj'
import * as interactions from 'ol/interaction'
import * as converters from '../util/converters'
import * as log from '../log'
import * as validators from '../util/validators'

import 'ol/ol.css'

export default {
  components: {
    CmiControlBar
  },
  provide () {
    return {
      getOLMap: () => this.olMap,
      getOLContainer: () => this.olContainer,
      getOLView: () => this.olView,
      reload: {
        getLastReloadTime: () => this.lastReloadTime
      },
      window: {
        getAnimationPrimaryFrames: () => this.animationPrimaryFrames,
        getAnimationFrameNumber: () => this.animationFrameNumber,
        setAnimationPrimaryFrames: (frames, frameMax) => this.setAnimationPrimaryFrames(frames, frameMax)
      }
    }
  },
  props: {
    /**
     * Whether the animation is currently playing.
     *
     * @type {Boolean}
     */
    animationRunning: {
      type: Boolean,
      default: false,
      fallback: true
    },
    /**
     *  Evenly drops the number of frames for faster looping over larger time period
     */
    animationCompress: {
      type: Number,
      default: null
    },
    /**
     * The delay for updating frames when the map is animating.
     *
     * May be an ISO8601 duration string or a duration in milliseconds.
     *
     * @type {Number|String}
     */
    animationFrameDelayMultiplier: {
      type: [String, Number],
      validator: value => validators.convertibleToDuration(value),
      default: 'PT1S'
    },
    animationFrameDelayMax: {
      type: [Number],
      default: 4
    },
    animationFrameMax: {
      type: Number,
      default: 10,
      fallback: true
    },
    initialValues: {
      type: Object,
      default: () => {
        return {
          view: {
            center: [0, 0],
            extent: null,
            zoom: 4
          }
        }
      }
    },
    /**
     * Whether or not to display the map controls.
     *
     * @type {Boolean}
     */
    disabled: {
      type: Boolean,
      default: false
    },
    /**
     * Whether or not two clicks in quick succession should register as a
     * double-click.
     *
     * If set to false, the two clicks will register as separate single clicks.
     *
     * @type {Boolean}
     */
    doubleClickEvents: {
      type: Boolean,
      default: true
    },
    /**
     * The name of the legend to display.
     *
     * @todo Allow custom legends to be passed in
     * @type {String}
     */
    legend: {
      type: String,
      default: null
    },
    /**
     * How often the WMS data should be reloaded and frames recalculated.
     *
     * This value must be provided as an ISO8601 duration string or an integer
     * representing the delay in milliseconds.  For example, 'PT5M' would
     * trigger a reload every five minutes.
     *
     * By default, the value is set to null, which disables reloading.
     *
     * @type {Number|String}
     */
    reloadDelay: {
      type: [Number, String],
      validator: value => validators.convertibleToDuration(value),
      default: null
    },
    maxZoom: {
      type: Number,
      default: 10
    },
    minZoom: {
      type: Number,
      default: 4
    },
    timezone: {
      type: String,
      default: 'local'
    }
  },
  data () {
    return {
      olMap: null,
      olContainer: null,
      olView: null,
      animationFrameSpeed: 8,
      animationFrameNumber: 0,
      animationPrimaryFrames: null,
      lastReloadTime: DateTime.utc(),
      dataProjection: 'EPSG:4326', // how the cmi interacts with applications using the API
      projection: 'EPSG:3857',
      zoom: this.initialValues.view.zoom,
      cmi: {
        panTo: this.cmiPanTo,
        fitTo: this.cmiFitTo
      }
    }
  },
  computed: {
    controlbarStatus () {
      if (this.hasPrimaryFrames) {
        if (this.animationPrimaryFrames.length === 0) {
          return 'invalid'
        } else if (this.expiredPrimaryFrames) {
          return 'error'
        }
        return 'valid'
      }
      return 'valid'
    },
    controlBarInfo () {
      if (this.controlbarStatus === 'valid') {
        if (this.hasPrimaryFrames) {
          // timezone is validated in the persist store setter
          return [
            `${this.currentFrame.setZone(this.timezone).toFormat('M/dd/yy hh:mm a')}`,
            `${this.animationFrameNumber + 1} / ${this.animationPrimaryFrames.length}`
          ]
        }
        return [
          'Loading...'
        ]
      } else {
        if (this.expiredPrimaryFrames) {
          return [
            'Current Radar Not Available'
          ]
        }
        return [
          'Unknown Error'
        ]
      }
    },
    expiredPrimaryFrames () {
      return this.hasPrimaryFrames && this.lastFrame && Math.abs(this.currentFrame.diffNow('hours').hours) > 1
    },
    hasPrimaryFrames () {
      return this.animationPrimaryFrames && this.animationPrimaryFrames.length > 0
    },
    lastFrame () {
      return this.hasPrimaryFrames ? this.animationFrameNumber === this.animationPrimaryFrames.length - 1 : false
    },
    currentFrame () {
      return this.hasPrimaryFrames ? this.animationPrimaryFrames[this.animationFrameNumber] : null
    },
    /**
     * @type {luxon.Duration}
     */
    animationFrameDelay () {
      const delay = converters.convertToDuration(this.animationFrameDelayMultiplier)
      const multiplied = delay.toMillis() * (this.animationFrameDelayMax - this.animationFrameSpeed + 1)
      const multipliedDelay = converters.convertToDuration(multiplied)
      log.debug(`Speed set to ${multipliedDelay.toMillis()} milliseconds (${this.animationFrameDelayMultiplier}/${this.animationFrameDelayMax}/${this.animationFrameSpeed})`)
      return multipliedDelay
    },
    _animationRunning: {
      get () { return this.$animationRunning },
      set (value) { this.$animationRunning = value }
    },
    _animationFrameMax: {
      get () { return this.$animationFrameMax },
      set (value) { this.$animationFrameMax = value }
    },
    /**
     * @type {luxon.Duration}
     */
    _reloadDelay () {
      return converters.convertToDuration(this.reloadDelay)
    }
  },
  watch: {
    animationPrimaryFrames: {
      immediate: true,
      handler () {
        if (this.hasPrimaryFrames) {
          this.animationFrameNumber = this.animationPrimaryFrames.length - 1
        }
        if (Array.isArray(this.animationPrimaryFrames)) {
          this.$emit('frames', this.animationPrimaryFrames.map(frame => frame.toISO()))
        }
      }
    },
    animationFrameDelayMultiplier: {
      immediate: true,
      handler () {
        // Feature temporarily disabled
        // this.animationFrameDelayMultiplier = this.animationFrameDelayMultiplier
      }
    },
    animationFrameDelayMax: {
      immediate: true,
      handler () {
        this._animationFrameDelayMax = this.animationFrameDelayMax
      }
    }
  },
  mounted () {
    this.olMap.setTarget(this.$refs['ol-map'])
    if (this.initialValues.view.extent) {
      this.panToExtent(transformExtent(this.initialValues.view.extent, this.dataProjection, this.projection), 0)
    }
  },
  created () {
    this.olView = new View({
      zoom: this.zoom,
      maxZoom: this.maxZoom,
      minZoom: this.minZoom,
      center: transformPoint(this.initialValues.view.center, this.dataProjection, this.projection),
      projection: this.projection
    })

    this.olMap = new Map({
      controls: new Collection(),
      view: this.olView
    })
    this.olContainer = this.olMap.getLayers()
    this.olMap.on('display-layers', () => {
      log.debug('=== Map layers ===')
      this.listMap(this.olMap.getLayers())
    })
    this.olMap.on('singleclick', this._onSingleClick)
    this.olMap.on('dblclick', this._onDoubleClick)
    this.olMap.on('movestart', this._onMoveStart)
    this.olMap.on('moveend', this._onMoveEnd)
    // this.olMap.on('pointerdrag', this._onPointerDrag)
    // this.olMap.on('pointermove', this._onPointerMove)
    this._onMapCreated(this.olMap)
  },
  methods: {
    emitInterface () {
      this.$emit('interface', {
        _gotoLastFrame: () => this._gotoLastFrame()
      })
    },
    setAnimationPrimaryFrames (frames, frameMax) {
      if (frames) {
        let conditionedFrames = frames
        if (this.animationCompress) {
          conditionedFrames = conditionedFrames.filter((value, index) => {
            return (index + 1) % this.animationCompress !== 0
          })
        }
        const animationFrameMax = frameMax || this._animationFrameMax
        log.debug(`Selecting the last ${animationFrameMax} frames`)
        this.animationPrimaryFrames = conditionedFrames.slice(animationFrameMax * -1)
      } else {
        this.animationPrimaryFrames = null
      }
    },
    /**
     * Returns the currently visible map center.
     *
     * @returns {Number[]}
     */
    getCenter () {
      return this.olView.getCenter()
    },
    /**
     * Returns the currently visible map extent.
     *
     * @returns {Number[]}
     */
    getExtent () {
      return this.olView.calculateExtent(this.olMap.getSize())
    },
    /**
     * Returns the currently visible map rotation.
     *
     * @returns {Number}
     */
    getRotation () {
      return this.olView.getRotation()
    },
    /**
     * Returns the currently visible map zoom.
     *
     * @returns {Number}
     */
    getZoom () {
      return this.olView.getZoom()
    },
    /**
     * Only for debugging purposes to log mapping library layers to console
     */
    listMap (layers, indent = 1) {
      layers.forEach((layer) => {
        console.log('>'.repeat(indent), layer.get('who') || layer.values_.id)
        if (layer instanceof LayerGroup) {
          this.listMap(layer.getLayers(), indent + 1)
        }
      })
    },
    panTo ({ center = null, rotation = null, zoom = null, duration = null } = {}) {
      // Only pass values to OpenLayers that are defined/not null
      const args = Object.entries({ center, rotation, zoom }).reduce((acc, [key, value]) => {
        if (value !== null && value !== undefined) {
          acc[key] = value
        }
        return acc
      }, {})

      let options = {
        center: 'center' in args ? args.center : this.getCenter(),
        rotation: 'rotation' in args ? this._fromDegrees(args.rotation) : this.getRotation(),
        zoom: 'zoom' in args ? args.zoom : this.getZoom()
      }
      // Best not to include duration at all (resorting to library default) unless specifically set
      if ('duration' in args) {
        options.duration = args.duration
      }

      log.debug('Animating map view', {
        target: args,
        raw: options
      })
      this.olView.animate(options)
    },
    fitTo ({ bounds = null, zoom = null, duration = null } = {}) {
      if (bounds) {
        this.olView.fit(proj.transformExtent(bounds, this.dataProjection, this.projection), {
          duration,
          maxZoom: 10,
          padding: [30, 30, 30, 380]
        })
      }
    },
    panToExtent (value, duration = 1000) {
      log.debug(`Fitting map to extent ${value}`)
      this.olMap.getView().fit(value, {
        size: this.olMap.getSize(),
        duration: duration
      })
    },
    reload () {
      this.animationPrimaryFrames = null
      this.lastReloadTime = DateTime.utc()
      this.$emit('reload', this.lastReloadTime.toISO())
    },
    _gotoFrame (frameNumber, setRunning) {
      if (typeof setRunning !== 'undefined') {
        this.$emit('update:animationRunning', !!setRunning)
      }
      this.animationFrameNumber = frameNumber
    },
    _gotoNextFrame () {
      if (this.animationFrameNumber === this.animationPrimaryFrames.length - 1) {
        this._gotoFrame(0)
      } else {
        this._gotoFrame(this.animationFrameNumber + 1)
      }
    },
    _gotoPreviousFrame () {
      if (this.animationFrameNumber === 0) {
        this._gotoFrame(this.animationPrimaryFrames.length - 1)
      } else {
        this._gotoFrame(this.animationFrameNumber - 1)
      }
    },
    _gotoLastFrame () {
      if (this.animationPrimaryFrames) {
        this._gotoFrame(this.animationPrimaryFrames.length - 1)
      }
    },
    _gotoFirstFrame () {
      this._gotoFrame(0)
    },
    _animate () {
      this._gotoNextFrame()
    },
    _zoomIn () {
      // parent is updated via moveend event
      if (this.zoom < this.maxZoom) {
        this.zoom++
        this.olMap.getView().setZoom(this.zoom)
      }

      if (this.$tracker) {
        this.$tracker('event', {
          action: 'zoom',
          label: 'in'
        })
      }
    },
    _zoomOut () {
      // parent is updated via moveend event
      if (this.zoom > this.minZoom) {
        this.zoom--
        this.olMap.getView().setZoom(this.zoom)
      }

      if (this.$tracker) {
        this.$tracker('event', {
          action: 'zoom',
          label: 'out'
        })
      }
    },

    // Event handlers
    /**
     * Only for debugging purposes to see how mapping library layered layers
     * add @postrender to cmi-map component to enable
     */
    _postrender (event) {
      log.debug('> Map layers:')
      this.listMap(event.map.getLayers())
    },
    /**
     * This handler registers all clicks when double click is disabled.
     */
    _onClick (event) {
      if (this.doubleClickEvents) {
        return
      }

      const newEvent = this._transformMapBrowserEvent(event)
      this.$emit('click', newEvent)
    },
    /**
     * This handler only registers true single clicks when double click is enabled.
     */
    _onSingleClick (event) {
      if (!this.doubleClickEvents) {
        return
      }

      const newEvent = this._transformMapBrowserEvent(event)
      this.$emit('click', newEvent)
    },
    /**
     * This handler only registers true double clicks when double click is enabled.
     */
    _onDoubleClick (event) {
      if (!this.doubleClickEvents) {
        return
      }

      const newEvent = this._transformMapBrowserEvent(event)
      this.$emit('doubleclick', newEvent)
    },
    _onMapCreated (event) {
      this.olMap.getInteractions().clear()
      const defaultInteractions = interactions.defaults({
        altShiftDragRotate: false,
        mouseWheelZoom: true,
        dragPan: true
      })
      this.olMap.getInteractions().extend(defaultInteractions.getArray())

      const newEvent = this._transformMapEvent(event)
      this.$emit('created', newEvent, this.cmi)
    },
    _onMoveStart (event) {
      const newEvent = this._transformMapEvent(event)
      this.$emit('movestart', newEvent)
    },
    _onMoveEnd (event) {
      const newEvent = this._transformMapEvent(event)
      this.zoom = newEvent.zoom
      this.$emit('moveend', newEvent)
    },
    _onPointerDrag (event) {
      const newEvent = this._transformMapBrowserEvent(event)
      this.$emit('pointerdrag', newEvent)
    },
    _onPointerMove (event) {
      const newEvent = this._transformMapBrowserEvent(event)
      this.$emit('pointermove', newEvent)
    },
    _fromDegrees (degrees) {
      return degrees * Math.PI / 180.0
    },
    _fromLonLat (coord) {
      return proj.fromLonLat(coord, this.projection)
    },
    _toDegrees (radians) {
      return radians * 180.0 / Math.PI
    },
    _toLonLat (coord) {
      return proj.toLonLat(coord, this.projection)
    },
    _transformMapBrowserEvent (event) {
      return Object.assign(this._transformMapEvent(event), {
        coordinates: this._toLonLat(event.coordinate)
      })
    },
    _transformMapEvent (event) {
      let transformedEvent = {}
      if (event.frameState) {
        const extent = event.frameState.extent
        const viewState = event.frameState.viewState
        transformedEvent = deepmerge(transformedEvent, {
          center: proj.toLonLat(viewState.center, this.projection),
          extent: proj.transformExtent(extent, this.projection, this.dataProjection),
          rotation: this._toDegrees(viewState.rotation),
          zoom: viewState.zoom
        })
      }
      return transformedEvent
    },
    cmiPanTo ({ center = null, rotation = null, zoom = null, duration = null } = {}) {
      this.panTo({
        center: this._fromLonLat(center, this.projection),
        rotation,
        zoom,
        duration
      })
    },
    cmiFitTo ({ bounds = null, zoom = null, duration = null } = {}) {
      this.fitTo({ bounds, zoom, duration })
    }
  }
}
</script>

<style scoped>
.cmi-map-container {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
}

.cmi-map {
  height: 100%;
  width: 100%;
  overflow: hidden;
  display: block;
}
</style>
