<template>
  <div class="legend">
    <canvas
      v-show="legend"
      ref="canvas"
      :style="{ left: lengthOffset + 'px'}"
    />
    <div
      v-if="showDebugBins"
      class="debug"
    >
      <div
        v-for="(bin, index) in debugBins"
        :key="`debugBins${index}`"
        class="bin"
      >
        <div>{{ bin.label }}</div>
        <div :style="`background:${bin.startColor}`">
          {{ bin.startColor }}
        </div>
        <div :style="`background:${bin.endColor}`">
          {{ bin.endColor }}
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import * as log from '../../log'
import { LEGENDS } from '../../config'

export default {
  props: {
    legend: {
      type: String,
      default: null
    },
    vertical: {
      type: Boolean,
      default: false
    },
    lengthOffset: {
      type: Number,
      default: 0
    },
    widthOverride: {
      type: Number,
      default: null
    }
  },
  data () {
    return {
      canvas: null,
      context: null,
      symbolWidth: 10,
      symbolPadding: 4,
      labelSize: 11,
      labelColor: 'white',
      legendKey: null,
      maxLength: 500,
      showDebugBins: false,
      windowWidth: 0,
      legends: LEGENDS,
      legendMap: {
        bref_qcd: 'BNOB',
        cref_qcd: 'BNOB',
        pcpn_typ: 'PrecipFlag',
        neet_v18: 'NEET',
        sr_bref: 'BNOB',
        sr_bvel: 'BNOG',
        bdhc: 'BNOH',
        boha: 'BOHA',
        bdsa: 'BDTA',
        brefl: 'BNOB',
        bref1: 'BNOB',
        bvel: 'BNOG',
        stat: '_status'
      }
    }
  },
  computed: {
    width () {
      if (this.widthOverride !== null) {
        return this.widthOverride
      }
      return this.vertical ? 42 : 30
    },
    length () {
      let horizontalLength = this.windowWidth <= (this.maxLength + this.lengthOffset) ? (this.windowWidth - this.lengthOffset) : 500
      return this.vertical ? 400 : horizontalLength
    },
    debugBins () {
      if (this.legendMappedKey && this.legends[this.legendMappedKey]) {
        const steps = this.legends[this.legendMappedKey].steps
        if (steps && steps.length > 0) {
          let bins = []
          for (let i = 0; i < steps.length; i++) {
            bins.push({
              label: steps[i][0].trim().length > 0 ? steps[i][0] : '--',
              startColor: steps[i][1],
              endColor: steps[i][2]
            })
          }
          return bins
        }
      }

      return []
    },
    legendMappedKey () {
      if (this.legendKey && this.legendMap[this.legendKey]) {
        return this.legendMap[this.legendKey]
      }
      return undefined
    }
  },
  watch: {
    legend () {
      this.draw()
    },
    vertical () {
      this.build()
      this.draw()
    }
  },
  beforeDestroy () {
    window.removeEventListener('resize', this.getWindowWidth)
    window.removeEventListener('resize', this.getWindowHeight)
  },
  mounted () {
    window.addEventListener('resize', this.handleResize)
    this.getWindowWidth()

    this.init()
    this.build()
    this.draw()
  },
  methods: {
    build () {
      this.canvas.width = this.vertical ? this.width : this.length
      this.canvas.height = this.vertical ? this.length : this.width
      this.context.font = `${this.labelSize}px Calibri`
      this.context.textAlign = 'start'
    },
    clear () {
      this.context.clearRect(0, 0, this.canvas.width, this.canvas.height)
    },
    colorBetween (color1, color2, ratio) {
      var hex = function (x) {
        x = x.toString(16)
        return (x.length === 1) ? '0' + x : x
      }
      color1 = color1.substring(1, 7)
      color2 = color2.substring(1, 7)
      var r = Math.ceil(parseInt(color1.substring(0, 2), 16) * ratio + parseInt(color2.substring(0, 2), 16) * (1 - ratio))
      var g = Math.ceil(parseInt(color1.substring(2, 4), 16) * ratio + parseInt(color2.substring(2, 4), 16) * (1 - ratio))
      var b = Math.ceil(parseInt(color1.substring(4, 6), 16) * ratio + parseInt(color2.substring(4, 6), 16) * (1 - ratio))

      return '#' + hex(r) + hex(g) + hex(b)
    },
    draw () {
      if (this.legend) {
        this.legendKey = this.legend

        this.clear()
        this.context.fillStyle = 'rgba(50, 50, 50, 1)'
        this.context.fillRect(0, 0, this.canvas.width, this.canvas.height)

        if (this.legends[this.legendMappedKey]) {
          log.debug(`Drawing legend for ${this.legendKey} with ${this.legendMappedKey}`)
          this.drawSteps(this.legends[this.legendMappedKey].steps)
        } else {
          log.warn(`Cannot draw legend for ${this.legendKey}: key ${this.legendMappedKey} is undefined`)
        }
      }
    },
    drawSteps (steps) {
      let labelCoords = [0, 0]
      let labelCoordLengthPosition
      let labelCoordWidthPosition
      let stepLength = (this.vertical ? this.canvas.height : this.canvas.width) / steps.length
      let symbolCoords = [0, 0, 0, 0]
      let symbolCoordLengthStartPosition
      let symbolCoordLengthEndPosition

      if (this.vertical) {
        labelCoordLengthPosition = 1
        labelCoordWidthPosition = 0
        symbolCoords[0] = 0
        symbolCoords[2] = this.symbolWidth
        symbolCoordLengthStartPosition = 1
        symbolCoordLengthEndPosition = 3
      } else {
        labelCoordLengthPosition = 0
        labelCoordWidthPosition = 1
        symbolCoords[1] = 0
        symbolCoords[3] = this.symbolWidth
        symbolCoordLengthStartPosition = 0
        symbolCoordLengthEndPosition = 2
      }

      for (let i = 0; i < steps.length; ++i) {
        const step = {
          label: steps[i][0],
          startColor: steps[i][1],
          endColor: steps[i][2] ? steps[i][2] : steps[i][1]
        }

        if (this.reduceLabels()) {
          if (i === 0) {
            step.label = 'Low'
          } else if (i === (steps.length - 1)) {
            step.label = 'High'
          } else {
            step.label = ''
          }
        }

        symbolCoords[symbolCoordLengthStartPosition] = symbolCoords[symbolCoordLengthEndPosition]
        symbolCoords[symbolCoordLengthEndPosition] = stepLength * (i + 1)

        // Use gradient with same colors for solids to keep code simple
        let gradientCoords = this.setGradientDirection(symbolCoords)
        let gradient = this.context.createLinearGradient(gradientCoords[0], gradientCoords[1], gradientCoords[2], gradientCoords[3])

        gradient.addColorStop(0, step.startColor)
        gradient.addColorStop(1, step.endColor || step.startColor)
        this.context.fillStyle = gradient

        this.context.fillRect(symbolCoords[0], symbolCoords[1], symbolCoords[2], symbolCoords[3])

        let labelOffset = this.getLabelOffset(stepLength, step.label)
        labelCoords[labelCoordLengthPosition] = (stepLength * i) + labelOffset.length

        if (this.reduceLabels()) {
          // quick and dirty means to fit larger reduced labels
          if (i === 0) {
            labelCoords[labelCoordLengthPosition] += 10
          } else if (i === steps.length - 1) {
            labelCoords[labelCoordLengthPosition] -= 10
          }
        }

        labelCoords[labelCoordWidthPosition] = labelOffset.padding

        this.context.fillStyle = this.labelColor
        this.context.fillText(step.label, labelCoords[0], labelCoords[1])
      }
    },
    handleResize () {
      this.getWindowWidth()
      this.build()
      this.draw()
    },
    init () {
      this.canvas = this.$refs.canvas
      this.context = this.canvas.getContext('2d')
    },
    getLabelOffset (length, text) {
      let approxTextHeight = this.context.measureText('M').width // because there is no height in canvas measureText
      if (this.vertical) {
        return {
          length: length - approxTextHeight + 2,
          padding: this.symbolWidth + this.symbolPadding
        }
      } else {
        return {
          length: (length - this.context.measureText(text).width) / 2,
          padding: this.symbolWidth + this.symbolPadding + approxTextHeight
        }
      }
    },
    getWindowWidth (event) {
      this.windowWidth = document.documentElement.clientWidth
    },
    reduceLabels () {
      if (this.legendMappedKey && this.legends[this.legendMappedKey].allowReduce === false) {
        return false
      } else {
        return this.canvas.width < 360
      }
    },
    setGradientDirection (coords) {
      let directionCoords = [...coords]
      if (this.vertical) {
        directionCoords[0] = directionCoords[2] = 0
      } else {
        directionCoords[1] = directionCoords[3] = 0
      }
      return directionCoords
    }
  }
}
</script>

<style scoped>
.legend {
  display: block;
  position: relative;
}

.legend > canvas {
  display: block;
}

.legend > .debug {
  position: fixed;
  top: 0;
  right: 0;
  min-height: 200px;
  background: #c9c9c9;
}

.legend > .debug > .bin {
  display: flex;
  min-width: 300px;
}

.legend > .debug > .bin > div {
  flex: 1;
  text-align: center;
  white-space: nowrap;
  padding: 1px 6px;
}

.legend > .debug > .bin > div:first-child {
  flex: 0 50px;
  width: 50px;
}
</style>
