<template>
  <cmi-layer-group>
    <cmi-timeline-wms
      :id="`timeline-alerts-${layer}`"
      :layer="layer"
      :max-zoom="maxZoom"
      :min-zoom="minZoom"
      :opacity="opacity"
      :url="gisUrl(`wwa/${layer}`)"
      :suppress-extent="true"
      :tile-size="[512,512]"
      version="1.1.1"
      :z-index="zIndex"
      @change:active="changeActiveFrame"
      @change:last="changeLastFrame"
    />
    <cmi-layer-vector-shape
      :features="bboxAsGeoJson"
      :z-index="800"
    />
  </cmi-layer-group>
</template>

<script>
import { mapGetters, mapMutations } from 'vuex'

export default {
  props: {
    maxZoom: {
      type: Number,
      default: 10
    },
    minZoom: {
      type: Number,
      default: 0
    },
    opacity: {
      type: Number,
      default: 0.6
    },
    zIndex: {
      type: Number,
      required: true
    }
  },
  computed: {
    ...mapGetters('persist', [
      'gisUrl'
    ]),
    ...mapGetters('alerts', [
      'layer',
      'highlightBbox'
    ]),
    bboxAsGeoJson () {
      if (!this.highlightBbox) {
        return []
      }

      return [{
        type: 'Feature',
        geometry: {
          type: 'Polygon',
          coordinates: [[
            [this.highlightBbox[0], this.highlightBbox[1]],
            [this.highlightBbox[0], this.highlightBbox[3]],
            [this.highlightBbox[2], this.highlightBbox[3]],
            [this.highlightBbox[2], this.highlightBbox[1]],
            [this.highlightBbox[0], this.highlightBbox[1]]
          ]]
        },
        properties: {
          style: {
            fill: 'rgba(84, 114, 210, 0.2)',
            stroke: "white",
            width: 1
          }
        }
      }]
    }
  },
  methods: {
    ...mapMutations('alerts', [
      'setActiveLayerTime',
      'setLastLayerTime'
    ]),
    changeActiveFrame (frame) {
      this.setActiveLayerTime(frame ? frame.time : null)
    },
    changeLastFrame (frame) {
      this.setLastLayerTime(frame)
    }
  }
}
</script>
