<template>
  <LineChartGenerator
    :chart-data="data"
    :chart-options="options"
    :styles="styles"
    :plugins="plugins"
  />
</template>

<script>
import 'chartjs-adapter-luxon'
import { Line as LineChartGenerator } from 'vue-chartjs/legacy'
import {
  Chart as ChartJS,
  LineController,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  TimeScale,
  Filler
} from 'chart.js'

ChartJS.register(
  LineController,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  TimeScale,
  Filler
)

export default {
  components: {
    LineChartGenerator
  },
  props: {
    data: {
      type: Object,
      required: true
    },
    options: {
      type: Object,
      required: true
    },
    styles: {
      type: Object,
      required: true
    },
    plugins: {
      type: Array,
      default: null
    }
  }
}
</script>
