<template>
  <app-panel>
    <app-panel-option
      v-show="!focus"
      :label="kmlOptionLabel"
      @click="downloadKML(layerName)"
    >
      <template #icon>
        <span class="fa fa-download" />
      </template>
    </app-panel-option>
    <app-panel-option
      v-if="!focus && station"
      label="Clear selected radar"
      @click="clearSelectedStation"
    >
      <template #icon>
        <span class="fa fa-times" />
      </template>
    </app-panel-option>
    <app-panel-option-group
      v-show="!focus || focus === 'hazards' || focus === 'localradar' || focus === 'nationalradar' || focus === 'localstations'"
      label="Layer Options"
    >
      <template #icon>
        <span class="config-item-icon fa fa-tasks" />
      </template>
      <app-panel-hazards-option
        v-show="!focus || focus == 'hazards'"
      />
      <app-panel-local-radar-option
        v-show="station && (!focus || focus === 'localradar')"
        :agenda-bar-override="{
          product: true
        }"
      />
      <app-panel-national-radar-option
        v-show="!station && (!focus || focus === 'nationalradar')"
      />
      <app-panel-local-stations-option
        v-show="!focus || focus === 'localstations'"
      />
    </app-panel-option-group>
  </app-panel>
</template>

<script>
import AppPanel from '~/components/menu/Panel.vue'
import AppPanelOption from '~/components/menu/PanelOption.vue'
import AppPanelOptionGroup from '~/components/menu/PanelOptionGroup.vue'
import AppPanelHazardsOption from '~/components/menu/panels/options/Hazards.vue'
import AppPanelLocalRadarOption from '~/components/menu/panels/options/LocalRadar.vue'
import AppPanelLocalStationsOption from '~/components/menu/panels/options/LocalStations.vue'
import AppPanelNationalRadarOption from '~/components/menu/panels/options/NationalRadar.vue'

import { MAPS } from '~/config'
import { mapGetters } from 'vuex'

export default {
  components: {
    AppPanel,
    AppPanelOption,
    AppPanelOptionGroup,
    AppPanelHazardsOption,
    AppPanelLocalRadarOption,
    AppPanelNationalRadarOption,
    AppPanelLocalStationsOption
  },
  computed: {
    ...mapGetters('persist', [
      'gisBaseUrl'
    ]),
    ...mapGetters('local', [
      'filter',
      'layerName'
    ]),
    ...mapGetters('menu', [
      'focus'
    ]),
    localProducts () {
      if (this.filter) {
        return MAPS.local[this.filter]
      } else {
        return Object.keys(MAPS.local).reduce((allLocalProducts, type) => {
          allLocalProducts.push(...MAPS.local[type])
          return allLocalProducts
        }, [])
      }
    },
    kmlName () {
      if (this.localProducts && this.station) {
        for (let i = 0; i < this.localProducts.length; i++) {
          if (this.localProducts[i].name === this.layerName) {
            return `${this.station} ${this.localProducts[i].text}`
          }
        }
      }
      return null
    },
    kmlOptionLabel () {
      if (this.kmlName) {
        return `Download KML for ${this.kmlName}`
      } else if (this.station) {
        return 'KML not provided for this station'
      } else {
        return 'Select station to download KML'
      }
    },
    kmlLink () {
      if (this.localProducts && this.station) {
        return `${this.gisBaseUrl}/wms/kml?layers=${this.station.toLowerCase()}:${this.station.toLowerCase()}_${this.layerName.replace('.', '_')}`
      }
      return null
    },
    station: {
      get () { return this.$store.getters['local/station'] },
      set (value) { this.$store.commit('local/station', value) }
    },
    searchSelected: {
      get () { return this.$store.getters['search/selected'] },
      set (value) { this.$store.commit('search/selected', value) }
    }
  },
  methods: {
    downloadKML (name) {
      window.open(this.kmlLink, '_new')
      if (this.$tracker) {
        this.$tracker('event', {
          action: 'download',
          label: `local-${name}`
        })
      }
    },
    clearSelectedStation () {
      this.station = null
      this.searchSelected = null
    }
  }
}
</script>
